window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-hepato-hep-1"]={"block":"medcurso:medcurso-hepato-hep-1","label":"Medcurso · HEP 1","count":435,"questions":[{"id":"medcurso-hepato-hep-1-345441","number":"345441","sourceNumber":"345441","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Sobre as hepatites virais, assinale a alternativa INCORRETA:","options":{"A":"Os vírus causadores de todas as hepatites virais são vírus RNA.","B":"As hepatites virais A e E são transmitidas pela via fecal-oral.","C":"A vacina da hepatite B (recombinante) é recomendada, de forma universal, a partir do\nnascimento. A aplicação da 1ª dose nas\nprimeiras 12-24 horas de vida resulta em alta eficácia na\nprevenção da infecção transmitida verticalmente.","D":"A vacina hepatite A (inativada) purificada é indicada no calendário básico de vacinação da\ncriança do Ministério da Saúde."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-343839","number":"343839","sourceNumber":"343839","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Com relação à interpretação dos exames sorológicos para hepatites virais, analise os\ncritérios abaixo e correlacione com a conclusão de cada situação. I. HBsAg reagente, Anti-HBc igM\nreagente, Anti-HBc total não reagente, Anti-HBs não reagente. II. HBsAg reagente por mais de 6\nmeses, Anti-HBc IgM não reagente, Anti-HBc total reagente, Anti-HBs não reagente. III. HBsAg não\nreagente, Anti-HBc total reagente, Anti-HBs reagente. IV. HBsAg não reagente, Anti-HBc total não\nreagente, Anti-HBs reagente. ( ) Imunidade vacinal ao vírus da hepatite B. ( ) Hepatite B aguda. ( )\nHepatite B crônica. ( ) Imunidade por contato com o vírus da hepatite B. A sequência correta é:","options":{"A":"I, II, III, IV","B":"II, I, III, II","C":"IV, I, II, III","D":"IV, II, I, III"},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-251860","number":"251860","sourceNumber":"251860","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Teste Anti-HCV positivo com genótipo negativo sugere:","options":{"A":"Detecção de HCV no 1º mês de diagnóstico.","B":"Detecção de HCV no 2º mês de diagnóstico.","C":"Detecção de HCV no 3º mês de diagnóstico.","D":"Cura da hepatite C adquirida no passado."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-247146","number":"247146","sourceNumber":"247146","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"O diagnóstico sorológico da hepatite crônica pelo vírus B é confirmado pelo achado:","options":{"A":"HBsAg-, anti-HBc+, anti-HBs+.","B":"HBsAg+, anti-HBc-, anti-HBs+.","C":"HBsAg+, anti-HBc+, anti-HBs-.","D":"HBsAg-, anti-HBc+, anti-HBs-.","E":"HBsAg-, anti-HBc-, anti-HBs+."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-217719","number":"217719","sourceNumber":"217719","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente masculino, 10 anos de idade, previamente hígido, com quadro de febre\nautolimitada, seguida por icterícia e dor abdominal. Ao exame físico: icterícia e hepatomegalia\ndolorosa. Resultados de exames laboratoriais: ALT = 2.300 UI/ml; AST = 1.998 UI/ml; bilirrubina\ntotal = 7,3 mg/dl; bilirrubina direta = 5,2 mg/dl; bilirrubina indireta = 2,1 mg/dl. Os principais\nmarcadores sorológicos para a elucidação diagnóstica são:","options":{"A":"Anti-HAV lgM, HBsAg e anti-HBc lgM.","B":"Anti-HAV IgM, anti-HAV IgG, HBsAg, anti-HBc IgM e anti-HBc total.","C":"HBsAg, anti-HBc IgM e anti-HCV.","D":"Anti-HAV IgG, HBsAg, anti-HBc IgM e anti-HCV."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-182659","number":"182659","sourceNumber":"182659","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente masculino, 17 anos, ictérico e com desconforto abdominal, cujos resultados\nsorológicos evidenciaram: Anti-HAV IgM não reagente, Anti-HAV IgG reagente, HBsAg reagente,\nAnti-HBc total não reagente, Anti-HBc IgM reagente. Tais resultados permitem concluir que o\nquadro apresentado atualmente pelo paciente deve-se à infecção:","options":{"A":"Causada pelo vírus da Hepatite A (VHA).","B":"Aguda causada pelo vírus da Hepatite B.","C":"Pregressa causada pelo VHA.","D":"Crônica causada pelo vírus da Hepatite B."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-182669","number":"182669","sourceNumber":"182669","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Considere as características descritas abaixo: I. Estima-se que 3% da população\nmundial esteja infectada por esse vírus, e que\nentre 60% e 70% das pessoas infectadas\ndesenvolverão doença hepática crônica. II. Sua transmissão ocorre principalmente por via\nparenteral, por meio do contato com sangue contaminado, sendo a transmissão sexual pouco\neficiente e ocorre, sobretudo, em indivíduos com múltiplos parceiros e práticas sexuais de risco,\nsem uso de preservativo. III. A tecnologia capaz de diagnosticar tal vírus chegou aos bancos de\nsangue do Brasil em 1993. IV. O risco para infecção por esse vírus é maior em pessoas que\nreceberam transfusão de sangue e/ou hemoderivados antes de 1993; que usam drogas e que\ncompartilham seringas e agulhas, que possuem tatuagem ou piercing; ou que apresentam outras\nformas de exposição percutânea, sem os cuidados adequados de biossegurança - como\nprocedimentos odontológicos, podologia, manicure e pedicure. V. De modo geral, a hepatite aguda\ncausada por esse vírus apresenta evolução subclínica: cerca de 80% dos casos têm apresentação\nassintomática e anictérica. Tais características pertencem ao:","options":{"A":"VHA.","B":"VHB.","C":"VHC.","D":"VHD."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-183130","number":"183130","sourceNumber":"183130","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A hepatite de evolução fulminante ocorre mais comumente em:","options":{"A":"Recém-nascidos.","B":"Adolescentes.","C":"Pré-escolares.","D":"Escolares.","E":"Lactentes."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-159118","number":"159118","sourceNumber":"159118","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"O tratamento do Vírus da Hepatite C (VHC) é uma medida importante, pois além da\npossibilidade de erradicação do vírus, reduz a evolução para cirrose hepática e/ou\nhepatocarcinoma. Diante de um portador do VHC, adulto, masculino, virgem de tratamento, sem\nsinais clínicos ou laboratoriais de cirrose hepática, cuja elastografia hepática evidencie Metavir\n= F3\n(Fibrose hepática grau 3), o Ministério da Saúde preconiza como esquema terapêutico:","options":{"A":"Sofosbuvir e daclatasvir.","B":"Interferon peguilado e ribavirina.","C":"Interferon peguilado, telaprevir e ribavirina.","D":"Sofosbuvir, telaprevir ou ribavirina."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-159115","number":"159115","sourceNumber":"159115","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente assintomática traz os seguintes resultados sorológicos: Anti-HAV IgG\nreagente, Anti-HAV IgM não reagente, HBsAg não\nreagente, Anti-HBc total reagente, Anti-HBc IgM\nnão reagente, Anti-HBs reagente, Anti-HCV reagente. Com relação às hepatites virais pode-se\nafirmar que é possível que essa paciente seja portadora de:","options":{"A":"Hepatite A.","B":"Hepatite B.","C":"Hepatite C.","D":"Hepatite B e Hepatite C."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-135903","number":"135903","sourceNumber":"135903","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"MAS, feminina, 37 anos, cujo único sintoma relatado foi dispepsia, foi encaminhada ao\nserviço de infectologia devido aos seguintes resultados sorológicos: HBsAg não reagente. Anti-HBc\ntotal reagente, Anti-HBc IgM não reagente, Anti-HBs não reagente, Anti-HCV reagente. Com\nrelação a esse caso está INCORRETO afirmar:","options":{"A":"Trata-se de uma paciente portadora de hepatite C crônica;","B":"A paciente não desenvolveu imunidade contra o vírus da hepatite B;","C":"É possível que essa paciente seja portadora de hepatite B oculta;","D":"Nesse momento o ideal é aplicar vacina contra a hepatite B nessa paciente."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-135978","number":"135978","sourceNumber":"135978","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Os antivirais que foram introduzidos em 2015 pelo Ministério da Saúde no arsenal\nterapêutico para o tratamento da hepatite C crônica no Brasil foram:","options":{"A":"Adefovir e daclastavir;","B":"Daclatasvir e simdepresvir;","C":"Sofosbuvir, daclatasvir e simeprevir","D":"Simeprevir e adefovir"},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-108654","number":"108654","sourceNumber":"108654","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"<p>Paciente masculino, 46 anos, assintomático, realizou exames sorológicos\nadmissionais, pois passou em um concurso\npúblico. Os resultados foram: HBsAg: não reagente,\nanti-HBs: reagente, anti-HBc IgM: não reagente, anti-HBc total: reagente. Com relação a esse caso,\npode-se afirmar que o paciente:</p>","options":{"A":"É portador da infecção crônica pelo Vírus da Hepatite B (VHB).","B":"Apresenta imunidade vacinal ao VHB.","C":"Apresenta imunidade após infecção pelo VHB.","D":"Necessita realizar outros exames para confirmar a infecção VHB."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-108793","number":"108793","sourceNumber":"108793","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Homem, 51 anos, assintomático, traz resultado da sorologia anti-HCV reagente. Com\nrelação a esse caso, pode-se afirmar que:","options":{"A":"É portador da infecção crônica pelo Vírus da Hepatite C (VHC).","B":"Apresenta imunidade após infecção pelo VHC.","C":"Necessita realizar outro exame para confirmar ou não a infecção atual pelo VHC.","D":"Há uma remota possibilidade da manutenção da infecção pelo VHC."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-84532","number":"84532","sourceNumber":"84532","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente, 39 anos, masculino, portador de hepatite B, não cirrótico, sem comorbidades,\ntransaminases normais, perfil sorológico: Anti-HBc total positivo, Anti-HBc IgM negativo, HBeAg\nnegativo, Anti-HBe positivo, Anti-Delta negativo, AntiHCV negativo e Anti-HIV negativo. HBV-DNA\nquantitativo = 3.000 Ul/ml. Com relação ao tratamento do VHB, está CORRETO afirmar que:","options":{"A":"A droga de primeira escolha é o tenofovir;","B":"Neste caso o interferon é uma das possibilidades terapêuticas;","C":"Não se deve iniciar o tratamento específico neste caso, pois a carga viral está abaixo dos níveis\nrecomendados para o início da terapêutica;","D":"O entecavir é o antiviral mais recomendado neste caso;","E":"Para decidir sobre o tratamento deve-se antes realizar a biópsia hepática;"},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-66926","number":"66926","sourceNumber":"66926","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"<p>Paciente, 24 anos, feminino, procura atendimento trazendo os seguintes resultados\nde exames: HBsAG positivo, anti-HBc IgM negativo,\nanti-HBc total positivo, HBeAG negativo,\n\nanti-HBe positivo, anti-HCV negativo. Nesta situação, você informa que ela:</p>","options":{"A":"É portadora do vírus da Hepatite B e precisa fazer o exame para verificar se possui o vírus\ndelta.","B":"Está imunizada contra o vírus da Hepatite B.","C":"Deverá ser submetida ao PCR qualitativo para Hepatite C para confirmar ou não a infecção por\nesse vírus.","D":"Teve contato com o vírus da Hepatite B, mas não se tornou portadora do mesmo."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-66935","number":"66935","sourceNumber":"66935","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Com relação à hepatite C está INCORRETO afirmar:","options":{"A":"A presença de anti-HCV não define isoladamente a presença de infecção ativa e deve ser\ninterpretada como contato prévio com o HCV;","B":"O resultado reagente para anti-HCV deverá ser confirmado por testes moleculares para\ndetecção de ácidos nucleicos do HCV;","C":"Mesmo sendo portadores do HCV, indivíduos imunossuprimidos podem não apresentar\nsorologia reagente (anti-HCV), em virtude da\ndiminuição ou ausência da produção de anticorpos;","D":"Atualmente Interferon e Ribavirina são as únicas drogas aprovadas pela ANVISA (Agência\nNacional de Vigilância Sanitária) para o tratamento da hepatite C no Brasil."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-50090","number":"50090","sourceNumber":"50090","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente de 22 anos, sexo feminino, agente administrativo, busca atendimento devido a\num quadro de febre, cefaleia, mialgia e artralgia há 5 dias. Nega outras manifestações clínicas.\n\nPreviamente saudável. Reside em um bairro da periferia de Rio Branco - Acre e esteve no\nmunicípio de Mâncio Lima por 10 dias, tendo\nretornado a Rio Branco há 13 dias. Ao exame físico:\nsem anormalidades. Prova do laço negativa. Resultados laboratoriais: Hemograma: 3500\nleucócitos/mm³ de sangue e plaquetas: 65.000/mm³ de sangue; AST: 102; ALT: 167; ureia e\ncreatinina normais, sódio sérico e potássio sérico normais. Com relação ao CASO CLÍNICO está\nINCORRETO:","options":{"A":"Uma das hipóteses diagnósticas é malária, sendo importante solicitar pesquisa de Plasmodium.","B":"Trata-se de um caso suspeito de dengue, neste momento estadiado no grupo A, devendo ser a\nhidratação por via oral.","C":"Não está excluída a hipótese de ser um caso de leptospirose.","D":"Uma das possibilidades diagnósticas mais prováveis é hepatite viral aguda."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-50087","number":"50087","sourceNumber":"50087","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Qual das condutas abaixo está CORRETA, em relação ao atendimento a um\nrecém-nascido de mãe com HBsAG positivo?","options":{"A":"Imunoglobulina específica, vacina anti-Hepatite B, contraindicar a amamentação.","B":"Não permitir que a mãe amamente a criança até que a criança tenha recebido a imunoglobulina\nespecífica anti-Hepatite B.","C":"Não permitir que a mãe amamente a criança até que a criança tenha recebido a vacina\nanti-Hepatite B.","D":"Permitir a amamentação logo após o parto independente da criança ter recebido vacina e/ou\nimunoglobulina específica anti-Hepatite B."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-37088","number":"37088","sourceNumber":"37088","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"O sinal de mau prognóstico na Hepatite Viral Aguda é:","options":{"A":"Fosfatase alcalina acima de 3 vezes o valor normal","B":"Transaminases acima de 20 vezes o valor normal","C":"Tempo de protrombina muito alargado","D":"Esplenomegalia volumosa","E":"Icterícia persistente por mais de 2 meses"},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-29346","number":"29346","sourceNumber":"29346","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Com relação ao diagnóstico da infecção pelo vírus da hepatite C é CORRETO afirmar:","options":{"A":"A sorologia mostrando anti-HCV positivo confirma o diagnóstico","B":"O exame confirmatório usado na prática clínica é o PCR qualitativo","C":"A confirmação diagnóstica é feita pelo PCR quantitativo","D":"A biópsia hepática é imprescindível para confirmar a infecção","E":"A sorologia mostrando positividade do Anti-HBc confirma o diagnóstico"},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-343229","number":"343229","sourceNumber":"343229","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A porção N-terminal da NS3 codifica a serino-protease, responsável pelo\nprocessamento da poliproteína do HCV. Sendo correto que:","options":{"A":"A replicação do RNA viral é catalisada pela NS5B (RNA polimerase dependente de RNA). Tanto\na protease quanto a RNA polimerase são enzimas\nessenciais para a replicação do HCV e têm sido\nalvos de intensos estudos para o desenvolvimento de medicamentos.","B":"A replicação do RNA viral é catalisada pela NS5B (RNA polimerase dependente de RNA). Tanto\na protease quanto a RNA polimerase são enzimas\nnão essenciais para a replicação do HCV e têm\nsido alvos de intensos estudos para o desenvolvimento de medicamentos.","C":"A replicação do RNA viral é catalisada pela NS5B (RNA polimerase dependente de RNA). Tanto\na protease quanto a RNA polimerase são enzimas\nessenciais para a replicação do HCV e não têm\nsido alvos de intensos estudos para o desenvolvimento de medicamentos.","D":"A replicação do RNA viral nunca é catalisada pela NS5B (RNA polimerase dependente de RNA).\n\nTanto a protease quanto a RNA polimerase são enzimas essenciais para a replicação do HCV e\ntêm sido alvos de intensos estudos para o desenvolvimento de medicamentos."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-313426","number":"313426","sourceNumber":"313426","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A Hepatite Viral Crônica é assintomática na maioria dos casos. Assinale a alternativa\ncorreta.","options":{"A":"De modo geral, as manifestações clínicas não aparecem em fases adiantadas de acometimento\nhepático e, podem incluir fibrose, cirrose\nhepática, carcinoma hepatocelular e comprometimento de\noutros órgãos.","B":"De modo geral, as manifestações clínicas aparecem apenas em fases adiantadas de\nacometimento hepático e, podem incluir fibrose,\ncirrose hepática, carcinoma hepatocelular e não o\ncomprometimento de outros órgãos.","C":"De modo geral, as manifestações clínicas aparecem apenas em fases adiantadas de\nacometimento hepático e, podem incluir fibrose, cirrose hepática, carcinoma hepatocelular e\ncomprometimento de outros órgãos.","D":"De modo geral, as manifestações clínicas aparecem apenas em fases precoces de\nacometimento hepático e, podem incluir fibrose, cirrose hepática, carcinoma hepatocelular e\ncomprometimento de outros órgãos."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-313433","number":"313433","sourceNumber":"313433","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"As aminotransferases ? alanina aminotransferase ou transaminase glutâmico- -pirúvica\n(ALT ou TGP) e aspartato aminotransferase\nou transaminase glutâmico-oxalacética (AST ou TGO)\n\n? estão de acordo com o item correto:","options":{"A":"São marcadores sensíveis para detecção de lesão da cápsula hepática, porém, não são\nespecíficas para nenhum tipo de hepatite.","B":"São marcadores sensíveis para detecção de lesão do parênquima hepático, porém, não são\nespecíficas para nenhum tipo de hepatite.","C":"São marcadores sensíveis para detecção de lesão do parênquima hepático, são específicas\npara Hepatite B.","D":"São marcadores não sensíveis para detecção de lesão do parênquima hepático, são específicas\npara tipo de Hepatite Imune."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-252873","number":"252873","sourceNumber":"252873","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Homem, 22 anos de idade, procura atendimento médico por alterações de exames\nlaboratoriais de rotina. Assintomático. No\ninterrogatório sistemático, referiu ter notado olhos\namarelados, há cerca de 2 anos, por cerca de 2 dias, mas não procurou atendimento médico. Nega\ncomorbidades. Exame físico sem alterações. Exames laboratoriais com bilirrubinas totais de 2,89\nmg/dl, com bilirrubina indireta de 2,03 mg/dl; AST = 18 U/l (VR = 30); ALT = 16 U/L (VR = 30); FA =\n55 U/L (VR = 100); GGt = 20 U/L (VR = 60) AntiHCV não reagente; AntiHBs reagente; AntiHAV 1gG\nreagente Eletroforense de hemoglobina: HbA1 = 59%; HbA2 = 4%; HbS = 37%. A causa mais\nprovável para a elevação de bilirrubina deste paciente é:","options":{"A":"Anemia falciforme.","B":"Hepatite viral.","C":"Síndrome de Dubin-Johnson.","D":"Síndrome de Gilbert."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-252874","number":"252874","sourceNumber":"252874","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Homem, 22 anos de idade, procura atendimento médico por alterações de exames\nlaboratoriais de rotina. Assintomático. No\ninterrogatório sistemático, referiu ter notado olhos\namarelados, há cerca de 2 anos, por cerca de 2 dias, mas não procurou atendimento médico. Nega\ncomorbidades. Exame físico sem alterações. Exames laboratoriais com bilirrubinas totais de 2,89\nmg/dl, com bilirrubina indireta de 2,03 mg/dl; AST = 18 U/l (VR = 30); ALT = 16 U/L (VR = 30); FA =\n55 U/L (VR = 100); GGt = 20 U/L (VR = 60) AntiHCV não reagente; AntiHBs reagente; AntiHAV 1gG\nreagente Eletroforense de hemoglobina: HbA1 = 59%; HbA2 = 4%; HbS = 37%. Diante do quadro, o\ntratamento mais adequado neste momento é:","options":{"A":"Expectante.","B":"Entecavir.","C":"Hidroxiureia.","D":"Fenobarbital."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-249387","number":"249387","sourceNumber":"249387","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Os pacientes co-infectados pelo HIV que desenvolvem hepatite aguda pelo HBV têm\ncinco a seis vezes mais chance de se\ntornarem portadores crônicos do HBV, quando comparados a\nindivíduos soronegativos para o HIV. Assim, podemos aceitar que:","options":{"A":"A história da infecção pelo vírus da hepatite B é melhorada pelo HIV.","B":"A história natural da infecção pelo vírus da hepatite B não é alterada pelo HIV.","C":"A história natural da infecção pelo vírus da hepatite B é independente do HIV.","D":"A história natural da infecção pelo vírus da hepatite B é alterada pelo HIV."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-249388","number":"249388","sourceNumber":"249388","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Quando analisamos situações clínicas, de pacientes com doença aguda pelo HCV em\nfase inicial (até 30 dias) e pacientes imunodeprimidos e/ou dialíticos, pode não haver presença de\nanticorpos anti-HCV, em razão da incapacidade imunológica desses pacientes para produzir\nanticorpos. Podemos apenas aceitar que:","options":{"A":"Nessas situações, o diagnóstico da infecção pelo HCV não deverá ser realizado pela presença\ndo HCV-RNA, por método de biologia molecular.","B":"Nessas situações, o diagnóstico da infecção pelo HCV deverá ser realizado pela presença do\nHCV-RNA, por método de biologia molecular.","C":"Nessas situações, o diagnóstico da infecção pelo HCV deverá ser realizado pela ausência do\nHCV-RNA, por método de biologia molecular.","D":"Nessas situações, não é possível o diagnóstico da infecção pelo HCV por método de biologia\nmolecular."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-249392","number":"249392","sourceNumber":"249392","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Todo tratamento da hepatite B deverá ser interrompido, independentemente do\nesquema terapêutico, nas seguintes situações listadas\nabaixo, exceto:","options":{"A":"Ocorrência de eventos adversos importantes.","B":"Ausência de adesão ao tratamento.","C":"Identificação de situação que não demande substituição do tratamento.","D":"Identificação de situação que contra indique a modalidade de tratamento."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-249442","number":"249442","sourceNumber":"249442","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Todos os medicamentos de ação direta apresentam, em maior ou menor frequência,\nimportantes interações medicamentosas com diferentes fármacos. No caso do SOFOSBUVIR,\nsomente sendo incorreto que:","options":{"A":"não deve ser coadministrado com rifampicina, rifabutina, rifapentina, carbamazepina, fenitoína,\nfenobarbital, oxcarbamazepina, erva de são joão (Hypericum perforatum)","B":"da mesma forma, não se recomenda o tipranavir/ritonavir em associação ao sofosbuvir.","C":"não se conhecem as interações do fármaco com anticoncepcionais hormonais.","D":"não deve ser coadministrado com alguns antiarrítmicos, exceto a amiodarona"},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-249451","number":"249451","sourceNumber":"249451","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Recomenda-se que, ao início do tratamento ou durante o mesmo, todos os\nmedicamentos em uso pelo paciente sejam\navaliados em relação a possíveis interações\nmedicamentosas. Em particular, os pacientes coinfectados pelo HIV devem ser monitorados em\nrelação a possíveis interações dos Antivirais de Ação Direta com a terapia antirretroviral.\n\nSIMEPREVIR, indique qual item não procede.","options":{"A":"A medicação pode ser usada com carbamazepina, fenobarbital, fenitoína, eritromicina,\nclaritromicina, rifampicina, rifabutina, telitromicina,\nitraconazol, cetoconazol, posaconazol,\nfluconazol, voriconazol, dexametasona, cisaprida, erva de são joão (Hypericum perforatum) e\nsilimarina (Silybum marianum).","B":"Não deve ser utilizado com os antirretrovirais efavirenz, nevirapina, etravirina, tenofovir e a\nclasse de inibidores de protease.","C":"As dosagens de alguns antiarrítmicos, bloqueadores de canais de cálcio, estatinas, inibidores da\nfosfodiesterase tipo 5 e sedativos/ansiolíticos ? além da varfarina ? devem ser ajustadas.","D":"Recomenda-se a prévia consulta de potenciais interações."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-249277","number":"249277","sourceNumber":"249277","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"O tratamento com alfapeguinterferona e ribavirina para hepatite C podem ocasionar\ndiversas alterações laboratoriais e possíveis\nreações adversas que necessitam de monitoramento\nclínico e laboratorial mais rigoroso, com o objetivo de melhorar a adesão ao tratamento e a\nadequação das doses dos medicamentos. Sendo inadequado que:","options":{"A":"entre os principais eventos adversos do uso de alfapeguinterferona, destacam-se as alterações\nhematológicas (anemia, granulocitopenia , mas nunca a plaquetopenia).","B":"os sintomas se assemelham aos da gripe (dor de cabeça, fadiga, febre e mialgia) e sintomas\npsiquiátricos.","C":"o uso de alfapeguinterferona também pode desencadear disfunção tireoidiana e dermatológica.","D":"os novos medicamentos de ação direta, de forma geral, cursam eventualmente com a presença\nde cefaleia, fadiga, insônia, náuseas e prurido."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-212237","number":"212237","sourceNumber":"212237","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Dadas as afirmativas quanto às hepatites virais:\n\nI. A hepatite A é de transmissão fecal-oral, tem caráter benigno, pode evoluir para forma fulminante\nem < 1% dos casos.\n\nII. Cerca de 30?50% dos carcinomas hepatocelulares em portadores da hepatite B ocorrem na\nausência de cirrose, pois é um vírus oncogênico.\n\nIII. Cerca de 20% das mulheres grávidas infectadas pela hepatite E, rara no Brasil e comum na Ásia\ne África, desenvolvem uma forma grave da doença, principalmente as gestantes que se encontram\nno terceiro trimestre. Verifica-se que está(ão) CORRETA(S):","options":{"A":"I, II e III.","B":"II e III, apenas.","C":"I e III, apenas.","D":"II, apenas.","E":"I, apenas."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-216247","number":"216247","sourceNumber":"216247","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Assinale a causa medicamentosa mais comum como etiologia da falência hepática\nfulminante.","options":{"A":"Isoniazida.","B":"Tetraciclina.","C":"Anfetamina.","D":"Paracetamol."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-216261","number":"216261","sourceNumber":"216261","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Das hepatites, qual é a causa mais comum de falência hepática fulminante?","options":{"A":"Hepatite C.","B":"Hepatite B.","C":"Hepatite E.","D":"Hepatite A."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-216273","number":"216273","sourceNumber":"216273","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Assinale a alternativa INCORRETA.","options":{"A":"A hipoglicemia ocorre em 40% dos pacientes com falência hepática fulminante e tem etiologia\nmultifatorial.","B":"As infecções estão presentes em menos de 50% dos casos.","C":"O surgimento de edema cerebral é único da insuficiência hepática aguda, sendo causa\nfrequente de mortalidade.","D":"O edema cerebral se manifesta clinicamente quando a pressão intracraniana excede 30mmHg."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-216286","number":"216286","sourceNumber":"216286","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Qual alternativa apresenta fator de melhor prognóstico na falência hepática:","options":{"A":"intoxicação por paracetamol e infecção por vírus da hepatite A.","B":"infecção pelo vírus da hepatite B.","C":"infecção pelo vírus da hepatite C.","D":"infecção pelo vírus da hepatite E."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-216296","number":"216296","sourceNumber":"216296","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Qual é o fator mais importante para predizer a sobrevida nos pacientes com falência\nhepática fulminante?","options":{"A":"A etiologia.","B":"A função hepática.","C":"O grau de encefalopatia.","D":"Grau I de encefalopatia."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-183589","number":"183589","sourceNumber":"183589","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Estima-se que a hepatite C seja responsável por aproximadamente 700.000 óbitos\nanuais em consequência de suas complicações. Sendo complemente ADEQUADO, apenas, um\ndos itens abaixo. Indique-o.","options":{"A":"A agressão hepatocelular causada pelo HCV pode resultar em câncer hepático. Nas fases\navançadas da doença, o paciente pode\nevoluir para óbito em consequência de suas complicações,\nsobretudo o câncer hepático ? hepatocarcinoma, mas não carcinoma hepatocelular (CHC).","B":"A agressão hepatocelular causada pelo HCV não pode resultar em fibrose hepática, cirrose e\ncâncer hepático. Nas fases avançadas da doença, o paciente pode evoluir para óbito em\nconsequência de suas complicações, sobretudo a cirrose.","C":"A agressão hepatocelular causada pelo HCV pode resultar em fibrose hepática, cirrose, mas não\ncausa câncer hepático. Nas fases avançadas da\ndoença, o paciente pode evoluir para óbito em\nconsequência de suas complicações, sobretudo a cirrose.","D":"A agressão hepatocelular causada pelo HCV pode resultar em fibrose hepática, cirrose e câncer\nhepático. Nas fases avançadas da doença, o paciente pode evoluir para óbito em consequência de\nsuas complicações, sobretudo a cirrose e o câncer hepático ? hepatocarcinoma ou carcinoma\nhepatocelular (CHC)."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-183554","number":"183554","sourceNumber":"183554","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Estima-se que a hepatite C seja responsável por, aproximadamente, 700.000 óbitos\nanuais em consequência de suas complicações. Há, também, a possibilidade de transmissão\nvertical, em menor proporção dos casos, aponte o dado epidemiológico INCORRETO.","options":{"A":"Estima-se que 3% da população mundial esteja infectada pelo vírus da hepatite C e, que, entre\n60% e 70% das pessoas infectadas, desenvolverão doença hepática crônica, necessitando de\nassistência à saúde especializada e de alta complexidade.","B":"Sua transmissão ocorre, principalmente, por via parenteral, por meio do contato com sangue\ncontaminado.","C":"A transmissão sexual do HCV também tem sido relatada de forma esporádica em alguns grupos\npopulacionais.","D":"De forma geral, a transmissão sexual desse vírus é muito eficiente e ocorre, sobretudo, em\nindivíduos com múltiplos parceiros e práticas sexuais de risco, sem uso de preservativo."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-183574","number":"183574","sourceNumber":"183574","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A tecnologia capaz de diagnosticar o HCV chegou aos bancos de sangue do Brasil em\n1993. Cinco anos antes, em 1988 ? como forma de prevenir doenças de transmissão parenteral,\npara as quais não havia tecnologia de diagnóstico ? o governo federal proibira a doação de sangue\nremunerada (BRASIL, 2008, BRASIL, 1993, MINAS GERAIS, 1998). Aponte o item completamente\nCORRETO.","options":{"A":"Após a implementação dessas medidas de prevenção, muitas pessoas assintomáticas\ninfectadas pelo HCV perpetuaram a transmissão\ndo vírus por meio de doações de sangue, do\ncompartilhamento de objetos pessoais, seringas e agulhas para uso de drogas, por transmissão\nnosocomial e, eventualmente, por relações sexuais desprotegidas. Por isso, a hepatite C infectou\ngerações e populações específicas de forma desproporcional em todo o mundo.","B":"Até a implementação dessas medidas de prevenção, muitas pessoas sintomáticas infectadas\npelo HCV perpetuaram a transmissão do vírus por\nmeio de doações de sangue, do\ncompartilhamento de objetos pessoais, seringas e agulhas para uso de drogas, por transmissão\nnosocomial e, frequentemente por relações sexuais desprotegidas. Por isso, a hepatite C infectou\ngerações e populações específicas de forma desproporcional em todo o mundo.","C":"Até a implementação dessas medidas de prevenção, muitas pessoas assintomáticas infectadas\npelo HCV perpetuaram a transmissão do vírus por\nmeio de doações de sangue, do\ncompartilhamento de objetos pessoais, seringas e agulhas para uso de drogas, por transmissão\nnosocomial e, eventualmente, por relações sexuais desprotegidas. Por isso, a hepatite C infectou\ngerações e populações específicas de forma desproporcional em todo o mundo.","D":"Até a implementação dessas medidas de prevenção, muitas pessoas assintomáticas infectadas\npelo HCV perpetuaram a transmissão do vírus por\nmeio de doações de sangue, do\ncompartilhamento de objetos pessoais, seringas e agulhas para uso de drogas, por transmissão\nnosocomial e, muito frequentemente por relações sexuais desprotegidas. Por isso, a hepatite C\ninfectou gerações e populações específicas de forma proporcional em todo o mundo."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-182727","number":"182727","sourceNumber":"182727","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A decisão para recomendar uma vacina contra Hepatites envolve a avaliação dos riscos\nda doença, os benefícios da vacinação e os\nriscos associados à sua realização. Lembrando que as\nduas medidas mais efetivas para prevenir doenças infecciosas são as higiênicas e a imunização.\n\nSobre isso, assinale a alternativa INCORRETA:","options":{"A":"Quando ocorre na infância, a hepatite A desenvolve-se, em geral, de modo maligno, mas\nautolimitado. Contudo, quanto mais tardiamente ocorre a infecção, maior o risco de\ndesenvolvimento de formas graves e fulminantes. O esquema vacinal é composto de duas doses,\ndevendo haver um intervalo mínimo de 6 meses entre elas.","B":"A possibilidade de desenvolvimento da forma crônica da doença e de sua evolução para cirrose\ne hepatocarcinoma justifica a indicação universal da\nvacina.","C":"Deve-se vacinar todos os pacientes com doença renal crônica e hepatopatias.","D":"Também se recomenda a contactantes domiciliares de pessoas com infecção crônica pelo vírus\nda hepatite B."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-183595","number":"183595","sourceNumber":"183595","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"No Brasil, a hepatite C teve como formas preferenciais de transmissão o uso de drogas\ninjetáveis, hemodiálise, transfusão de sangue e hemoderivados e outros procedimentos médicos\ninvasivos, sobretudo até o início dos anos 90. Apenas um dos itens abaixo se apresenta\nCORRETO por completo, aponte-o.","options":{"A":"O risco para infecção pelo HCV é maior nas seguintes populações: pessoas que receberam\ntransfusão de sangue e/ou hemoderivados\nantes de 2003; que usam drogas e que compartilham\nseringas e agulhas; que possuem tatuagem ou piercing; ou que apresentam outras formas de\nexposição percutânea, sem os cuidados adequados de biossegurança ? como procedimentos\nodontológicos, podologia, manicure e pedicure.","B":"O risco para infecção pelo HCV é maior nas seguintes populações: pessoas que receberam\ntransfusão de sangue e/ou hemoderivados\nantes de 1993; que usam drogas e que compartilham\nseringas e agulhas; tatuagem ou piercing não apresenta alteração de incidência.","C":"O risco para infecção pelo HCV é maior nas seguintes populações: pessoas que receberam\ntransfusão de sangue e/ou hemoderivados\nantes de 1993; que usam drogas e que compartilham\nseringas e agulhas; que possuem tatuagem ou piercing; ou que apresentam outras formas de\nexposição percutânea, sem os cuidados adequados de biossegurança, mas procedimentos\nodontológicos, podologia, manicure e pedicure não causam contaminação.","D":"O risco para infecção pelo HCV é maior nas seguintes populações: pessoas que receberam\ntransfusão de sangue e/ou hemoderivados\nantes de 1993; que usam drogas e que compartilham\nseringas e agulhas; que possuem tatuagem ou piercing; ou que apresentam outras formas de\nexposição percutânea, sem os cuidados adequados de biossegurança ? como procedimentos\nodontológicos, podologia, manicure e pedicure ."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-183633","number":"183633","sourceNumber":"183633","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Globalmente, a epidemiologia da hepatite C também enseja maior vulnerabilidade entre\nindivíduos de determinadas gerações (GALBRAITH et al., 2015). Em recente análise da série\nhistórica brasileira, realizada pela Faculdade de Medicina da Universidade de São Paulo (FMUSP),\nobservou-se que o HCV acomete com maior frequência os indivíduos com mais de 40 anos de\nidade (AMAKU etal., 2016). Sendo INCORRETO, apenas, o seguinte dado:","options":{"A":"atualmente, as pessoas que usam drogas, injetáveis ou inaláveis, não mais constituem um grupo\nde risco no Brasil, embora em\n\nnúmero bem menor do que na Ásia, Europa e Estados Unidos.","B":"no entanto, a transmissão do vírus HCV não se restringiu a esses grupos.","C":"foram identificados outros mecanismos de transmissão: procedimentos de manicure e pedicure;\npiercings e tatuagens;\n\ntratamentos odontológicos; uso de seringas de vidro; endoscopia digestiva alta; e relações sexuais\ndesprotegidas.","D":"a doença também encontrou oportunidade de propagação em populações que apresentam\nfatores adicionais de vulnerabilidade,\n\ncomo transtornos mentais."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-183638","number":"183638","sourceNumber":"183638","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Grande parte das pessoas com hepatite C desconhece seu diagnóstico, e poucos\nsabem como ocorreu a transmissão ou que existe\ntratamento para a doença, sendo INCORRETO\nque,","options":{"A":"estima-se que existam entre 1,4 e 1,7 milhão de pessoas cronicamente infectadas pelo HCV no\nBrasil ? número significativamente inferior às estimativas da Organização Mundial da Saúde.","B":"no Brasil, aproximadamente 10 mil casos são notificados a cada ano.","C":"a epidemiologia da hepatite C não é homogênea no país.","D":"no início da epidemia, o desconhecimento da doença e a falta de exame para o diagnóstico das\ninfecções assintomáticas levaram à maior concentração da doença em indivíduos submetidos à\ntransfusão de sangue, mas não por hemoderivados."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-183621","number":"183621","sourceNumber":"183621","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"De 1999 a 2015, foram notificados 289.459 casos de hepatite C no Brasil. Do total de\ncasos notificados nesse período, 64,2% se\nconcentraram na região Sudeste, 24,2% na região Sul,\n5,6% na região Nordeste, 3,2% na região Centro-Oeste e 2,7% na região Norte. Em 2015, a taxa\nde detecção da região Sul foi de 14,1 casos para cada 100 mil habitantes, seguida pelo Sudeste\n(8,1), Norte (3,5), Centro-Oeste (1,9) e Nordeste (1,2) (BRASIL, 2016). NÃO sendo adequado o\nseguinte:","options":{"A":"a taxa de detecção de casos de hepatite C tem apresentado tendência de aumento ao longo dos\nanos, por regiões do país.","B":"de 2002 a 2009, a região Sudeste apresentou a maior taxa e, a partir de 2010, a região Sul\npassou a liderar o ranking.","C":"em quase toda a série histórica, a região Nordeste apresentou a menor taxa de detecção. Entre\nos casos confirmados de hepatite C,\naproximadamente 150.000 casos (58,8%) ocorreram entre\nhomens e 41,2% entre mulheres.","D":"apesar do número de casos entre homens ser inferior ao das mulheres, observa-se que essa\nproporção vem diminuindo ao longo dos anos."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-161173","number":"161173","sourceNumber":"161173","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Segundo Couinauld, a Hepatectomia Esquerda estendida inclui os seguintes\nsegmentos hepáticos:","options":{"A":"V, VI e VII.","B":"II, III e IV.","C":"II, III, IV e VIII.","D":"IV, V, VI, VII e VIII."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-152658","number":"152658","sourceNumber":"152658","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Na avaliação das enzimas hepáticas, podemos afirmar que:","options":{"A":"ALT é marcador de doença crônica.","B":"AST é marcador de doença aguda.","C":"ALT/AST expressam lesão hepatocelular.","D":"Duas alternativas estão corretas.","E":"Todas as alternativas estão incorretas."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-161314","number":"161314","sourceNumber":"161314","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A respeito de gestante primigesta de 22 anos, IG: 15 semanas, com sorologia positiva\npara hepatite B, assinale a alternativa\nCORRETA.","options":{"A":"Orientar parto cesáreo e inibir lactação.","B":"Recomendar parto via obstétrica (normal ou cesárea) e orientar profilaxia do RN com vacina e\nimunoglobulina.","C":"A transmissão vertical independe da via de parto e aleitamento e não há medidas de proteção\nao RN no pós-parto.","D":"Recomendar parto cesáreo, suspender aleitamento e orientar profilaxia do RN com vacina e\nimunoglobulina."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-131323","number":"131323","sourceNumber":"131323","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Na avaliação das enzimas hepáticas podemos afirmar que:","options":{"A":"ALT é marcador de doença crônica.","B":"AST é marcador de doença aguda.","C":"ALT/AST expressam lesão hepatocelular.","D":"Duas alternativas estão corretas.","E":"Todas as alternativas estão incorretas."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-131360","number":"131360","sourceNumber":"131360","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A icterícia com aumento de bilirrubina indireta está relacionada com todas as situações\nabaixo, EXCETO:","options":{"A":"Anemia hemolítica.","B":"Hipoalbuminemia.","C":"Nutrição parenteral prolongada.","D":"Síndrome de Rotor.","E":"Síndrome de Gilbert."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-110621","number":"110621","sourceNumber":"110621","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A icterícia com aumento de bilirrubina indireta está relacionada com todas as situações\nabaixo, EXCETO:","options":{"A":"Anemia hemolítica.","B":"Hipoalbuminemia.","C":"Nutrição parenteral prolongada.","D":"Síndrome de Rotor.","E":"Síndrome de Gilbert."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-108580","number":"108580","sourceNumber":"108580","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"<p>Paciente encaminhado ao ambulatório de gastroenterologia após doação de\nsangue. Observou-se que tinha dosagem de anti-HBc\nreagente, anti-HBs reagente e HBsAg não\nreagente. A melhor hipótese para justificar esses resultados é:</p>","options":{"A":"Hepatite aguda pelo vírus B.","B":"Hepatite crônica pelo vírus B.","C":"Portador assintomático do vírus B.","D":"Imunização natural pelo vírus B.","E":"Imunização contra o vírus B por vacinação."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-49616","number":"49616","sourceNumber":"49616","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Qual dos sinais abaixo não corresponde à insuficiência hepática?","options":{"A":"Telangiectasia.","B":"Circulação colateral porto-cava.","C":"Flapping.","D":"Ginecomastia.","E":"Aumento do TAP + INR."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-362488","number":"362488","sourceNumber":"362488","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente durante exames de rotina teve os seguintes resultados: HBSAG Negativo;\nAnti-HBS positivo; anti-HBC IGG positivo; anti-HBC\nIGM negativo. Qual o significado dos seguintes\nexames?","options":{"A":"Paciente portador crônico ativo.","B":"Paciente vacinado para hepatite B.","C":"Paciente com hepatite B crônica portado inativo.","D":"Paciente tem imunidade ao vírus da hepatite B por meio de contato com vírus da Hepatite B."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-327221","number":"327221","sourceNumber":"327221","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Sobre o vírus da hepatite C, podemos afirmar que:","options":{"A":"É um vírus DNA.","B":"É um vírus RNA.","C":"Sua forma crônica é menos prevalente que o vírus da hepatite B.","D":"Sua maior forma de contágio é por via sexual."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-298193","number":"298193","sourceNumber":"298193","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente durante exames de rotina teve os seguintes resultados: HBSAG Negativo;\n\nAnti-HBS positivo; anti-HBC IGG negativo; anti-HBC IGM negativo. Qual o significado dos seguintes\nexames?","options":{"A":"Paciente portador crônico ativo","B":"Paciente com hepatite B crônica portador inativo","C":"Paciente vacinado para hepatite B","D":"Paciente com mutação pré-core"},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-286717","number":"286717","sourceNumber":"286717","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Sobre o vírus da hepatite C, podemos afirmar que:","options":{"A":"É um vírus RNA.","B":"Sua forma crônica é menos prevalente que o vírus da hepatite B.","C":"É um vírus DNA.","D":"Sua maior forma de contágio é por via sexual."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-129747","number":"129747","sourceNumber":"129747","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"As alternativas sobre a hepatite B estão corretas, EXCETO:","options":{"A":"O tratamento atual conta com 90% de taxa de cura.","B":"Este vírus é transmitido facilmente por contato sexual.","C":"Embora 90 a 95% dos adultos que desenvolvem doença aguda eliminem o vírus, 5 a 10%\ndesenvolverão doença crônica.","D":"A administração imediata de globulina sérica imune aos contatos adequados é eficaz para evitar\ninfecção."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-87443","number":"87443","sourceNumber":"87443","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Um homem de 45 anos, natural de Manaus, submetido a exame de rotina para seguro\nde vida, apresenta TGO (AST) = 80 U/I (\nfaixa normal 9-40) e TGP (ALT) = 110 U/I ( faixa normal\n\n7-52). Relata uma história remota do uso de drogas injetáveis. Testes reagentes para anticorpos da\nhepatite C, anti-HBc total e anti-HBs da hepatite B. Testes não reagentes para anticorpos do vírus\nda imunodeficiência humana (HIV) e lgM anti-HAV da hepatite A. A Genotipagem do vírus da\nhepatite C (VHC) revela genótipo 1B; com RNA-HCV de 2.460.000 UI/mL. O hemograma é normal,\na contagem de plaquetas é 220.000/mm³ e o exame de ultrassom abdominal revelam aspectos\nmorfológicos ecográficos sugestivos de infiltração gordurosa (esteatose). Como você interpretaria\nos resultados dos exames deste paciente?","options":{"A":"Hepatite C, passado de hepatite B, sem HIV/AIDS e sem hepatite A.","B":"Hepatite C, passado de hepatite B, com HIV/AIDS e com hepatite A.","C":"Hepatite C, passado de hepatite B, com HIV/AIDS e sem hepatite A.","D":"Hepatite C, hepatite B sem HIV/AIDS e sem hepatite A.","E":"Hepatite C, hepatite B, com HIV/AIDS e com hepatite A."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-60880","number":"60880","sourceNumber":"60880","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente com 38 anos, traz exames solicitados por outro médico em janeiro de 2009:\nHBsAg reagente, anti-HBclgM não reagente, AST= 28(30), ALT= 45(35). Você os repete e as\nsorologias têm o mesmo resultado. As aminotransferases permanecem nos mesmos níveis\naproximadamente. Sobre o caso, marque a alternativa CORRETA:","options":{"A":"O anti-HDV é dispensável, mas o anti-HCV não","B":"Se o HBeAg for reagente, o anti-HBe também o será","C":"Como o anti-HBs deve ser não reagente, há indicação de vacinação.","D":"Não é necessário investigar hepatite B em familiares assintomáticos","E":"Ausência do HBcAg na biópsia hepática é esperado para o portador crônico inativo"},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hepato-hep-1-46704","number":"46704","sourceNumber":"46704","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Um jovem de 20 anos chega à consulta para investigar icterícia iniciada 05 dias antes.\nNo exame físico, não há sinais de hepatopatia\ncrônica ou encefalopatia hepática. Traz exames\nrealizados no pronto-socorro no primeiro dia que percebeu icterícia: AST= 500 (valor de referência\n4-30), ALT = 580 (VR: 10-40), bilirrubina total = 4,0 (VR < 1,2), bilirrubina direta = 3,0 (VR <\n4,0).\n\nSobre o caso, marque a alternativa verdadeira:","options":{"A":"O anti-HCV negativo garante ausência do vírus da Hepatite C, não havendo necessidade da\ncarga viral ou repetir a sorologia.","B":"Um anti-HBc IgG reagente mostra contato anterior com o vírus da Hepatite C, mas não diz se há\ninfecção atual.","C":"Se o HBsAG não for reagente, não é preciso pesquisar o vírus delta.","D":"Medicamentos não é causa provável das alterações clinicolaboratoriais.","E":"O resultado das sorologias para hepatites virais é necessário para fechar o diagnóstico de\nhepatite aguda."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-34169","number":"34169","sourceNumber":"34169","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A.H., sexo masculino, 20 anos, há aproximadamente 03 dias com mal-estar, hiporexia,\nastenia. Hoje evoluiu com febre, icterícia e\ncolúria. Ao exame físico: orientado, acordado,\ndeambulando sem dificuldades. Você solicita os seguintes exames: bilirrubina total = 7,0 (1,2), ALT\n\n= 3.200 (30), fosfatase alcalina = 300 (300). Sobre o caso, marque a alternativa verdadeira.","options":{"A":"Deve-se encaminhá-lo para a UTI, pois os exames refletem a gravidade do caso.","B":"Trata-se de um caso de hepatite fulminante.","C":"A dosagem de AST e GGT é fundamental para se estabelecer o diagnóstico.","D":"A investigação de uso dos medicamentos não é obrigatória.","E":"O anti-HBc lgM é um dos exames necessários dentro da investigação."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-26475","number":"26475","sourceNumber":"26475","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Adolescente de 15 anos, sexo feminino, procura ambulatório com história de ter sido\nvítima de abuso sexual há 48 horas. Houve intercurso anal e vaginal, sem a utilização de\npreservativo pelo agressor. A mãe não sabe da caderneta de vacinação e não lembra a data da\núltima vacina. Exames complementares revelam: Anti HAV IgG reagente e IgM não reagente.\n\nHbsAg não reagente e antiHBs reagente com baixa titulação.Qual a conduta mais apropriada para\nprofilaxia antiretrovíral e hepatites?","options":{"A":"Indicar profilaxia antiretrovíral e imunoglobulina hiperimune contra hepatite B;","B":"Indicar profilaxia antiretrovíral e uma dose de reforço da hepatite B;","C":"Indicar uma dose de reforço de vacina contra hepatite B e vacina contra hepatite A;","D":"Indicar profilaxia antiretrovíral e imunoglobulina hiperimune contra hepatite A e B;","E":"Não indicar profilaxia nenhuma"},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-7437","number":"7437","sourceNumber":"7437","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Em caso de criança com suspeita clínica de hepatite viral, os marcadores virais séricos\na serem solicitados para definição do agente\netiológico são:","options":{"A":"Anti-HVA IgM + AgHBs + Anti-HVC.","B":"Anti-HVA IgM + AgHBs + Anti-HBcIgG.","C":"Anti-HVA IgG + AntiHBs + Anti-HVC.","D":"Anti-HVA IgG + Anti-HVA IgM + AgHBs.","E":"Nenhuma delas."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-354377","number":"354377","sourceNumber":"354377","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Homem, 38 anos de idade, procura a UPA com queixas de icterícia, febre, mal-estar e\nnáuseas, há cerca de três dias. Refere ter retornado de uma viagem à praia há cerca de 30 dias.\nAo exame físico, apresenta-se lúcido e orientado, com icterícia 2+/4. Ausculta cardiorrespiratória\nsem alterações. Abdome com hepatomegalia e esplenomegalia discretas. Exame neurológico sem\nalterações. Os exames laboratoriais evidenciaram: Hb: 12g/dL, leucócitos: 9mil/mm³, plaquetas:\n200mil/mm³, AST: 900U/L (VR 40), ALT: 980U/L (VR40), Fosfatase alcalina: 400U/L (VR 150),\nGamaGT: 300U/L (VR 60), BT: 5,0mg/dL, RNI: 1,7. Diante do quadro clínico, quanto à gravidade do\npaciente, pode-se afirmar:","options":{"A":"A gravidade do caso é definida, principalmente, pela elevação de transaminases.","B":"A elevação importante de transaminases indica tratar-se de uma hepatite fulminante.","C":"A gravidade do caso é definida, principalmente, pela elevação de bilirrubinas e RNI.","D":"A elevação de bilirrubinas e RNI indicam tratar-se de uma hepatite fulminante."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-354401","number":"354401","sourceNumber":"354401","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Homem, 38 anos de idade, procura a UPA com queixas de icterícia, febre, mal-estar e\nnáuseas, há cerca de três dias. Refere ter retornado de uma viagem à praia há cerca de 30 dias.\nAo exame físico, apresenta-se lúcido e orientado, com icterícia 2+/4. Ausculta cardiorrespiratória\nsem alterações. Abdome com hepatomegalia e esplenomegalia discretas. Exame neurológico sem\nalterações. Os exames laboratoriais evidenciaram: Hb: 12g/dL, leucócitos: 9mil/mm³, plaquetas:\n200mil/mm³, AST: 900U/L (VR 40), ALT: 980U/L (VR40), Fosfatase alcalina: 400U/L (VR 150),\nGamaGT: 300U/L (VR 60), BT: 5,0mg/dL, RNI: 1,7. Com base nas informações, indique os exames\nque devem ser solicitados para definição etiológica:","options":{"A":"Anti-HAV IgM, Anti-EBV IgM, Anti-CMV IgM.","B":"Anti-HAV IgG e IgM, AgHBs, Anti-HCV.","C":"PCR qualitativo para HAV, HBV e HCV.","D":"Anti-HAV IgM, Anti-HBc IgM, PCR para HCV."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-354402","number":"354402","sourceNumber":"354402","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Homem, 38 anos de idade, procura a UPA com queixas de icterícia, febre, mal-estar e\nnáuseas, há cerca de três dias. Refere ter retornado de uma viagem à praia há cerca de 30 dias.\nAo exame físico, apresenta-se lúcido e orientado, com icterícia 2+/4. Ausculta cardiorrespiratória\nsem alterações. Abdome com hepatomegalia e esplenomegalia discretas. Exame neurológico sem\nalterações. Os exames laboratoriais evidenciaram: Hb: 12g/dL, leucócitos: 9mil/mm³, plaquetas:\n200mil/mm³, AST: 900U/L (VR 40), ALT: 980U/L (VR40), Fosfatase alcalina: 400U/L (VR 150),\nGamaGT: 300U/L (VR 60), BT: 5,0mg/dL, RNI: 1,7. Indique a conduta terapêutica inicial mais\napropriada para esse paciente:","options":{"A":"Administração de imunoglobulina.","B":"Iniciar terapia antiviral específica.","C":"Repouso e medidas de suporte.","D":"Encaminhamento para transplante hepático."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-34973","number":"34973","sourceNumber":"34973","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Na avaliação de um paciente com icterícia e desordens hepáticas hereditárias, é correto\nafirmar:","options":{"A":"A síndrome de Gilbert pode acometer até 7% da população e parece ser uma patologia\nautossômica dominante. Os níveis de bilirrubina são, em geral, menor que 3 mg%, não sendo\nindicado nenhum tratamento clínico.","B":"Na síndrome de Dubin-Johnson, que é uma doença autossômica recessiva, geralmente sem\nconsequências clínicas, existe predomínio\n\nde hiperbilirrubinemia indireta (não conjugada).","C":"A síndrome de Rotor é uma doença autossômica recessiva quando existe diminuição da\nexcreção de bilirrubina não conjugada, podendo levar a níveis plasmáticos de até 20 mg% de\nbilirrubina não conjugada.","D":"A síndrome de Crigler-Najjar tipo II geralmente leva o paciente à morte ainda na infância,\ncaracterizando-se por Kernicterus em quase todos os casos e apresentando biópsia hepática, em\ngeral, normal. A hiperbilirrubinemia é predominantemente à custa de bilirrubina conjugada.","E":"A síndrome de Crigler-Najjar tipo I caracteriza-se por biópsia hepática normal, usualmente não\nhá repercussão clínica por níveis mais altos de\nbilirrubina não conjugada e é compatível com vida\nnormal."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-27485","number":"27485","sourceNumber":"27485","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Mulher, 52 anos de idade, assintomática, em início de menopausa, apresentou em\nexames de rotina AST: 210 U/dl, ALT: 102\nU/dl, gamaglutamiltransferase: 92 U/l. Não faz reposição\nhormonal. Nega transfusões sanguíneas e tem apenas um parceiro sexual. O exame físico é\nnormal. Realizou exames adicionais que revelaram Hb: 13,2 g/dl, Ht: 37%, leucograma: 5.700\nleucócitos/mm³ sem desvios, glicemia: 82 mg/dl. Anti-HCV positivo, AgHBs negativo, índice de\nsaturação de transferrina: 40%, ferritina sérica: 850 mcg/dl. Anticorpos antimitocôndria,\nantimúsculo\nliso e anti-LKM negativos. Anticorpos anti-TPO positivos. O passo seguinte, entre os exames\ncomplementares, é:","options":{"A":"repetir o Anti-HCV.","B":"realizar PCR para o RNA do vírus C da hepatite.","C":"pesquisar mutações da hemocromatose.","D":"pesquisar anticorpos anti-DNA nativo e FAN.","E":"realizar biópsia hepática."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-27488","number":"27488","sourceNumber":"27488","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Mulher, 52 anos de idade, assintomática, em início de menopausa, apresentou em\nexames de rotina AST: 210 U/dl, ALT: 102\nU/dl, gamaglutamiltransferase: 92 U/l. Não faz reposição\nhormonal. Nega transfusões sanguíneas e tem apenas um parceiro sexual. O exame físico é\nnormal. Realizou exames adicionais que revelaram Hb: 13,2 g/dl, Ht: 37%, leucograma: 5.700\nleucócitos/mm³ sem desvios, glicemia: 82 mg/dl. Anti-HCV positivo, AgHBs negativo, índice de\nsaturação de transferrina: 40%, ferritina sérica: 850 mcg/dl. Anticorpos antimitocôndria,\nantimúsculo\nliso e anti-LKM negativos. Anticorpos anti-TPO positivos. Confirmando-se a principal suspeita\ndiagnóstica, o objetivo específico do tratamento será:","options":{"A":"redução dos índices de ferro sérico e hepático.","B":"normalização histológica ou redução da fibrose na biópsia.","C":"RNA viral inferior a 100 cópias, por, no mínimo, seis meses.","D":"normalização das aminotransferases por, no mínimo, quatro meses.","E":"negativação dos autoanticorpos e normalização das aminotransferases."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-27490","number":"27490","sourceNumber":"27490","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Mulher, 52 anos de idade, assintomática, em início de menopausa, apresentou em\nexames de rotina AST: 210 U/dl, ALT: 02\nU/dl, gamaglutamiltransferase: 92 U/l. Não faz reposição\nhormonal. Nega transfusões sanguíneas e tem apenas um parceiro sexual. O exame físico é\nnormal. Realizou exames adicionais que revelaram Hb: 13,2 g/dl, Ht: 37%, leucograma: 5.700\nleucócitos/mm³ sem desvios, glicemia: 82 mg/dl. Anti-HCV positivo, AgHBs negativo, índice de\nsaturação de transferrina: 40%, ferritina sérica: 850 mcg/dl. Anticorpos antimitocôndria,\nantimúsculo\nliso e anti-LKM negativos. Anticorpos anti-TPO positivos. A paciente evoluiu com equimoses e\npetéquias com relevo em MMII e nádegas, hematúria, edema de MMII e ascite. TA: 150 X 100\nmmHg. Os exames revelaram urina (sumário): hematúria com cilindros granulosos, hialinos e\nproteinúria; creatinina: 1,9 mg/dl, ureia: 72 mg/dl, K sérico: 5,7 mEq/l, albumina sérica: 1,4 g/dl,\nglobulina: 4,6 g/dl, colesterol total: 350 mg/dl, tempo de protrombina: 69%, dosagem de C3: 35\nmg/dl (VN 55 a 120 mg/dl), contagem de plaquetas: 103 mil/mm³. O tratamento preconizado para o\nmomento é usar:","options":{"A":"espironolactona e furosemida oral.","B":"metilprednisona oral.","C":"furosemida parenteral.","D":"metilprednisolona parenteral em pulsoterapia.","E":"paracentese com albumina EV."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-27493","number":"27493","sourceNumber":"27493","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Mulher, 52 anos de idade, assintomática, em início de menopausa, apresentou em\nexames de rotina: AST: 210 U/dl; ALT: 102\nU/dl; gamaglutamiltransferase: 92 U/l. Não faz reposição\nhormonal. Nega transfusões sanguíneas e tem apenas um parceiro sexual. O exame físico é\nnormal. Realizou exames adicionais que revelaram: Hb: 13,2 g/dl; Ht: 37%; leucograma: 5.700\nleuc/mm³ sem desvios; glicemia: 82 mg/dl. Anti-HCV positivo; AgHBs negativo; índice de saturação\nde transferrina: 40%; ferritina sérica: 850 mcg/L. Anticorpos antimitocôndria, antimúsculo liso e\n\nanti-LKM negativos. Anticorpos anti-TPO positivos. A alteração renal mais provável, nesse caso, é:","options":{"A":"Glomerulonefrite membranoproliferativa por imunocomplexos.","B":"Glomerulonefrite proliferativa difusa por imunocomplexos.","C":"Glomeruloesclerose segmentar focal com esclerose arteriolar.","D":"Lesão glomerular mínima com alteração dos podócitos mesangiais.","E":"Rins estruturalmente normais com reabsorção tubular exacerbada de sódio."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-27497","number":"27497","sourceNumber":"27497","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Mulher, 52 anos de idade, assintomática, em início de menopausa, apresentou em\nexames de rotina AST: 210U/dl, ALT:102U/dl\ngamaglutamiltransferase: 92U/l. Não faz reposição\nhormonal. Nega transfusões sanguíneas e tem apenas um parceiro sexual. O exame físico é\nnormal. Realizou exames adicionais que revelaram Hb: 13,2g/dl, Ht: 37%, leucograma: 5.700\nleucócitos/mm³ sem desvios, glicemia: 82mg/dl. AntiHCV positivo, AgHBs negativo, índice de\nsaturação de transferrina: 40%, ferritina sérica: 850mcg/dl. Anticorpos antimitocôndria, antimúsculo\nliso e anti-LKM negativos. Anticorpos anti-TPO positivos. Após uma semana de tratamento, o\nionograma e a hemogasimetria arterial da paciente apresentaram os seguintes achados, pH: 7,3,\nPC02: 31mmHg, HC03: 19mEq/l, PaO²: 83mmHg, BE: -12, sódio sérico: 137mEq/l, CI: 104mEq/l, K:\n6,0mEq/l. O distúrbio metabólico apresentado é:","options":{"A":"acidose mista respiratória e metabólica, descompensada.","B":"acidose respiratória crônica agudizada, descompensada.","C":"acidose respiratória com alcalose metabólica, compensadas.","D":"acidose metabólica descompensada.","E":"acidose metabólica com alcalose respiratória, descompensada."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-27498","number":"27498","sourceNumber":"27498","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Mulher, 52 anos de idade, assintomática, em início de menopausa, apresentou em\nexames de rotina AST: 210 U/dl, ALT: 102\nU/dl gamaglutamiltransferase: 92 U/l. Não faz reposição\nhormonal. Nega transfusões sanguíneas e tem apenas um parceiro sexual. O exame físico é\nnormal. Realizou exames adicionais que revelaram Hb: 13,2 g/dl, Ht: 37%, leucograma: 5.700\nleucócitos/mm³ sem desvios, glicemia: 82 mg/dl. AntiHCV positivo, AgHBs negativo, índice de\nsaturação de transferrina: 40%, ferritina sérica: 850 mcg/dl. Anticorpos antimitocôndria,\nantimúsculo\nliso e anti-LKM negativos. Anticorpos anti-TPO positivos. A paciente passou a apresentar onda T\napiculada no ECG. A medida mais imediata é:","options":{"A":"bicarbonato de sódio EV.","B":"nebulização com fenoterol.","C":"resina de troca iônica e manitol oral (sorcal).","D":"gluconato de cálcio EV.","E":"solução de glicose e insulina EV."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-343379","number":"343379","sourceNumber":"343379","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A porção N-terminal da NS3 codifica a serino-protease, responsável pelo\nprocessamento da poliproteína do HCV. Sendo correto que:","options":{"A":"A replicação do RNA viral é catalisada pela NS5B (RNA polimerase dependente de RNA). Tanto\na protease quanto a RNA polimerase são enzimas\nessenciais para a replicação do HCV e têm sido\nalvos de intensos estudos para o desenvolvimento de medicamentos.","B":"A replicação do RNA viral é catalisada pela NS5B (RNA polimerase dependente de RNA). Tanto\na protease quanto a RNA polimerase são enzimas\nnão essenciais para a replicação do HCV e têm\nsido alvos de intensos estudos para o desenvolvimento de medicamentos.","C":"A replicação do RNA viral é catalisada pela NS5B (RNA polimerase dependente de RNA). Tanto\na protease quanto a RNA polimerase são enzimas\nessenciais para a replicação do HCV e não têm\nsido alvos de intensos estudos para o desenvolvimento de medicamentos.","D":"A replicação do RNA viral nunca é catalisada pela NS5B (RNA polimerase dependente de RNA).\n\nTanto a protease quanto a RNA polimerase são enzimas essenciais para a replicação do HCV e\ntêm sido alvos de intensos estudos para o desenvolvimento de medicamentos."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-281850","number":"281850","sourceNumber":"281850","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Os testes moleculares quantitativos também são conhecidos como testes de Carga\nViral (CV), sendo correto o item:","options":{"A":"São incapazes de quantificar o número de cópias de genomas virais circulantes em um paciente.","B":"São capazes de quantificar o número de cópias de genomas virais circulantes em um paciente.","C":"São capazes de quantificar o número de cópias de genomas virais não circulantes em um\npaciente.","D":"São capazes de qualificar o tipo e úmero de cópias de genomas não virais circulantes em um\npaciente."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-281856","number":"281856","sourceNumber":"281856","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"O anti-HCV é um marcador que indica contato prévio com o vírus. Sendo adequado\nque:","options":{"A":"Isoladamente, um resultado reagente para o anticorpo permite diferenciar uma infecção resolvida\nnaturalmente de uma infecção ativa.","B":"Isoladamente, um resultado reagente para o anticorpo permite diferenciar uma infecção resolvida\nnaturalmente de uma infecção inativa.","C":"Isoladamente, um resultado não reagente para o anticorpo sempre permite diferenciar uma\ninfecção resolvida naturalmente de uma infecção ativa.","D":"Isoladamente, um resultado reagente para o anticorpo não permite diferenciar uma infecção\nresolvida naturalmente de uma infecção ativa."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-249971","number":"249971","sourceNumber":"249971","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Considerando que os vírus das hepatites B, C e Delta e o HIV apresentam formas de\ntransmissão em comum, podemos apenas determinar como adequado o item:","options":{"A":"Co-infecção com outros vírus não pode ocorrer e afetar de forma significativa a história natural\nda doença.","B":"A presença concomitante desses agentes infecciosos não agrava, somente acelera a evolução\nda hepatite.","C":"A presença concomitante desses agentes infecciosos agrava a atividade necro inflamatória.","D":"O principal fator associado à evolução para cronicidade da infecção pelo vírus da hepatite B é a\nvia que a infecção ocorre."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-249976","number":"249976","sourceNumber":"249976","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A biópsia hepática é útil no diagnóstico de outras doenças hepáticas concomitantes\ncom hepatite viral crônica ? como a doença\ngordurosa, que impacta de maneira significativa a\nevolução dos casos e o manejo dos pacientes. Podemos assim, indicar como errado o item:","options":{"A":"A biópsia hepática é o exame padrão-ouro para a avaliação da fibrose hepática.","B":"É excepcional na avaliação de hepatite B crônica e reservada aos casos em que não há dúvidas\nna indicação de tratamento.","C":"Biópsia pode ser realizada com diferentes técnicas e tipos de agulha.","D":"A biópsia hepática é um procedimento invasivo, que requer uma estrutura apropriada."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-250024","number":"250024","sourceNumber":"250024","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"O tratamento da hepatite C crônica está indicado para todos os adultos (?18 anos),\nsendo correto o item:","options":{"A":"Co-infectados pelo HIV, dependentemente do estadiamento de fibrose hepática ou da contagem\nde células LT-CD4+.","B":"Co-infectados pelo HIV, independentemente do estadiamento de fibrose hepática somente da\ncontagem de células LT-CD4+.","C":"Co-infectados pelo HIV, independentemente do estadiamento contagem de células LT-CD4+ e\nsim da fibrose hepática.","D":"Co-infectados pelo HIV, independentemente do estadiamento de fibrose hepática ou da\ncontagem de células LT-CD4+."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-157648","number":"157648","sourceNumber":"157648","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Dentre as relações dos diabéticos com a Hepatite Viral, pacientes com hepatite C\napresentam a seguinte característica. Indique-a.","options":{"A":"Ocorre menor prevalência de DM tipo 2.","B":"Por outro lado, pacientes com DM têm pequena prevalência de sorologia positiva para hepatite\nC.","C":"Pacientes com DM apresentam risco de contrair o vírus da hepatite B duas vezes maior que na\npopulação geral.","D":"Por isso, atualmente, recomenda-se vacinação para essa doença viral em casos selecionados\nde pacientes com DM."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-139789","number":"139789","sourceNumber":"139789","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"As hepatites virais são doenças de transmissão inter-humana, distribuídas\nuniversalmente, que podem apresentar evolução\naguda ou crônica, constituindo-se em importante\nproblema de saúde pública no mundo. Desse modo, aponte a alternativa em que a afirmação esteja\nINCORRETA.","options":{"A":"A infecção pelo vírus da hepatite pode se apresentar desde formas assintomáticas até\nsintomáticas com evolução grave (hepatite\nfulminante). Um aspecto importante é a ausência de\nicterícia em 50% dos casos de hepatite, e a possibilidade de evolução para cronicidade existe nas\nhepatites causadas pelo vírus B e C.","B":"A infecção pelo vírus da hepatite C é disseminada fundamentalmente pela exposição parenteral\nao sangue ou derivados sangue de pessoas\ninfectadas, sendo o uso de drogas injetáveis o\nprincipal modo de transmissão da hepatite C atualmente.","C":"O vírus da hepatite B é transmitido através do sangue ou fluídos corpóreos como: secreção\ncervical e vaginal, sêmen, leite\n\nmaterno e saliva de pessoas portadoras do vírus. O sangue é o que contém a mais alta\nconcentração do vírus. A transmissão\nperinatal, ainda que não eficiente, é possível e ocorre quase\nsempre no momento do parto ou logo após, e a transmissão transplacentária do VHB é descrita\nembora de ocorrência incomum.","D":"O vírus da hepatite B é transmitido através do sangue ou fluídos corpóreos como: secreção\ncervical e vaginal, sêmen, leite\n\nmaterno e saliva de pessoas portadoras do vírus. O sangue é o que contém a mais alta\nconcentração do vírus. A transmissão\n\nperinatal, ainda que não eficiente, é possível e ocorre quase sempre no momento do parto ou logo\napós, e a transmissão\n\ntransplacentária do VHB é descrita embora de ocorrência incomum."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-173008","number":"173008","sourceNumber":"173008","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Um profissional de saúde de 25 anos, assintomático, teve sua primeira doação de\nsangue negada devido a alterações em sorologia\npara hepatite B (anti-HBc total positivo). Teve\ntodas as demais sorologias negativas. Repetiu exames ambulatorialmente após seis semanas\ntendo os resultados descritos na tabela abaixo. Transaminases e demais resultados de provas de\nfunção e lesão hepática dentro dos limites da normalidade. Ele acredita ter realizado vacinação\npara hepatite B, mas não recorda se completou esquema vacinal ou tem comprovação. Não\nrecorda nenhum evento clínico compatível com hepatite. Qual exame deve ser solicitado para\navaliação do caso?","options":{"A":"Carga viral DNA-PCR agora.","B":"Anti-HBc IgG após 6 meses.","C":"Anti-HBs após 6 meses.","D":"HBeAg agora."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":["question_bank/media/medcurso/medcurso-hepato-hep-1/173008.png"],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-65781","number":"65781","sourceNumber":"65781","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente de 38 anos, sexo masculino, é encaminhado pelo banco de sangue com\nanti-HCV reagente. Não apresenta quaisquer queixas. O exame físico é normal. Hemograma,\neletrólitos, funções renal e hepática estão inalterados. São então realizados o Imunoblot (RIBA),\nque foi REAGENTE, e o PCR, que foi NÃO REAGENTE. Qual a melhor conduta para este\npaciente?","options":{"A":"Realizar biópsia hepática.","B":"Encaminhar ao transplante.","C":"Iniciar tratamento antiviral.","D":"Solicitar genotipagem viral.","E":"Fazer acompanhamento clínico."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-65788","number":"65788","sourceNumber":"65788","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"<p>Mulher de 32 anos, com hepatite C crônica, apresenta pápulas violáceas,\npruriginosas, com fina rede de linhas\nbranco-acinzentadas na superfície, acometendo as faces\nflexoras dos punhos. As unhas das mãos estão acometidas, sobretudo as dos polegares. Qual o\ndiagnóstico mais compatível com este quadro? (VER IMAGEM)</p>","options":{"A":"Psoríase.","B":"Líquen plano.","C":"Pitiríase rósea.","D":"Dermatofitose.","E":"Eczema disidrótico."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":["question_bank/media/medcurso/medcurso-hepato-hep-1/65788.png"],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-141582","number":"141582","sourceNumber":"141582","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Na interpretação dos marcadores sorológicos de um paciente com Hepatite B aguda,\nqual é o primeiro marcador que aparece e declina a níveis indetectáveis em até 24 semanas?","options":{"A":"Anti-HBc IgM.","B":"Anti-HBs.","C":"HbsAg.","D":"HbeAg."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-30877","number":"30877","sourceNumber":"30877","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Mulher, 36 anos, com comportamento sexual de risco (múltiplos parceiros, sem\npreservativo), comparece com icterícia, dor\nabdominal e TGP elevada (20 vezes o valor normal) de\ninício há duas semanas. Qual dos exames séricos abaixo é habitualmente solicitado e pode ser\npositivo nessa fase da doença?","options":{"A":"HBsAg.","B":"HBcAg.","C":"Anti-HBe.","D":"Anti-HBc IgG.","E":"Anti-HBs."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-22927","number":"22927","sourceNumber":"22927","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente de 25 anos procurou atendimento com médico com náuseas, vômitos,\nicterícia, dor abdominal em hipocôndrio D e\nfebre de instalação há cinco dias. Durante esse período\nfez uso de paracetamol e vários anti-inflamatórios para alívio da febre. Os exames laboratoriais\nmostram: HBsAg negativo, Anti-HbC IgM negativo, Anti-HbC IgG positivo, Anti-Hbs positivo,\n\nanti-HVA IgG positivo, TGP 500 U/L (limite superior da normalidade: 40 U/L), TGO 346 U/L (limite\nsuperior da normalidade: 36 U/L). O ultrassom abdominal é compatível com hepatomegalia. Qual o\ndiagnóstico mais provável?","options":{"A":"Hepatite B crônica com mutação pré-core","B":"Hepatite B crônica sem mutação pré-core","C":"Hepatite B aguda na fase de janela imunológica","D":"Hepatite B curada e hepatite de outra causa","E":"Hepatite A"},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-29486","number":"29486","sourceNumber":"29486","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Dora, 34 anos, profissional do sexo, procurou seu médico de família para apresentar o\nresultado de exames: Anti-HIV 1 e 2 negativos, Anti-HVC positivo, HBsAg negativo, Hbe Ag\nnegativo, Anti-Hbs negativo, VDRL negativo, FTA-ABS positivo. Baseando-se no caso acima e em\nseus conhecimentos, o médico de família pode afirmar, exceto:","options":{"A":"Dora provavelmente é susceptível à hepatite B, sendo indicada a vacinação;","B":"Os resultados HbsAg negativo, Anti-Hbs negativo, HbeAg negativo podem ser encontrados na\nfase convalescente;","C":"O resultado anti-HVC indica contato prévio com o vírus da hepatite C, mas não define se recente\nou tardio;","D":"Nenhuma das alternativas acima."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-24368","number":"24368","sourceNumber":"24368","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Em relação às hepatites virais, é CORRETO afirmar:","options":{"A":"Cerca de 10% dos casos de hepatite A pode evoluir para a forma fulminante.","B":"Atualmente, a principal forma de transmissão da hepatite C são as transfusões sanguíneas.","C":"Lamivudina, entecavir, adefovir e interferon-alfa são fármacos utilizados por via oral para\ntratamento da hepatite B.","D":"A hepatite E apresenta formas graves em gestantes, mas não evolui para cronificação."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hepato-hep-1-22958","number":"22958","sourceNumber":"22958","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Qual a interpretação para uma criança que apresenta o seguinte padrão sorológico\npara hepatite B: HBsAg negativo; HBeAg negativo;\nanti-HBcIgM negativo; anti-HBe negativo e\nanti-HBs positivo?","options":{"A":"Hepatite B crônica","B":"Janela imunológica","C":"Hepatite B aguda","D":"Paciente vacinado","E":"Paciente não imunizado"},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-27736","number":"27736","sourceNumber":"27736","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"O diagnóstico de hepatite pelo vírus D utiliza como teste confirmatório a pesquisa de\nanti-VHD e como teste de triagem a pesquisa de:","options":{"A":"HBs Ag","B":"anti-HBS","C":"IgM anti-HBC","D":"IgM anti-HVA","E":"anti-HVC"},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-25371","number":"25371","sourceNumber":"25371","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Numa criança com suspeita clínica de hepatite viral aguda, os marcadores virais séricos\nmais apropriados a serem solicitados para definição diagnóstica do agente etiológico, dentre as\nopções abaixo, são:","options":{"A":"Anti HVA IgM + AgHBs + anti HBs","B":"Anti HVA IgM + AgHBs + anti HBcIgM","C":"Anti HVA IgG + Anti HBs + anti HBc total","D":"Anti HVA IgG + Anti HBe + AgHBs","E":"Anti HVA IgM + anti HBc total + Anti HBs"},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-25354","number":"25354","sourceNumber":"25354","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Das hepatites abaixo, qual a que tem maior potencial de evoluir para forma crônica?","options":{"A":"Infecção pelo vírus da hepatite B adquirida na infância","B":"Infecção pelo vírus da hepatite B adquirida na fase adulta","C":"Infecção pelo vírus da hepatite C","D":"Infecção pelo vírus da hepatite E","E":"Infecção pelo vírus da hepatite D"},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-7300","number":"7300","sourceNumber":"7300","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Indivíduo de 42 anos de idade, masculino, procura ambulatório porque foi doar sangue\ne disseram que estava com hepatite. Nega\nsintomatologia. Ao exame físico: Bom estado geral,\ndiscretamente ictérico, raras telangiectasias em tronco. Fígado a 1 cm do RCD, duro discretamente\ndoloroso. Exames Laboratoriais: Leucócitos: 5500/mm3 ; Plaquetas: 160.000/mm3; Hb: 15g/dL;\nHt:34%. AST: 12U/L; ALT: 8 U/L; GGT: 20U/L; FA: 60U/L Bilirrubina Total: 2.4mg/dL .Testes\nSorológicos para Hepatite: anti-HVA IgM negativo; anti-HVA IgG positivo; Ag HBs positivo; Anti-HBs\nnegativo; Anti -HBc positivo; Ag Hbe negativo; Anti-HVC positivo. O paciente, nesse caso, tem\ninfecção ativa por:","options":{"A":"VHA e VHB.","B":"VHA e VHC.","C":"VHB.","D":"VHA e VHB e VHC.","E":"VHB e VHC."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hepato-hep-1-7283","number":"7283","sourceNumber":"7283","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Qual a interpretação para uma criança que apresenta o seguinte padrão sorológico\npara hepatite B: HBsAg negativo; HBeAg negativo;\nanti-HBcIgM negativo; anti-HBe negativo e\nanti-HBs positivo?","options":{"A":"Hepatite B crônica.","B":"Paciente vacinado.","C":"Hepatite B aguda.","D":"Janela imunológica.","E":"Paciente não imunizado."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-9107","number":"9107","sourceNumber":"9107","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Com relação à hepatite B em gestantes é CORRETO afirmar que:","options":{"A":"A gestação favorece o aparecimento da infecção e agrava o curso da doença.","B":"O diagnóstico diferencial deve ser feito com icterícia colestática, colelitíase, síndrome HELLP,\nfígado gorduroso agudo da gestação e farmacotoxicidade.","C":"Os neonatos infectados pelo vírus têm 30% de chance de se tornarem portadores crônicos.","D":"Se o rastreamento no pré-natal com o HBsAg for positivo, os recém nascidos devem receber\napenas a imunoglobulina imediatamente após o\nnascimento."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-9040","number":"9040","sourceNumber":"9040","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Hugo, 18 anos, acometido pela hepatite B, apresenta HBsAg, HBeAg e Anti-HBc (IgM),\napós seis meses de infecção. Com esses\ndados, qual foi a conclusão de seu médico?","options":{"A":"Hugo pode estar com infecção crônica e com sinais de replicação viral.","B":"Hugo apresenta sinais de vacinação prévia.","C":"Hugo encontra-se no fim da fase replicativa.","D":"Hugo encontra-se em fase de convalescença de infecção recente e com imunidade comprovada."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-15974","number":"15974","sourceNumber":"15974","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Em relação à hepatite pelo vírus A, podemos afirmar, corretamente que:","options":{"A":"em geral é aguda e autolimitada, evoluindo para resolução clínica, bioquímica e histológica de\nforma rápida.","B":"a principal via de transmissão é parenteral.","C":"a vacina contra hepatite A não demonstra segurança nem efetividade.","D":"a presença do anti-VHA IgG no soro indica infecção aguda ou recente pelo VHA.","E":"o quadro clínico típico se caracteriza pelo início insidioso de achados inespecíficos."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hepato-hep-1-365653","number":"365653","sourceNumber":"365653","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A Secretaria de Estado da Saúde de São Paulo registrou, de janeiro até o dia 4 de julho\ndeste ano, 1.602 casos e 123 óbitos causados por infecções pelos diferentes vírus causadores de\nhepatite. Esses números apresentam uma tendência de queda no número de mortes relacionadas\nregistradas nos últimos cinco anos. (Disponível em\nhttps://bvsms.saude.gov.br/bvs/publicacoes/manual_tecnico_diagnostico_hepatites_virais.pdf.\n\nAcesso em: 7 dez. 2023). Um dos motivos da redução da prevalência e da gravidade das hepatites\nvirais crônicas é a (o)","options":{"A":"vacinação contra a hepatite C.","B":"aumento da eficácia dos novos interferons.","C":"erradicação da hepatite E no Brasil.","D":"eficácia dos antivirais contra a hepatite C."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-365652","number":"365652","sourceNumber":"365652","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Durante exames admissionais, um paciente realizou sorologias para hepatites virais\ncom os resultados a seguir. Acerca da orientação nesse caso, assinale a alternativa correta.","options":{"A":"Dose de reforço da vacina contra a hepatite A","B":"Tratamento contra a hepatite A crônica","C":"Solicitação de pesquisa de HCV-RNA","D":"Esclarecimento a respeito de imunidade por vacina contra a hepatite A e C"},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":["question_bank/media/medcurso/medcurso-hepato-hep-1/365652.png"],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-262184","number":"262184","sourceNumber":"262184","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Uma paciente de 30 anos de idade, empregada doméstica, natural do Piauí, procedente\nde Samambaia (DF), gestante de 12 semanas, é\nencaminhada ao hepatologista em virtude de\nexame sorológico positivo para hepatite B. Verificam-se AgHBs (antígeno hepatite B) anti-HBc total\n\n? (anticorpo contra antígeno core hepatite B) anti- HBs (anticorpo contra vírus da hepatite B).\nConsiderando esse caso clínico e com base nos conhecimentos médicos correlatos, julgue o item a\nseguir. AgHBs positivo, anti-HBc total positivo e anti-HBs negativo ? infectada atualmente por\nhepatite B.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-262424","number":"262424","sourceNumber":"262424","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Determinado senhor de 61 anos de idade, morador de Manaus (AM), marcou consulta\nmédica por quadro clínico de mal-estar,\ncefaleia, astenia, icterícia, náuseas e vômito há uma\nsemana. O médico, após anamnese e exame físico, solicitou exames laboratoriais, incluindo\nsorologias para hepatites virais, receitou sintomáticos e agendou o retorno. No retorno, os exames\napresentaram anti-HAV IgG reagente, anti-HAV IgM não reagente, HBsAg reagente, anti-HBs Ag\nnão reagente, anti-HBc total reagente, anti-HBc IgM reagente, HBeAg reagente, anti-HBe não\nreagente e anti-HCV não reagente. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. O paciente já teve infecção pelo vírus da hepatite A ou foi\nvacinado de hepatite A. Segundo a Sociedade Brasileira de Imunizações, são indicadas duas doses\nda vacina, com intervalo de seis meses entre as doses.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-262185","number":"262185","sourceNumber":"262185","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Uma paciente de 30 anos de idade, empregada doméstica, natural do Piauí, procedente\nde Samambaia (DF), gestante de 12 semanas, é\nencaminhada ao hepatologista em virtude de\nexame sorológico positivo para hepatite B. Verificam-se AgHBs (antígeno hepatite B) anti-HBc total\n\n? (anticorpo contra antígeno core hepatite B) anti- HBs (anticorpo contra vírus da hepatite B).\nConsiderando esse caso clínico e com base nos conhecimentos médicos correlatos, julgue o item a\nseguir. AgHBs negativo, anti-HBc total negativo e anti-HBs positivo ? vacinada para hepatite B.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-262425","number":"262425","sourceNumber":"262425","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Determinado senhor de 61 anos de idade, morador de Manaus (AM), marcou consulta\nmédica por quadro clínico de mal-estar, cefaleia, astenia, icterícia, náuseas e vômito há uma\nsemana. O médico, após anamnese e exame físico, solicitou exames laboratoriais, incluindo\nsorologias para hepatites virais, receitou sintomáticos e agendou o retorno. No retorno, os exames\napresentaram anti-HAV IgG reagente, anti-HAV IgM não reagente, HBsAg reagente, anti-HBs Ag\nnão reagente, anti-HBc total reagente, anti-HBc IgM reagente, HBeAg reagente, anti-HBe não\nreagente e anti-HCV não reagente. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. Para tratamento desse paciente que tem hepatite B com HBeAg\nreagente, a alfapeginterferona está indicada pelo protocolo do Ministério da Saúde do Brasil, com\naplicação subcutânea semanal, por 48 semanas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-262426","number":"262426","sourceNumber":"262426","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Determinado senhor de 61 anos de idade, morador de Manaus (AM), marcou consulta\nmédica por quadro clínico de mal-estar,\ncefaleia, astenia, icterícia, náuseas e vômito há uma\nsemana. O médico, após anamnese e exame físico, solicitou exames laboratoriais, incluindo\nsorologias para hepatites virais, receitou sintomáticos e agendou o retorno. No retorno, os exames\napresentaram anti-HAV IgG reagente, anti-HAV IgM não reagente, HBsAg reagente, anti-HBs Ag\nnão reagente, anti-HBc total reagente, anti-HBc IgM reagente, HBeAg reagente, anti-HBe não\nreagente e anti-HCV não reagente. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. O diagnóstico sorológico da hepatite Delta baseia-se na detecção\nde anticorpos anti-HDV IgG em paciente com suspeita de exposição recente para o agente\ninfeccioso. Pacientes portadores de hepatite B, residentes em áreas endêmicas (como é o caso do\npaciente descrito) ou com antecedente epidemiológico correspondente, são candidatos a\ninvestigação.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-262187","number":"262187","sourceNumber":"262187","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Uma paciente de 30 anos de idade, empregada doméstica, natural do Piauí, procedente\nde Samambaia (DF), gestante de 12 semanas, é\nencaminhada ao hepatologista em virtude de\nexame sorológico positivo para hepatite B. Verificam-se AgHBs (antígeno hepatite B) anti-HBc total\n\n? (anticorpo contra antígeno core hepatite B) anti- HBs (anticorpo contra vírus da hepatite B).\nConsiderando esse caso clínico e com base nos conhecimentos médicos correlatos, julgue o item a\nseguir. AgHBs negativo, anti-HBc total positivo e anti-HBs negativo - contágio prévio por hepatite\nC.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-262427","number":"262427","sourceNumber":"262427","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Determinado senhor de 61 anos de idade, morador de Manaus (AM), marcou consulta\nmédica por quadro clínico de mal-estar, cefaleia, astenia, icterícia, náuseas e vômito há uma\nsemana. O médico, após anamnese e exame físico, solicitou exames laboratoriais, incluindo\nsorologias para hepatites virais, receitou sintomáticos e agendou o retorno. No retorno, os exames\napresentaram anti-HAV IgG reagente, anti-HAV IgM não reagente, HBsAg reagente, anti-HBs Ag\nnão reagente, anti-HBc total reagente, anti-HBc IgM reagente, HBeAg reagente, anti-HBe não\nreagente e anti-HCV não reagente. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. O médico, após análise dos exames sorológicos, faz diagnóstico\nde que o paciente tem hepatite B aguda.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-262188","number":"262188","sourceNumber":"262188","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Uma paciente de 30 anos de idade, empregada doméstica, natural do Piauí, procedente\nde Samambaia (DF), gestante de 12 semanas, é\nencaminhada ao hepatologista em virtude de\nexame sorológico positivo para hepatite B. Verificam-se AgHBs (antígeno hepatite B) anti-HBc total\n\n? (anticorpo contra antígeno core hepatite B) anti- HBs (anticorpo contra vírus da hepatite B).\nConsiderando esse caso clínico e com base nos conhecimentos médicos correlatos, julgue o item a\nseguir. AgHBs negativo, anti-HBc total negativo, anti-HBs negativo - suscetível a contágio por vírus\nda hepatite B.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-262430","number":"262430","sourceNumber":"262430","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Determinado senhor de 61 anos de idade, morador de Manaus (AM), marcou consulta\nmédica por quadro clínico de mal-estar,\ncefaleia, astenia, icterícia, náuseas e vômito há uma\nsemana. O médico, após anamnese e exame físico, solicitou exames laboratoriais, incluindo\nsorologias para hepatites virais, receitou sintomáticos e agendou o retorno. No retorno, os exames\napresentaram anti-HAV IgG reagente, anti-HAV IgM não reagente, HBsAg reagente, anti-HBs Ag\nnão reagente, anti-HBc total reagente, anti-HBc IgM reagente, HBeAg reagente, anti-HBe não\nreagente e anti-HCV não reagente. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. O paciente deve ser orientado quanto à prevenção das hepatites\nvirais, acerca de seus contatos domiciliares e parceiros sexuais, e com relação ao uso adequado de\npreservativo e do não compartilhamento de instrumentos perfurocortantes e de objetos de higiene\npessoal, como escovas de dente, alicates de unha e lâminas de barbear ou de depilação.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-262477","number":"262477","sourceNumber":"262477","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Um paciente de 65 anos de idade, assintomático, ao realizar testes sorológicos de\ntriagem, oferecidos por um mutirão da saúde no seu bairro, descobriu um resultado de Anti-HCV\nreagente. Foi encaminhado ao médico infectologista que solicitou exames laboratoriais e de\nimagem para o paciente. Considerando esse caso clínico e os conhecimentos médicos correlatos,\njulgue o item a seguir. O infectologista não precisa solicitar nenhum exame para confirmar o\ndiagnóstico de hepatite C, uma vez que o anti-HCV reagente é suficiente para confirmação do\ndiagnóstico de hepatite C crônica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-262478","number":"262478","sourceNumber":"262478","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Um paciente de 65 anos de idade, assintomático, ao realizar testes sorológicos de\ntriagem, oferecidos por um mutirão da saúde no seu bairro, descobriu um resultado de Anti-HCV\nreagente. Foi encaminhado ao médico infectologista que solicitou exames laboratoriais e de\nimagem para o paciente. Considerando esse caso clínico e os conhecimentos médicos correlatos,\njulgue o item a seguir. O médico solicitou genotipagem para hepatite C e confirmou genótipo tipo\ntrês. Para esse genótipo, o infectologista prescreveu sofosbuvir e daclatasvir.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-262479","number":"262479","sourceNumber":"262479","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Um paciente de 65 anos de idade, assintomático, ao realizar testes sorológicos de\ntriagem, oferecidos por um mutirão da saúde no\nseu bairro, descobriu um resultado de Anti-HCV\nreagente. Foi encaminhado ao médico infectologista que solicitou exames laboratoriais e de\nimagem para o paciente. Considerando esse caso clínico e os conhecimentos médicos correlatos,\njulgue o item a seguir. Para prescrever o tratamento da hepatite C crônica, o médico deve pedir\nbiópsia hepática ou elastografia hepática para avaliar o grau de fibrose hepática, já que a\nindicação\ndo tratamento é para fibrose maior ou igual a três.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-255679","number":"255679","sourceNumber":"255679","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Um paciente de 55 anos de idade apresentou quadro de febre, mal-estar e dor\nabdominal difusa. Durante a investigação, foi diagnosticado abscesso hepático com ruptura\nintra-abdominal. A respeito desse caso clínico e tendo em vista os conhecimentos médicos\n\ncorrelatos, julgue o item a seguir. Alguns estudos sugerem que há falha na drenagem percutânea\nde abscessos maiores que 5 cm.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-131831","number":"131831","sourceNumber":"131831","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Quanto às hepatites virais agudas, assinale a alternativa CORRETA:","options":{"A":"A hepatite A tem transmissão fecal-oral, apresenta período de incubação de 30 a 150 dias e não\ncronifica.","B":"A hepatite B possui transmissão vertical, parenteral e sexual, tem período de incubação de 15 a\n30 dias e cronifica em 90% dos casos nos\nhomens adultos infectados.","C":"A hepatite C é causada pelo HCV, um vírus DNA, que tem período de incubação de 5 a 20 dias,\nsendo a transmissão sexual a forma mais comum de contágio.","D":"A hepatite D está ligada à ocorrência da hepatite C e é um vírus DNA que pode se manifestar\nem dois padrões clínicos: a superinfecção e a\ncoinfecção, sendo a superinfecção a ocorrência\nsimultânea das hepatites C e D agudas.","E":"A hepatite A pode ser diagnosticada através do achado de IgM anti-HAV no soro do paciente\ncom características clínicas e bioquímicas de\nhepatite aguda."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-135082","number":"135082","sourceNumber":"135082","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A respeito de doenças infectocontagiosas, julgue o item a seguir. Geralmente, o vírus\nda hepatite A infecta o organismo por via oral,\no que origina uma infecção aguda, contagiosa e\nautolimitada. Esse vírus é excretado nas fezes, logo, a hepatite causada por esse agente está\ndiretamente relacionada ao padrão de saneamento da região.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-140747","number":"140747","sourceNumber":"140747","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A respeito das doenças infecciosas, julgue o seguinte item. Em pacientes portadores da\nhepatite C crônica, a ultrassonografia de abdome total deve ser realizada a cada seis meses para\nrastreamento de câncer hepático.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-64699","number":"64699","sourceNumber":"64699","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"<p>Um paciente procurou o atendimento médico devido a um resultado de uma\nsorologia para hepatite B, que foi solicitada em\nseu serviço, com os seguintes resultados: AgHBe\nnegativo e anti-HBe positivo, além de alteração nas enzimas hepáticas. Sendo assim, assinale a\nalternativa que apresenta o diagnóstico mais provável deste paciente.</p>","options":{"A":"Portador inativo, sem hepatite.","B":"Infecção por vírus selvagem.","C":"Cirrose hepática.","D":"Hepatite B curada na janela imunológica.","E":"Hepatite B devido a um vírus mutante pré-core."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-32188","number":"32188","sourceNumber":"32188","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Um paciente assintomático, usuário de drogas injetáveis, procurou atendimento médico\npara exame de rotina. O médico assistente solicitou alguns exames sorológicos, cujos resultados\nforam: HBsAg positivo, anti-HBs negativo, anti-HBc IgM negativo, anti-HBc total positivo. Com base\nnos resultados desses exames, foi diagnosticado:","options":{"A":"Indivíduo imune por infecção natural.","B":"Hepatite aguda pelo vírus C.","C":"Hepatite crônica pelo vírus C.","D":"Hepatite aguda pelo vírus B.","E":"Hepatite crônica pelo vírus B."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-343393","number":"343393","sourceNumber":"343393","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"É definida como coloração amarelada da pele, escleróticas, membranas mucosas e\nlíquidos orgânicos, consequente à deposição, nesses locais, de pigmento biliar - bilirrubina, o qual\nse encontra em níveis elevados no plasma (hiperbilirrubinemia). É clinicamente detectada quando a\nconcentração sérica de bilirrubina ultrapassa 2-3 mg /100 ml. O trecho se refere a:","options":{"A":"Cirrose.","B":"Síndrome nefrótica.","C":"Edema idiopático.","D":"Icterícia."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-291485","number":"291485","sourceNumber":"291485","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Um homem de 23 anos de idade, membro de um grupo de usuário de drogas ilícitas\ninjetáveis, comparece à consulta no ambulatório de\nclínica médica com relato de \"olhos amarelos e\nurina cor de mate\". Segundo informa seu quadro clínico iniciou-se há cerca de 12 dias com\n\nmal-estar, febre (cerca de 38ºC), coriza e mialgias. Dois dias após, observou disgeusia e anosmia,\nalém de diarreia. Procurou unidade de pronto atendimento, sendo agendada pesquisa para\n\ncovid-19, que foi realizada no 5º dia de evolução da doença com resultado negativo. Passou a\napresentar, também, dor abdominal\n(especialmente no hipocôndrio direito) e fadiga vespertina. Há\n2 dias, observou que suas escleras ficaram amareladas e sua urina assumiu aspecto sugestivo de\ncolúria. Foi à mesma unidade onde havia sido atendido inicialmente, sendo solicitados exames\ncomplementares que são trazidos pelo paciente à consulta atual e que revelam: TGO/AST = 982\nUI/L (valor de referência: 20 a 40 UI/L); ALT/TGP: 1.220 UI/L (valor de referência: 20 a 40 UI/L);\nbilirrubinas totais = 4,2 mg/dl (valor de referência: 0,2 a 0,8 mg/dl), com predomínio da fração\ndireta\n(3,6 mg/dl ? valor de referência: 0,1 a 0,5 mg/dl); hemograma com leucopenia e linfocitose, sem\nanemia; INR e tempo de tromboplastina parcial ativada normais. Em razão desses resultados, o\npaciente foi encaminhado ao ambulatório para complementação da investigação diagnóstica,\ntratamento e acompanhamento. Ao exame físico, o paciente encontra-se em razoável estado geral,\nestando com as escleras e a mucosa sublingual ictéricas, além de apresentar leve hepatomegalia\n(13 cm de extensão ao nível da linha hemiclavicular direita) dolorosa, com sinal de Murphy\nnegativo. Acerca do caso desse paciente, pode-se afirmar que o diagnóstico mais provável e a\nlógica subjacente a tal conclusão são:","options":{"A":"Hepatite viral pelo vírus da hepatite C, por ser a causa mais comum de hepatite viral de\napresentação aguda.","B":"Hepatite autoimune do tipo 1, em função do gênero do paciente (sexo masculino) e do nível de\ntransaminases.","C":"Hepatite viral aguda pelo vírus da hepatite B, em razão de o paciente ser usuário de drogas\nilícitas injetáveis.","D":"Leptospirose íctero-hemorrágica, em razão do leucograma e níveis séricos das\naminotransferases."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-263416","number":"263416","sourceNumber":"263416","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Um homem de 50 anos de idade realiza investigação ambulatorial devido ao aumento\nde transaminases: AST = 122 U/L (valor de\nreferência: < 38 U/L) e ALT = 142 U/L (valor de\nreferência: < 41 U/L) evidenciado em um exame de rotina. O paciente consome 5 latas de cerveja\ndiariamente e nega o uso de drogas ilícitas. Não apresenta queixas clínicas. Os exames\nlaboratoriais solicitados para a investigação demonstraram o que está apresentado no quadro a\nseguir. Com base nos aspectos clínicos e laboratoriais, o diagnóstico e a conduta neste momento\ndevem ser, respectivamente:","options":{"A":"Hepatite B crônica; indicar vacinação.","B":"Hepatite B aguda; indicar interferon alfa peguilado.","C":"Hepatite C curada; orientar interrupção do etilismo.","D":"Hepatite B crônica; orientar interrupção do etilismo."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":["question_bank/media/medcurso/medcurso-hepato-hep-1/263416.png"],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-227390","number":"227390","sourceNumber":"227390","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente do sexo masculino, de trinta e cinco anos de idade, procurou atendimento\nmédico devido a achado de hepatite viral em\nscreening de doação de sangue. Ele apresentava a\nseguinte sorologia: AgHBs positivo, anti-HBc total positivo, anti-HBs negativo, AgHBe negativo e\nanti-HBe positivo. Enzimas hepáticas normais e ultrassonografia de abdome sem alterações. Com\nrelação a esse caso clínico, julgue o item que se segue. A informação a respeito da profissão do\npaciente é irrelevante, pois não envolve fator de risco de contágio a outras pessoas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-227391","number":"227391","sourceNumber":"227391","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente do sexo masculino, de trinta e cinco anos de idade, procurou atendimento\nmédico devido a achado de hepatite viral em\nscreening de doação de sangue. Ele apresentava a\nseguinte sorologia: AgHBs positivo, anti-HBc total positivo, anti-HBs negativo, AgHBe negativo e\nanti-HBe positivo. Enzimas hepáticas normais e ultrassonografia de abdome sem alterações. Com\nrelação a esse caso clínico, julgue o item que se segue. É essencial solicitar carga viral\nsorológica\ndo vírus da hepatite B (PCR DNA VHB) para confirmar o diagnóstico desse paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-227392","number":"227392","sourceNumber":"227392","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente do sexo masculino, de trinta e cinco anos de idade, procurou atendimento\nmédico devido a achado de hepatite viral em\nscreening de doação de sangue. Ele apresentava a\nseguinte sorologia: AgHBs positivo, anti-HBc total positivo, anti-HBs negativo, AgHBe negativo e\nanti-HBe positivo. Enzimas hepáticas normais e ultrassonografia de abdome sem alterações. Com\nrelação a esse caso clínico, julgue o item que se segue. Atualmente, a biópsia hepática tem sido\ndispensável para o estadiamento da hepatite B, haja vista os exames de avaliação de fibrose\nhepática não invasivos, como a elastrografia percutânea ou o elastro RNM.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-230628","number":"230628","sourceNumber":"230628","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Os sintomas da infecção pelo HCV geralmente são inespecíficos, tais como anorexia,\nastenia, mal-estar e dor abdominal, sendo\npresentes na minoria de casos (20% a 30%) com uma\nmenor parte dos pacientes que apresenta icterícia ou escurecimento da urina. Está INCORRETA a\nalternativa:","options":{"A":"O diagnóstico diferencial não é possível apenas com a realização de testes para detecção de\nanticorpos ou para a detecção do RNA do HCV (HCV-RNA).","B":"Casos de insuficiência hepática ou casos fulminantes são extremamente raros.","C":"Eliminação viral espontânea, após a infecção aguda pelo HCV, ocorre em 15% a 40% dos\ncasos.","D":"São fatores do hospedeiro, parecem associados à eliminação viral espontânea."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-230634","number":"230634","sourceNumber":"230634","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"O Vírus da Hepatite C (HCV) pertence ao gênero Hepacivirus, família Flaviviridae\n(THIEL et al., 2012). Sua estrutura genômica é\ncomposta por uma fita simples de Ácido\nRibonucleico (RNA), de polaridade positiva, com aproximadamente 9.400 nucleotídeos. Existem,\npelo menos, sete genótipos e 67 subtipos do vírus. A transmissão do HCV ocorre principalmente\npor via parenteral, por meio do contato com sangue contaminado, a exemplo dos listados abaixo,\nindique a alternativa com ERRO:","options":{"A":"Compartilhamento de agulhas, seringas e outros objetos para uso de drogas,","B":"Reutilização ou falha de esterilização de equipamentos médicos ou odontológicos,","C":"Falha de esterilização de equipamentos de manicure e reutilização de material para realização\nde tatuagem não é capaz de transmitir.","D":"Uso de sangue e seus derivados contaminados."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-230636","number":"230636","sourceNumber":"230636","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Para a hepatite B, a indicação da imunoglobulina humana anti-hepatite BIGHAHB irá\ndepender do tipo de exposição (vítimas de acidentes com material biológico infectado ou\nfortemente suspeito de infecção por HBV, comunicantes sexuais de casos agudos de hepatite B,\nvítimas de violência sexual, imunodeprimidos após exposição de risco, mesmo que previamente\nvacinados.), sendo CORRETO que:","options":{"A":"O conhecimento do status sorológico da pessoa-fonte em relação à hepatite B é importante para\na decisão sobre a utilização ou não da\nimunoglobulina humana anti-hepatite B IGHAHB.","B":"O conhecimento do status sorológico da pessoa-fonte em relação à hepatite B não é importante\npara a decisão sobre a utilização ou não da\nimunoglobulina humana anti-hepatite B IGHAHB.","C":"O conhecimento do status sorológico da pessoa-fonte em relação à hepatite B independe para a\ndecisão sobre a utilização ou não da imunoglobulina humana anti-hepatite B IGHAHB.","D":"O conhecimento do status de função hepática da pessoa-fonte em relação à hepatite B é o mais\nimportante para a decisão sobre a utilização ou não da imunoglobulina humana anti-hepatite B\nIGHAHB."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-212047","number":"212047","sourceNumber":"212047","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente do sexo feminino, de 37 anos de idade, faxineira, quatro filhos, foi atendida no\npronto-socorro hospitalar com índice de massa corporal de 32 e histórico de crises dispépticas e\ncólicas abdominais, localizadas em epigástrico. O quadro clínico evoluiu nas últimas 8 horas com\ndor forte e contínua no epigástrico e hipocôndrio direito, houve remissão transitória, com o uso de\nanalgésicos orais, e dois episódios de vômitos. No exame físico, apresentava-se ansiosa,\nhipocorada (+/4+), taquicárdica (90 bpm) e levemente ictérica. No que tange a esse caso clínico e\naos múltiplos aspectos a ele relacionados, julgue o item subsecutivo. As informações apresentadas\nnesse caso clínico apontam para a hipótese de hepatite aguda transinfecciosa.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hepato-hep-1-206099","number":"206099","sourceNumber":"206099","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Com relação à anatomia esplênica, assinale a alternativa INCORRETA:","options":{"A":"A artéria esplênica, um ramo do tronco celíaco, é um vaso tortuoso que emite múltiplos ramos\npara o pâncreas e cursa ao longo de sua\nface posterior.","B":"Existem duas matrizes típicas da artéria esplênica ? a magistral, que se ramifica em artérias\nterminais e polares próxima ao hilo do\nbaço, e a distributiva, que, como seu nome indica, dá seus\nramos precocemente e afastados do hilo.","C":"Ele é protegido pelas costelas 9,10 e 11 e é mantido em sua localização por múltiplas reflexões\nperitoneais, esplenofrênica, gastroesplênica, esplenorrenal e ligamentos esplenocólicos.","D":"Em pacientes com hipertensão portal, os ligamentos esplenofrênico e esplenocólico são\nrelativamente avasculares."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-206130","number":"206130","sourceNumber":"206130","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Inicialmente denominada ?hepatite não A não B?, a hepatite C foi elucidada apenas em\n1989, com a identificação de seu agente etiológico (CHOO et al., 1989). A partir daí, a infecção\npelo\nvírus da hepatite C (HCV) adquiriu especial importância entre as causas de doença hepática. NÃO\nsendo adequado, apenas, o seguinte item:","options":{"A":"A hepatite C é uma doença que afeta entre 80 e 150 milhões de pessoas no mundo, sendo uma\nrara causa de transplantes de fígado.","B":"A história natural da hepatite C é marcada por uma evolução silenciosa.","C":"Os sinais e sintomas são comuns às demais doenças parenquimatosas crônicas do fígado e\ncostumam se manifestar apenas nas fases mais avançadas da doença.","D":"A maioria dos casos é assintomática e o diagnóstico da doença geralmente é tardio, ocorrendo\ndécadas após a infecção viral."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-175118","number":"175118","sourceNumber":"175118","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"João, 13 anos, é levado ao atendimento médico por sentir-se indisposto, sem fome,\ncom vômitos em grande quantidade, urina marrom\ne febre há 2 dias, associados à coloração\namarelada da pele e dos olhos e sangramento gengival. Mora no Pará, em uma região com poucos\nrecursos, sem tratamento de esgoto. Encontra-se em REG, acianótico, ictérico 4+/4, afebril,\neupneico, sonolento, aparelho cardiorrespiratório normal, abdome normotenso, pouco doloroso\ndifusamente, fígado a 3 cm do RCD, sinal do piparote positivo e macicez móvel dos flancos também\npositivo, RHA+. Pulsos cheios e boa perfusão periférica. Ausência de linfonodomegalia. O\ndiagnóstico mais provável para o paciente é:","options":{"A":"Hepatite A.","B":"Anemia falciforme em crise de falcização com hemólise.","C":"Síndrome de Reye.","D":"Doença de Berger."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-154505","number":"154505","sourceNumber":"154505","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Mulher de 18 anos, refere perda de apetite e não ter dormido nas últimas 3 noites, após\ntérmino de namoro. Hoje, ao lavar o rosto pela manhã, notou estar ictérica. Refere ocorrência de\nepisódios prévios semelhantes, todos com remissão espontânea. Nenhum parente apresenta\nquadro semelhante. Ao exame clínico apresenta-se com icterícia leve, sem outras alterações.\n\nExames: hemácias 4,34 x 10¹²/L, hematócrito 38%, hemoglobina 13,8 g/dL, reticulócitos\n47.000/mm3, bilirrubina total=2,5 mg/dL,\nbilirrubina direta=0,9 mg/dL, bilirrubina indireta=1,6 mg/dL,\nhaptoglobina normal, desidrogenase lática normal. Diante da principal suspeita diagnóstica, o\npróximo exame a ser pedido é:","options":{"A":"Dosagem de fator V.","B":"Eletroforese de hemoglobina.","C":"Sorologia para hepatites virais.","D":"Enzimas hepáticas e canaliculares.","E":"Nenhum."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-168530","number":"168530","sourceNumber":"168530","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Um homem com 25 anos de idade é atendido na Unidade Básica de Saúde, com\nqueixa de febre não aferida, associada à\nmialgia, edema perimaleolar ++/4+ há 2 semanas, quando\nfoi submetido a exame do sedimento urinário, com o seguinte resultado: hematúria microscópica,\ncilindros hemáticos e leucocitários. Durante a anamnese, o paciente relatou que os sintomas\napareceram após forte chuva ocorrida em seu bairro, quando precisou retirar a água que entrara\nem sua casa. Interrogado quanto ao uso de preservativos, referiu julgá-lo desnecessário, já que\ntinha única parceira, sua conhecida desde a infância. Mediante os fatos relatados, o médico\nsolicitou alguns exames laboratoriais e indicou que retornasse em uma semana. No retorno, o\npaciente queixou-se de intensa dor nas articulações dos joelhos, punhos e mãos. O exame físico\nevidenciou paciente levemente ictérico e com discreto edema em punho direito, leve dor no\nhipocôndrio direito e uma ponta de baço palpável. Os resultados dos exames laboratoriais\nsolicitados na primeira consulta revelaram: hemácias = 4.120.000/mm³ (valor de referência =\n3.900.000-5.000.000/mm³); hemoglobina = 13,40 g/dl (valor de referência = 12,0-15,0 g/dl);\nhematócritos = 44,8% (valor de referência = 35-45%); leucócitos = 10.000/mm³ (valor de referência\n\n= 3.500-10.500/mm³); com 4% de bastões (valor de referência = 1-5%); plaquetas = 298.000/mm³\n(valor de referência = 150.000-450.000/mm³);\nAST = 520 UI/L (valor de referência = < 38 UI/L); ALT\n\n= 730 UI/L (valor de referência = < 41 UI/L); FA e GGT no limite superior da normalidade;\nbilirrubina\ntotal = 7 mg/dl (valor de referência =\n0,2-1,3 mg/dl) com predomínio da fração direta; anti-HAV IgG\n(+)/ IgM (-); HBsAg (-); Ac anti-HBs (-); Ac anti-HBc: IgM(+)/IgG(+); Ag HBe(-); Ac anti-HBe(+); HBV\nDNA baixo e Ac anti-HCV (-). Diante dos achados clínicos, epidemiológicos e laboratoriais, qual a\nprincipal hipótese diagnóstica?","options":{"A":"Hepatite A colestática.","B":"Hepatite B mutante pré-core.","C":"Leptospirose em fase precoce.","D":"Hepatite B aguda não replicativa."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-159623","number":"159623","sourceNumber":"159623","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Uma menina de dez anos de idade, moradora da periferia de uma grande cidade, foi\natendida na emergência, apresentando, de acordo com relato da mãe, febre alta havia seis dias. A\nmãe informou, ainda, que, após quarenta e oito horas do início da febre, esta havia sigo seguida\npor cefaleia, vômitos , diarreia e urina escura. No exame físico, o médico observou escleróticas\nictéricas , dor abdominal e discreta hepatomegalia. A mãe da menina relatou que havia um surto de\ndengue na região onde moravam. Exames laboratóriais realizados no terceiro dia de evolução do\nquadro clínico apresentataram os seguintes resultados: TGO = 90 UI; TGP = 280 UI; anti-HVA IgM\ne IgG não reagentes; Anti-HBs Ag reagente; HBs Ag, HBeAg, anti-HBeAg, anti-HB C IgM e IgG não\nreagentes; o exame de detecção para antígeno de dengue NS1 foi negativo. Com referência ao\ncaso clínico apresentado, julgue o item que se segue. Ante as evidências sorológicas, o quadro\nclínico da paciente não deve ser atribuido à hepatite B.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hepato-hep-1-159516","number":"159516","sourceNumber":"159516","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Uma menina de dez anos de idade, moradora da periferia de uma grande cidade, foi\natendida na emergência, apresentando, de acordo com relato da mãe, febre alta havia seis dias. A\nmãe informou ainda que, após quarenta e oito horas do início da febre, esta havia sido seguida por\ncefaleia, vômitos, diarreia e urina escura. No exame físico, o médico observou escleróticas\nictéricas, dor abdominal e discreta hepatomegalia. A mãe da menina relatou que havia um surto de\ndengue na região onde moravam. Exames laboratoriais realizados no terceiro dia de evolução do\nquadro clínico apresentaram os seguintes resultados: TGO = 90 UI; TGP = 280 UI; anti-HVA IgM e\nIgG não reagentes; anti-HBsAg reagente; HBsAg, HBeAg, anti-HBeAg, anti-HBC IgM e IgG não\nreagentes; o exame de detecção para antígeno de dengue NS1 foi negativo. Com referência ao\ncaso clínico apresentado, julgue o item que se segue. A hepatite A é uma hipótese de diagnóstico,\napesar de o teste sorológico HVA IgM ser não reagente.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hepato-hep-1-111317","number":"111317","sourceNumber":"111317","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"São manifestações autoimunes relacionadas à infecção pelo vírus da hepatite C,\nEXCETO:","options":{"A":"Vasculite crioglobulinêmica.","B":"Produção de autoanticorpos.","C":"Glomerulonefrite membranoproliferativa.","D":"Sialoadenite.","E":"Artrite erosiva."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-104745","number":"104745","sourceNumber":"104745","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Em relação à hepatite B, assinale a alternativa que apresenta dados referentes a uma\ncriança que teve contato com o vírus selvagem, mas também foi vacinada, considerando os\nmarcadores virais: AgHBs, AgHBe, Anti-HBe, Anti-HBc-IgM, Anti-HBc e Anti-HBs, respectivamente.","options":{"A":"Positivo, negativo, positivo, negativo, positivo, negativo.","B":"Positivo, positivo, negativo, negativo, positivo, negativo.","C":"Negativo, negativo, positivo, negativo, positivo, positivo.","D":"Negativo, negativo, negativo, negativo, positivo, positivo.","E":"Negativo, positivo, negativo, negativo, negativo, positivo."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-80730","number":"80730","sourceNumber":"80730","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"As hepatites virais são um importante problema de saúde pública. Em relação às\nformas de transmissão e profilaxia, é correto afirmar que o(a):","options":{"A":"Vacinação contra hepatite C tem reduzido bastante sua prevalência.","B":"Risco de contaminação por HIV ainda é maior que por hepatite B\nnos acidentes perfurocortantes.","C":"Transmissão sexual de hepatite B é desprezível.","D":"Via parenteral tem aumentado muito, apesar da transmissão da hepatite A ser mais frequente\npor via enteral.","E":"Vacinação contra hepatite B logo no período neonatal oferece proteção mesmo que a mãe seja\nHBSAg positiva."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-97838","number":"97838","sourceNumber":"97838","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Uma mulher com 47 anos de idade procura atendimento em posto de saúde com\nqueixa de astenia. Foram solicitados exames\nde sangue que revelaram aumento (2,5 vezes o valor\nnormal) nos níveis séricos de aspartato aminotransferase (AST) e alanina aminotransferase (ALT).\nA investigação inicial mostrou que a paciente encontra-se monoinfectada pelo Vírus da Hepatite C\n(VHC), sendo, portanto, encaminhada ao hepatologista que solicitou novos exames\ncomplementares, cujos resultados foram: RNA-VHC = 381.420 UI/ml, genótipo viral: 1b e\nultrassonografia abdominal com moderada alteração da ecogenicidade do parênquima hepático.\n\nApresentando ainda escore de Child-Pugh igual a 4. A biópsia hepática realizada revelou fibrose\ndiscreta (F1 da classificação histológica\nMetavir). Com base no quadro apresentado, que fator está\nassociado com uma pior resposta ao tratamento antiviral?","options":{"A":"Carga viral.","B":"Genótipo viral.","C":"Escore de Child-Pugh.","D":"Grau de fibrose hepática."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-75495","number":"75495","sourceNumber":"75495","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"<p>Mulher com 48 anos de idade, durante investigação laboratorial de rotina em\nAmbulatório de Clínica Médica, é surpreendida com achado de aminotransferases cerca de duas\nvezes o limite superior da normalidade. Na investigação de órgãos e sistemas, a paciente relata\napenas ?cansaço frequente?. Foram solicitados marcadores virais de hepatites, os quais\nrevelaram: Anti-HAV IgG não reativo; HBsAG não reativo; Anti-HBc IgG não reativo; Anti-HCV\nreativo. Diante dos resultados, foram adicionados à investigação a solicitação de PCR quantitativo\npara HCV, genotipagem do HCV, ultrassonografia abdominal e indicada vacinação para Hepatite A\ne B. No encaminhamento para hepatologista, o conjunto de resultados que indicaria a maior\nprobabilidade de resposta virológica sustentada para tratamento antiviral com ribavirina e\n\npeg-interferon é: </p>","options":{"A":"RNA do HCV indetectável e fígado com evidências de cirrose.","B":"RNA do HCV indetectável e fígado sem evidências de fibrose.","C":"RNA do HCV detectável com < 2.000.000 cópias/ml, genótipo 4 e fígado com esteatose.","D":"RNA do HCV detectável com > 2.000.000 cópias/ml, genótipo 1 e fígado com fibrose avançada.","E":"RNA do HCV detectável com < 2.000.000 cópias/ml, genótipo 2 e fígado com evidência de\nfibrose."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-137543","number":"137543","sourceNumber":"137543","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Na diferenciação entre as hepatites virais deve-se considerar que","options":{"A":"todas as hepatites virais podem evoluir para a cronicidade.","B":"a persistência do vírus da hepatite C por mais de seis meses define a cronicidade.","C":"a frequência de sintomatologia na hepatite pelo vírus A é semelhante entre os grupos etários.","D":"os índices de endemicidade da hepatite pelo vírus B, no Brasil, são mais elevados nos grandes\ncentros urbanos.","E":"os vírus A, D e E, do tipo RNA, têm transmissão entérica e as infecções ocorrem nas formas\nesporádica e epidêmica."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-138653","number":"138653","sourceNumber":"138653","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente do sexo masculino, com 26 anos de idade, procura ambulatório de Clínica\nMédica com queixas, há uma semana, de mal\nestar, febre de baixa intensidade não aferida,\ninapetência, vômitos ocasionais e aversão à fumaça de cigarro, evoluindo com colúria e acolia fecal\nhá três dias. Relata que costuma alimentarse em bares com baixo nível de higiene, próximos à\nuniversidade onde estuda; e viagem, há um mês, para acampamento. Informa manter relações\nsexuais sem uso de preservativos, com parceiros e parceiras desconhecidos. Ao exame físico\napresenta-se em bom estado geral, corado, hidratado, ictérico ++/4+, lúcido, orientado, Pressão\narterial =120 x 70 mmHg , Frequência cardíaca= 64bpm. Fígado palpável a três centímetros do\nrebordo costal direito; baço impalpável. O restante do exame físico não mostrou alterações\nsignificativas. Foram solicitadas dosagens de aminotransferases, que se mostraram muito elevadas\n(>1000 UI/ml) e marcadores sorológicos virais das hepatites determinaram que o paciente era\ncarreador crônico do vírus da hepatite B e apresentava também hepatite viral aguda pelo vírus da\nhepatite A. A infecção pelo vírus da hepatite C foi excluída por sorologia e técnicas moleculares. O\nperfi l sorológico compatível com o diagnóstico do paciente é","options":{"A":"anti-HAV IgG reativo e IgM não reativo; anti-HBc IgM e IgG reativos; HBsAg reativo.","B":"anti-HAV IgG e IgM reativos; anti-HBc IgG e IgM não reativos; HBsAg não reativo.","C":"anti-HAV IgG e IgM não reativos; anti-HBc IgG reativo e IgM não reativo; HBsAg não reativo.","D":"anti-HAV IgG não reativo e IgM reativo; anti-HBc IgM e IgG não reativos; HBsAg não reativo.","E":"anti-HAV IgG e IgM reativos; anti-HBc IgM não reativo e IgG reativo; HBsAg reativo."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-31033","number":"31033","sourceNumber":"31033","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Acerca de infecções, julgue o item que se segue: Considere que uma criança de nove\nanos de idade, há três semanas com\nhepatite causada pelo vírus A, apresente icterícia e tenha sido\nlevada pela mãe ao pediatra. A mãe gostaria de saber se a criança poderia viajar ao exterior em\ntais condições. Nessa situação, o pediatra pode liberá-la para viajar em razão de não haver mais\nrisco de contaminação.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hepato-hep-1-22199","number":"22199","sourceNumber":"22199","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Com relação às doenças infectocontagiosas, julgue o item a seguir. Suponha que um\nmenino de 7 anos de idade apresente adinamia, anorexia e mal-estar geral. No exame físico,\napresenta-se ictérico e com hepatomegalia dolorosa à palpação. A mãe refere alterações urinárias\ne fecais, sugestivas de colúria e hipocolia fecal. Foram solicitadas dosagens de transaminases e\nsorologias para hepatites virais. Nessa situação, a presença do marcador anti-HBs, no soro,\ndemonstra que o paciente apresenta imunidade ao HBV.","options":{"A":"certo","B":"errado"},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hepato-hep-1-351609","number":"351609","sourceNumber":"351609","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Com relação ao diagnóstico da Insuficiência Hepática Aguda (IHA), assinale V para as\nafirmativas verdadeiras e F para as falsas. ( ) Na anamnese, não é possível indicar a etiologia da\nIHA nem sugerir uma possível abordagem específica. ( ) No exame físico, é importante definir o\ngrau de encefalopatia hepática e a presença de estigmas de doença crônica. ( ) Todos os pacientes\ncom IHA precisam de monitoração hemodinâmica contínua, necessariamente em Unidade de\nTerapia Intensiva. ( ) Não é necessário realizar exames de imagem para visualização das veias\nhepáticas nem da veia porta, pois não é preciso avaliar detalhadamente o fígado. Assinale a\nalternativa que apresenta a sequência CORRETA:","options":{"A":"F ? V ? V ? F.","B":"F ? V ? F ? V.","C":"V ? F ? F ? V.","D":"V ? F ? V ? F."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-313297","number":"313297","sourceNumber":"313297","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Leia com atenção: ?Exames complementares comuns a todos os pacientes portadores\nde hepatite B crônica que devem ser solicitados\nem primeira consulta e durante acompanhamento.\nDesses exames, é o indicado para definir a imunização?. Assinale a alternativa\nque preenche, CORRETAMENTE, a lacuna do texto:","options":{"A":"HCsAg.","B":"HCeAg.","C":"Anti-HBe.","D":"Anti-HBs.","E":"Anti-HAV IgG."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-246726","number":"246726","sourceNumber":"246726","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Enfermeiro, 39 anos de idade, hígido e sem antecedentes de hepatites virais, recebeu 3\ndoses de vacina contra hepatite B. O padrão sorológico mais provável é:","options":{"A":"AgHBs(?), AntiHBc(total)(?), AntiHBcIgM(?), Anti-HBs(+)","B":"AgHBs(+), AntiHBc(total)(+), AntiHBcIgM(+), Anti-HBs(+)","C":"AgHBs(+), AntiHBc(total)(+/?), AntiHBcIgM(+/?), Anti-HBs(+)","D":"AgHBs(?), AntiHBc(total)(+), AntiHBcIgM(?), Anti-HBs(?)","E":"AgHBs(?), AntiHBc(total)(?), AntiHBcIgM(+), Anti-HBs(+)"},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-227256","number":"227256","sourceNumber":"227256","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Em relação à infecção aguda pelo vírus da hepatite C assinale a alternativa correta:","options":{"A":"Cerca de 20% a 30% dos casos de infecção aguda pelo vírus da hepatite C são sintomáticos,\napresentando-se como qualquer outro caso de hepatite viral aguda com febre, náuseas, icterícia,\nfadiga e anorexia.","B":"O RNA do vírus da hepatite C só é encontrado no soro de paciente infectados após cerca de 6\nmeses da infecção aguda.","C":"Apenas 10% dos pacientes infectados pelo vírus da hepatite C tornam-se portadores crônicos do\nvírus.","D":"Ausência de sintomas na fase aguda, sexo masculino e idade acima de 40 anos parecem ser\nfatores que estão associados à eliminação espontânea do vírus."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-155355","number":"155355","sourceNumber":"155355","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Mulher de 40 anos de idade, com história prévia de hepatite pós-transfusional,\napresenta elevação discreta da ALT e da gama GT.\nNão há sinais periféricos de hepatopatia, nem\nhepatoesplenomegalia. O HBsAg foi negativo, o anti-AgHBc Total positivo, o anti-HBs positivo, o\nanti-HCV positivo e o HCV RNA positivo. O diagnóstico provável é:","options":{"A":"Infecção crônica pelos vírus da hepatite B e C.","B":"Infecção crônica pelo vírus da hepatite B.","C":"Hepatite B aguda e infecção crônica C.","D":"Hepatite B curada e infecção pelo vírus da hepatite C.","E":"Infecção C aguda."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-155459","number":"155459","sourceNumber":"155459","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente masculino 35 anos, casado, pardo, previamente hígido, ao tentar doar sangue\ndescobriu ser portado de anti-HBc total reagente e HBsAg positivo. Foi encaminhado para\navaliação médica. Não tinha história de tabagismo, etilismo ou uso de drogas ilícitas, monogâmico\nhá 8 anos, mas refere ter sido um jovem muito \"namorador?. Exame físico geral sem\nanormalidades; abdome plano indolor, fígado palpável a 3 cm do RCD, superfície lisa, consistência\nlevemente aumentada e borda fina, baço não palpável. Os exames iniciais a serem solicitados para\navaliar a fase da doença no paciente e posterior indicação de tratamento são:","options":{"A":"HBeAg e anti-HBe para saber se o vírus encontra-se em fase de replicação e indicar início de\ntratamento. Não há necessidade de solicitar dosagem de aminotransferases (TGO e TGP).","B":"anti-HBc IgM e IgG para avaliar a aproximadamente quanto tempo o paciente se contaminou e\nas aminotransferases (TGO e TGP) para avaliar nível\nde lesão hepática.","C":"HBeAg e anti-HBe para saber se o vírus encontra-se replicando e as aminotransferases (TGO e\nTGP) para avaliar nível de lesão hepática.","D":"HBeAg e anti-HBe para saber se o vírus encontra-se replicando. E HBV-DNA quantitativo para\nindicar tratamento.","E":"HBV-DNA quantitativo para indicar o tratamento, uma vez que o paciente apresentando anti-HBc\ntotal reagente e HBsAg positivo se encontra na\nfase crônica da doença."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-127204","number":"127204","sourceNumber":"127204","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente de 46 anos, sexo feminino, apresentando há 2 semanas icterícia e adinamia.\nExame físico normal. Exames laboratoriais:\nbilirrubina total = 5,7 mg/dl (bilirrubina direta = 4,2 mg/dl\ne bilirrubina indireta = 1,5 mg/dl); AST = 1.215 U/L (valor de referência = até 30 U/L); ALT = 1.530\nU/L (valor de referência = até 30 U/L); TAP = 85%. Sorologias virais: anti-VHA IgG (+); anti-VHA\nIgM (-); HBsAg (+); anti-HBc IgG (+); anti-HBc IgM (+); HBeAg (+); anti-HBe (-); anti-VHC (-).\n\nAssinale a afirmativa que apresenta o diagnóstico:","options":{"A":"Hepatite aguda pelos vírus das hepatites A e B.","B":"Hepatite crônica pelos vírus das hepatites A e B.","C":"Hepatite aguda pelo vírus da hepatite B em paciente portador crônico do vírus da hepatite A.","D":"Hepatite aguda pelo vírus da hepatite B em paciente imune ao vírus da hepatite A.","E":"Hepatite crônica pelo vírus da hepatite B com alta replicação viral e imunidade para o vírus da\nhepatite A."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-87430","number":"87430","sourceNumber":"87430","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Na intoxicação por acetominofen, qual o achado que indica prognóstico ruim?","options":{"A":"Bilirrubina total maior que 1,8 mg/dL.","B":"Creatinina sérica < 3 mg/dL.","C":"Encefalopatia hepática.","D":"pH > 7,35 mg/dL.","E":"Tempo de protrombina maior que cinco vezes o controle."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-77519","number":"77519","sourceNumber":"77519","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Dos métodos não invasivos abaixo, aquele com maior sensibilidade e especificidade\npara a graduação do nível de fibrose\nhepática em doentes portadores de hepatites virais crônicas é:","options":{"A":"Ultrassonografia abdominal com Doppler e medida de resistência da artéria hepática.","B":"Tomografia computadorizada do abdome, helicoidal e trifásica.","C":"Ressonância nuclear magnética do abdome com saturação de gordura.","D":"Fibroscan (elastografia hepática).","E":"Biópsia hepática guiada por ultrassonografia."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-88895","number":"88895","sourceNumber":"88895","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Podem ser considerados, se encontrados ao exame físico, como sinais de insuficiência\nhepática, todas as alternativas, EXCETO:","options":{"A":"Circulação colateral do tipo cabeça de medusa.","B":"Spiders.","C":"Icterícia.","D":"Eritema palmar.","E":"Asterix."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-59334","number":"59334","sourceNumber":"59334","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Em relação à Hepatite A, marque a alternativa FALSA:","options":{"A":"Seu agente causal é um vírus e é classificado com um enterovírus.","B":"É uma doença de distribuição mundial e não está restrita aos países em desenvolvimento.","C":"A principal forma de contagio é a fecal-oral, através do consumo por exemplo de água ou\nalimentos contaminados.","D":"A gravidade da doença aumenta com a idade.","E":"A vacinação é ineficaz, com proteção apenas transitória, motivo pelo qual não é recomendada e\nnão incluída no calendário vacinal brasileiro."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-59082","number":"59082","sourceNumber":"59082","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"<p>A seguir, estão relacionados os marcadores sorológicos, os exames de biologia\nmolecular e as transaminases de três\npacientes que foram atendidos no ambulatório de clínica\nmédica: Paciente 1: HBsAG positivo; anti-HBc IgG positivo; HBeAG negativo; anti-HBeAG positivo;\nDNA ao vírus da hepatite B: 12.600 UI/ml; anti-VHC negativo; AST 88 U/L (valor de referência: 30\nU/L); ALT 91 U/L (valor de referência: 30 U/L). Paciente 2: HBsAG negativo; anti-HBc IgG negativo;\nanti-HBsAG positivo; anti-VHC positivo; RNA VHC positivo; AST 41 U/L (valor de referência: 30\nU/L); ALT 57 U/L (valor de referência: 30 U/L). Paciente 3: HBsAG negativo; anti-HBc IgG positivo;\nanti-HBs positivo; anti-VHC positivo; RNA VHC ainda em análise; AST 10 U/L (valor de referência:\n30 U/L); ALT 17 U/L (valor de referência: 30 U/L). Assinale a alternativa que apresenta o\ndiagnóstico CORRETO para cada paciente acima:</p>","options":{"A":"Paciente 1: portador inativo do vírus da hepatite B; Paciente 2: hepatite crônica C em paciente\nimune ao vírus da hepatite B por vacina; Paciente 3: paciente imune ao vírus da hepatite B e ao\nvírus da hepatite C.","B":"Paciente 1: hepatite crônica B com replicação viral ativa (mutante pré-core); Paciente 2:\nhepatite\ncrônica C em paciente imune ao vírus da hepatite B por vacina; Paciente 3: paciente com contato\nprévio e imunidade ao vírus da hepatite B e com contato prévio com o vírus da hepatite C.","C":"Paciente 1: hepatite crônica B com replicação viral ativa (mutante pré-core); Paciente 2:\nhepatite\ncrônica C em paciente imune ao vírus da hepatite B por contato prévio; Paciente 3: paciente com\ncontato prévio e imunidade aos vírus da hepatite B e C.","D":"Paciente 1: portador inativo do vírus da hepatite B; Paciente 2: hepatite aguda C em paciente\nimune ao vírus da hepatite B por contato prévio; Paciente 3: paciente com imunidade ao vírus da\nhepatite B por vacina e com contato prévio ao vírus da hepatite C.","E":"Paciente 1: hepatite crônica B sem replicação viral ativa; Paciente 2: hepatite crônica C em\npaciente imune ao vírus da hepatite B por\ncontato prévio; Paciente 3: paciente com contato prévio e\nimunidade aos vírus hepatite B e C."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-23115","number":"23115","sourceNumber":"23115","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente sexo masculino de 25 anos, há 10 dias com icterícia, colúria, artralgia. Na\nhistória epidemiológica relata viagem para a Bahia\nhá 40 dias, consumo de mariscos crus na praia,\nuso de drogas injetáveis e relação sexual desprotegida. Os exames revelaram: TGO= 1240,TGP=\n1580, AntiVHA IgG (+), Anti VHA Ig M (-), HBsAg (+), Anti HBc total (+), Anti HBc Ig M (+),Anti HBs\n(-), anti VHC (-). Avalie cuidadosamente as sorologias virais e assinale a afirmativa correta sobre\no\ncaso.","options":{"A":"Paciente com hepatite aguda A, em portador crônico do vírus B, sem contato prévio com o vírus\nC.","B":"Hepatite aguda pelos vírus A e B.","C":"Paciente precisa ser vacinado contra hepatite B já que o anti-HBs é negativo.","D":"Hepatite aguda C em portador crônico do vírus B.","E":"Hepatite aguda pelo vírus B em paciente imune ao vírus A."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-23079","number":"23079","sourceNumber":"23079","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Quanto a Hepatite B é correto afirmar:","options":{"A":"A transmissão vertical do vírus da Hepatite B aguda ao concepto é pouco frequente no primeiro\ne segundo trimestres por via transplacentária\n(5%).","B":"Durante o terceiro trimestre a hepatite aguda transmite-se ao recém-nascido por contaminação\ndurante o nascimento (65%).","C":"As portadoras do vírus da hepatite B crônica HBsAg (+) e também portadoras do anticorpo\nHBeAg de regra não transmitem o vírus ao recém-nascido (5%).","D":"As portadoras de HBsAg (+) e HBeAg (+) indica replicação viral e transmissão no parto de 75%\nà 96%.","E":"Todas estão corretas."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-27412","number":"27412","sourceNumber":"27412","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente chega ao ambulatório de referência encaminhado pela Unidade de Saúde com\nos seguintes exames : HbsAg ? (+), AntiHBc\ntotal ? (+), HbeAg ? (-), AntiHBe ? (+), antiHVA ? (+),\nAntiHCV ? (-), transaminases dentro dos limites normais. Assintomático. Analise as afirmativas\nabaixo: 1. O paciente é portador de Hepatite B com mutação pré-core. 2. O paciente é portador de\nHepatite A considerando a presença do marcador AntiHAV positivo. 3. Deverá ser realizado a\nquantificação do HBVDNA por PCR, com a finalidade de avaliar a condição de portador ativo ou\ninativo. 4. Os exames apresentados são suficientes para definir a necessidade de tratamento\nimediato com antivirais, considerando a presença do HbsAg positivo.","options":{"A":"Todas as afirmativas são corretas.","B":"Afirmativas 1 e 3 são corretas.","C":"Afirmativas 1, 2 e 4 são corretas.","D":"Afirmativas 2 e 3 são corretas.","E":"Afirmativas 2, 3 e 4 são corretas."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-8129","number":"8129","sourceNumber":"8129","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Com relação ao diagnóstico das hepatites virais, podemos afirmar:","options":{"A":"Paciente com sorologia anti-VHA IGG (+) e anti-VHA IgM (-) precisa ser vacinado para hepatite\nA.","B":"Sorologia HBsAG (-) anti-HBc IGG (+) e anti-HBs(+) indica infecção passada e imunidade para o\nvírus B.","C":"Sorologia anti-HBc IgM (+) faz o diagnóstico de hepatite aguda C.","D":"Paciente anti-VHC (+) possui anticorpos protetores contra hepatite C.","E":"Paciente anti-VHC (+) e PCR VHC (-) apresenta infecção ativa pelo vírus hepatite C."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-366964","number":"366964","sourceNumber":"366964","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Gabriela, 45 anos, tem histórico de transfusão sanguínea na década de 80. Atualmente,\nela apresenta elevação das transaminases e testes\nsorológicos positivos para um vírus. Qual é o\nvírus mais provavelmente responsável pelos sintomas de Gabriela?","options":{"A":"Vírus da hepatite C (HCV).","B":"HIV.","C":"Vírus da hepatite A (HAV).","D":"Vírus da hepatite B (HBV)."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-366956","number":"366956","sourceNumber":"366956","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Qual dos agentes abaixo é mais frequentemente associado a doenças infecciosas do\nfígado, levando à hepatite aguda e, potencialmente, à hepatite crônica?","options":{"A":"Escherichia coli.","B":"Vírus da hepatite C (HCV).","C":"Bacilo de Koch (Mycobacterium tuberculosis).","D":"Streptococcus pneumoniae."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-353831","number":"353831","sourceNumber":"353831","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Os resultados laboratoriais de um paciente de 45 anos com sintomas de disfunção\nhepática indicam: transaminases 12x acima do\nvalor de referência, Fosfatase Alcalina (FA) 3x\nacima, e ALT > AST, transaminases superiores a 1000 U/L. Seguindo as regras do MACETE (MED\n2013), é CORRETO afirmar:","options":{"A":"Síndrome é colestática, pois FA está 3x acima do valor de referência.","B":"Níveis elevados de transaminases sugerem Hepatite Viral Aguda.","C":"AST maior do que 2x ALT indica Hepatite Alcoólica.","D":"Paciente não tem síndrome hepatocelular; transaminases 12x acima do valor de referência."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-366936","number":"366936","sourceNumber":"366936","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Sobre a detecção de anticorpos e antígenos do vírus B, é correto afirmar:","options":{"A":"A presença de anticorpos para o antígeno de superfície do vírus B indica, exclusivamente, uma\ninfecção ativa.","B":"A presença do antígeno e do anticorpo simultaneamente é indicativa de uma infecção crônica.","C":"A presença de antígenos, por si só, indica que o paciente já foi exposto ao vírus, mas não está\nnecessariamente infectado.","D":"A detecção de anticorpos contra o antígeno de superfície do vírus B indica imunidade protetora\nao vírus."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-366935","number":"366935","sourceNumber":"366935","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Marina, uma paciente de 38 anos, foi recentemente diagnosticada com hepatite C. Em\nsua consulta, ela pergunta sobre o agente\ncausador da doença. Qual é a resposta mais adequada?","options":{"A":"A hepatite C é causada por uma bactéria que se propaga por alimentos contaminados.","B":"O vírus da hepatite C (HCV) é um retrovírus responsável pela doença.","C":"A hepatite C é causada pelo vírus HCV, um vírus de RNA da família Flaviviridae.","D":"O vírus da hepatite C (HCV) é um vírus DNA que frequentemente resulta em infecção crônica."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-339757","number":"339757","sourceNumber":"339757","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Um paciente de 45 anos procurou a emergência com história de icterícia e colúria há\nsete dias, evoluindo com vômitos recorrentes. À admissão o paciente estava consciente e\norientado, com fígado palpável cerca de 3 cm abaixo do rebordo costal direito e seus exames\nlaboratoriais mostravam: TGO (AST) 1850 UI/ml - TGP (ALT) 3500 UI/ml - BT 10,8 mg/dl - BD 8,0\nmg/dl - INR 2,1. Investigação sorológica mostrou antiHVA IgM negativo, antiHVA IgG positivo,\nantiHBc IgM positivo, HBsAg negativo. Com relação ao caso, assinale a alternativa CORRETA.","options":{"A":"O diagnóstico de hepatite B pode ser descartado, já que o HBsAg foi negativo.","B":"O início de entecavir pode ser benéfico neste caso.","C":"A presença do antiHBc positivo na ausência de HBsAg sugere que esse é um quadro de\nreativação de hepatite B crônica.","D":"O paciente deve ser listado imediatamente para transplante hepático, pois o INR alargado define\no diagnóstico de insuficiência hepática aguda.","E":"O paciente deve ser hospitalizado imediatamente, pois níveis de transaminases acima de 3000\nUI/ml predizem mau prognóstico."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-321612","number":"321612","sourceNumber":"321612","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Leia o caso clínico. Homem de 35 anos com história de hepatite há um ano. O médico\nassistente solicitou exames para hepatite A, B e C, cujos resultados foram os seguintes: Anti-HBc\nIgG = positivo / HBsAg = positivo / HBeAg = positivo / DNA HBV = 2.008.545 UI/ml / ALT = 35 U/ml\n(VR: < 40 UI/mL) / Anti-HAV IgG = positivo / Anti-HAV Igm = negativo / Anti-HCV = negativo. Após\nseis meses, os exames foram repetidos e apresentaram: HBsAg = positivo / HBeAg = positivo /\nDNA HBV = 108 UI/ml / ALT = 38 U/ml. Qual é o diagnóstico do paciente?","options":{"A":"Infecção crônica pelo HBV, sem sinais de inflamação hepática atual.","B":"Hepatite B pregressa, em fase de cura virológica.","C":"Infecção crônica pelo HBV, com inflamação hepática atual.","D":"Cirrose hepática por HBV."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-334179","number":"334179","sourceNumber":"334179","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"O HCV foi identificado por Choo e colaboradores, em 1989, nos Estados Unidos.\nAssinale a alternativa correta.","options":{"A":"Não sendo o principal agente etiológico da hepatite crônica, anteriormente denominada\n\"\"hepatite Não A Não B\"\". Sua transmissão ocorre, principalmente, por via parenteral.","B":"Sendo o principal agente etiológico da hepatite crônica, anteriormente denominada \"\"hepatite\nNão A Não B\"\". Sua transmissão ocorre,\nprincipalmente, por via enteral.","C":"Sendo o principal agente etiológico da hepatite crônica, anteriormente denominada \"\"hepatite\nNão A Não B\"\". Sua transmissão ocorre,\nprincipalmente, por via parenteral.","D":"Sendo o principal agente etiológico da hepatite crônica, anteriormente denominada \"\"hepatite\nNão A Não B\"\". Sua transmissão não ocorre por\nvia parenteral."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-334181","number":"334181","sourceNumber":"334181","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"São consideradas populações de risco acrescido para a infecção pelo HCV por via\nparenteral,","options":{"A":"Indivíduos que receberam transfusão de sangue e/ou hemoderivados antes de 1993; pessoas\nque usam drogas injetáveis (cocaína,\nanabolizantes e complexos vitamínicos), inaláveis (cocaína)\nou pipadas (crack), e que compartilham os respectivos equipamentos de uso; pessoas com\ntatuagem, piercings ou que apresentam outras formas de exposição percutânea que não obedecem\nàs normas de biossegurança.","B":"Indivíduos que receberam transfusão de sangue e/ou hemoderivados antes de 1993; pessoas\nque usam drogas injetáveis (cocaína,\nanabolizantes e complexos vitamínicos), inaláveis (cocaína)\nou pipadas (crack), e que compartilham os respectivos equipamentos de uso; pessoas com\ntatuagem, piercings ou que apresentam outras formas de exposição percutânea que obedecem às\nnormas de biossegurança.","C":"Indivíduos que receberam transfusão de sangue e/ou hemoderivados antes de 2013; pessoas\nque usam drogas injetáveis (cocaína,\nanabolizantes e complexos vitamínicos), inaláveis (cocaína)\nou pipadas (crack), e que compartilham os respectivos equipamentos de uso; pessoas com\ntatuagem, piercings ou que apresentam outras formas de exposição percutânea que não obedecem\nàs normas de biossegurança.","D":"Indivíduos que receberam transfusão de sangue e/ou hemoderivados antes de 1993; pessoas\nque usam drogas injetáveis (cocaína,\nanabolizantes e complexos vitamínicos), inaláveis (cocaína)\nou pipadas (crack), e que não compartilham os respectivos equipamentos de uso; pessoas com\ntatuagem, piercings ou que apresentam outras formas de exposição percutânea que não obedecem\nàs normas de biossegurança."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-334183","number":"334183","sourceNumber":"334183","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A transmissão vertical da Hepatite C é rara quando comparada à da Hepatite B.\nPodemos indicar como correto a alternativa:","options":{"A":"Entretanto, já se demonstrou que gestantes com carga viral do HCV elevada ou coinfectadas\npelo HIV apresentam menor risco de transmissão da\ndoença para os recém-nascidos.","B":"Entretanto, já se demonstrou que gestantes com carga viral do HCV elevada, mas não\ncoinfectadas pelo HIV apresentam maior risco de\ntransmissão da doença para os recém-nascidos.","C":"Entretanto, nunca se demonstrou que gestantes com carga viral do HCV elevada ou\ncoinfectadas pelo HIV apresentam maior risco\nde transmissão da doença para os recém-nascidos.","D":"Entretanto, já se demonstrou que gestantes com carga viral do HCV elevada ou coinfectadas\npelo HIV apresentam maior risco de transmissão da\ndoença para os recém-nascidos."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-315762","number":"315762","sourceNumber":"315762","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"O diagnóstico da infecção pelo vírus da hepatite A:","options":{"A":"É realizado por meio de imunoensaios que não detectam anticorpos contra o vírus em amostras\nde soro.","B":"É realizado por meio de imunoensaios que detectam anticorpos contra o vírus em amostras de\nurina.","C":"É realizado por meio de imunoensaios que detectam anticorpos contra o vírus em amostras de\nsoro.","D":"Nunca é realizado por meio de imunoensaios contra o vírus em amostras de soro."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-315770","number":"315770","sourceNumber":"315770","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A maioria das hepatites virais agudas é assintomática, independentemente do tipo de\nvírus. Sendo correto o item:","options":{"A":"Quando apresentam sintomatologia, são caracterizadas por fadiga, mal-estar, náuseas, dor\nabdominal, anorexia e não pela icterícia.","B":"Quando apresentam sintomatologia, são caracterizadas por fadiga, mal-estar, náuseas, dor\nabdominal, anorexia e icterícia.","C":"Quando apresentam sintomatologia, são caracterizadas por fadiga, mal-estar, náuseas, nunca\npor dor abdominal, anorexia e icterícia.","D":"Quando apresentam sintomatologia, são não podem ser caracterizadas por fadiga, mal-estar,\nnáuseas, dor abdominal, anorexia e icterícia."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-315772","number":"315772","sourceNumber":"315772","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Os testes para anti-HAV total (IgM e IgG) ou para o anti-HAV IgG permanecem\nreagentes após a infecção ou imunização durante\ntoda a vida do paciente, sendo:","options":{"A":"Inúteis apenas para identificar indivíduos em risco por não terem sido previamente imunizados.","B":"Úteis apenas para identificar indivíduos em risco por terem sido previamente imunizados.","C":"Úteis apenas para identificar indivíduos sem risco por não terem sido previamente imunizados.","D":"Úteis apenas para identificar indivíduos em risco por não terem sido previamente imunizados."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-315773","number":"315773","sourceNumber":"315773","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"O dano hepatocelular não é resultado de um efeito citopático direto do HAV, mas de um\nprocesso mediado pela resposta imune do hospedeiro. Sendo correto o item :","options":{"A":"Uma resposta imunológica forte, que se reflete em uma redução acentuada do RNA viral durante\na infecção aguda, está associada com a hepatite\naguda e, eventualmente, com forma fulminante da\ndoença.","B":"Uma resposta imunológica fraca, que se reflete em uma redução acentuada do RNA viral\ndurante a infecção aguda, está associada com a hepatite aguda e, eventualmente, com forma\nfulminante da doença.","C":"Uma resposta imunológica forte, que se reflete em uma redução acentuada do RNA viral durante\na infecção aguda, não está associada com a\nhepatite aguda e, eventualmente, com forma\nfulminante da doença.","D":"Uma resposta imunológica forte, que se reflete em uma redução acentuada do RNA viral durante\na infecção aguda, está associada com a hepatite\naguda e, mas não com a forma fulminante da\ndoença."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-315775","number":"315775","sourceNumber":"315775","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"As respostas imunes humorais e celulares costumam manifestar-se pouco antes da\nelevação das transaminases na hepatite A. Sendo correto o item:","options":{"A":"A imunoglobulina da classe IgM anti-HAV não pode ser detectada antes ou no momento da\nmanifestação dos sintomas clínicos e decai em cerca de três a seis meses, tornando-se\nindetectável pelos testes diagnósticos disponíveis.","B":"A imunoglobulina da classe IgM anti-HAV pode ser detectada antes ou no momento da\nmanifestação dos sintomas clínicos e decai em cerca de três a seis meses, tornando-se\nindetectável pelos testes diagnósticos disponíveis.","C":"A imunoglobulina da classe IgM anti-HAV pode ser detectada antes, mas nunca no momento da\nmanifestação dos sintomas clínicos e decai em cerca de três a seis meses, tornando-se\nindetectável pelos testes diagnósticos disponíveis.","D":"A imunoglobulina da classe IgM anti-HAV pode ser detectada antes ou no momento da\nmanifestação dos sintomas clínicos e decai em\ncerca de três a seis meses, tornando-se detectável\npelos testes diagnósticos disponíveis."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-315776","number":"315776","sourceNumber":"315776","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Os imunoensaios para IgM anti-HAV apresentam sensibilidade de 100%, especificidade\nde 99% e valor preditivo positivo de 88%.\nSendo correto que:","options":{"A":"Resultados falso-reagentes não podem ocorrer e, portanto, o teste sorológico deve ser realizado\napenas em indivíduos sintomáticos.","B":"Resultados falso-reagentes podem ocorrer e, portanto, o teste sorológico deve ser realizado\napenas em indivíduos assintomáticos.","C":"Resultados falso-reagentes podem ocorrer e, portanto, o teste sorológico sempre deve ser\nrealizado apenas em indivíduos assintomáticos.","D":"Resultados falso-reagentes podem ocorrer e, portanto, o teste sorológico deve ser realizado\napenas em indivíduos sintomáticos."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-316322","number":"316322","sourceNumber":"316322","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente de 44 anos fez exames laboratoriais que mostraram os seguintes resultados:\nHBsAg negativo, anti-HBC IgG positivo,\nanti-HBs positivo, HBeAg negativo. Esse perfil sorológico é\ncompatível com:","options":{"A":"Hepatite B aguda.","B":"Hepatite B crônica.","C":"Vacinação para hepatite B.","D":"O paciente teve contato com o vírus da hepatite B e evoluiu com cura."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-300928","number":"300928","sourceNumber":"300928","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Pacientes em uso de ribavirina devem realizar hemograma e teste de creatinina nas\nsemanas 4, 8 e 12 para avaliar anemia, ou\ncom maior frequência, caso necessário. Está\nCORRETO que:","options":{"A":"Nos casos de surgimento de anemia, a dose de ribavirina não pode ser ajustada, levando-se em\nconsideração a gravidade da anemia, a função renal e a presença de comorbidades, com especial\natenção aos portadores de doença renal grave.","B":"Nos casos de surgimento de anemia, a dose de ribavirina pode ser ajustada, levando-se em\nconsideração a gravidade da anemia, a função renal e não a presença de comorbidades, com\nespecial atenção aos portadores de doença renal grave.","C":"Nos casos de surgimento de anemia, a dose de ribavirina pode ser ajustada, levando-se em\nconsideração a gravidade da anemia, a função renal e a presença de comorbidades, exceto aos\nportadores de doença renal grave.","D":"Nos casos de surgimento de anemia, a dose de ribavirina pode ser ajustada, levando-se em\nconsideração a gravidade da anemia, a função renal e a presença de comorbidades, com especial\natenção aos portadores de doença renal grave."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-300929","number":"300929","sourceNumber":"300929","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"O objetivo do tratamento é a obtenção da Resposta Virológica Sustentada (RVS), que\nse caracteriza pela ausência de HCV-RNA na 12ª ou\n24ª semana após o término da terapia\nmedicamentosa. Está CORRETO que:","options":{"A":"A realização do teste para identificação do HCV-RNA por método de biologia molecular está\nindicada para confirmar o diagnóstico de hepatite C crônica imediatamente antes de iniciar o\ntratamento, e na 12ª ou 24ª semana após o término do tratamento, para avaliar a efetividade\nterapêutica.","B":"A realização do teste para identificação do HCV-DNA por método de biologia molecular está\nindicada para confirmar o diagnóstico de hepatite C crônica imediatamente antes de iniciar o\ntratamento, e na 12ª ou 24ª semana após o término do tratamento, para avaliar a efetividade\nterapêutica.","C":"A realização do teste para identificação do HCV-RNA por método de biologia molecular está\nindicada para confirmar o diagnóstico de hepatite C aguda imediatamente antes de iniciar o\ntratamento, e na 12ª ou 24ª semana após o término do tratamento, para avaliar a efetividade\nterapêutica.","D":"A realização do teste para identificação do HCV-RNA por método de biologia molecular está\nindicada para confirmar o diagnóstico de hepatite C crônica imediatamente antes de iniciar o\ntratamento, e na 12ª ou 24ª semana após o inicio do tratamento, para avaliar a efetividade\nterapêutica."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-308251","number":"308251","sourceNumber":"308251","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente L.C.S.B., 32 anos, comparece à consulta para segunda consulta de rotina do\npré-natal. Está muito aflita porque abriu os resultados dos seus exames e leu que estava com\nhepatite B. O médico então realiza sua consulta normalmente e, quando olha os exames\nlaboratoriais se depara com o seguinte resultado: O médico então deverá:","options":{"A":"Orientar sobre o diagnóstico de hepatite B e encaminhar ao hepatologista.","B":"Solicitar novo exame para confirmação.","C":"Informar que a paciente tem imunidade contra a hepatite B.","D":"Encaminhar a paciente à sala de vacina."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":["question_bank/media/medcurso/medcurso-hepato-hep-1/308251.png"],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-281248","number":"281248","sourceNumber":"281248","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"O RNA do HCV pode ser identificado no soro ou plasma antes da presença do\nanti-HCV. Sendo correto o item:","options":{"A":"A presença do HCV-RNA não pode ocorrer cerca de duas semanas após a exposição ao agente\ninfeccioso.","B":"A presença do HCV-RNA pode ocorrer cerca de dez semanas após a exposição ao agente\ninfeccioso.","C":"A presença do HCV-RNA pode ocorrer cerca de duas semanas antes da exposição ao agente\ninfeccioso.","D":"A presença do HCV-RNA pode ocorrer cerca de duas semanas após a exposição ao agente\ninfeccioso."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-285063","number":"285063","sourceNumber":"285063","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Mulher, 22 anos, assintomática procura consulta médica para orientação quanto à\nvacinação de hepatite. Traz exames realizados recentemente com anti-HBs negativo, HBsAg\nnegativo, anti-HCV negativo, anti-HVA IgM negativo e anti-HVA positivo. Nesse caso:","options":{"A":"Não há necessidade de se vacinar. Está protegida para as hepatites virais.","B":"Está protegida de hepatite A, mas suscetível às hepatites B e C. Deve ser orientada a procurar\nUBS para vacinação contra hepatites B e C.","C":"Está protegida de hepatite A e B, mas suscetível à hepatite C. Deve ser orientada a procurar\nUBS para vacinação contra hepatite C.","D":"É suscetível às três formas de hepatite. Deve ser orientada a procurar UBS para vacinação\ncontra hepatite B.","E":"Está protegida de hepatite A, mas suscetível às hepatites B e C. Deve ser orientada a procurar\nUBS para vacinação contra hepatite B."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-281256","number":"281256","sourceNumber":"281256","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Em determinadas situações clínicas, a exemplo de pacientes com doença aguda pelo\nHCV em fase inicial (até 30 dias) e pacientes imunodeprimidos e/ou dialíticos, está correto o item:","options":{"A":"Deve haver somente a presença de anticorpos anti-HCV, em razão da incapacidade imunológica\ndesses pacientes para produzir anticorpos.","B":"Deve haver presença de anticorpos anti-HCV, em razão da capacidade imunológica desses\npacientes para produzir anticorpos.","C":"Pode não haver presença de anticorpos anti-HCV, em razão da incapacidade imunológica\ndesses pacientes para produzir anticorpos.","D":"Nunca pode não haver presença de anticorpos anti-HCV, em razão da incapacidade imunológica\ndesses pacientes para produzir anticorpos."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-277402","number":"277402","sourceNumber":"277402","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Um paciente de 31 anos, portador de doença de Chron, iniciará tratamento com droga\nbiológica, infliximabe (anti-TNF) e está preocupado que a diminuição da imunidade provocada pela\nmedicação pode reativar algumas doenças infecciosas. Em qual dos achados sorológicos a seguir\nnão há risco de infecção ou reativação pelo vírus da hepatite B ao iniciarmos o tratamento com uma\ndroga imunossupressora?","options":{"A":"HBsAg positivo, anti-HBs negativo, anti-HBc positivo","B":"HBsAg negativo, anti-HBs positivo, anti-HBc positivo","C":"HBsAg negativo, anti-HBs negativo, anti-HBc positivo","D":"HBsAg negativo, anti-HBs positivo, anti-HBc negativo"},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-258174","number":"258174","sourceNumber":"258174","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Leia o caso clínico a seguir. Paciente com 30 anos teve diagnóstico de hepatite C\ncrônica com grau 1 de fibrose, sem qualquer\ncomorbidade. Submetido a tratamento com sofosbuvir\ne ledipasvir por 12 semanas, apresenta HCV-RNA não detectado três meses após o fim do\ntratamento. De acordo com o \"Protocolo Clínico e Diretrizes Terapêuticas para Hepatite C\" do\nMinistério da Saúde de 2019, qual deve ser a conduta?","options":{"A":"Receber alta ambulatorial com aconselhamento para evitar reinfecção.","B":"Realizar HCV-RNA anualmente durante três anos.","C":"Monitorizar com anti-HCV anualmente, devido ao alto custo e pouca disponibilidade do exame\nHCV-RNA.","D":"Acompanhar ambulatorialmente por tempo indefinido devido ao alto risco de recidiva viral e\ndesenvolvimento de cirrose."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-265866","number":"265866","sourceNumber":"265866","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A reativação viral da hepatite B tem sido descrita em pacientes tratados com DAA\nantivirais de ação direta durante ou após o término do tratamento. Sendo assim:","options":{"A":"Os indivíduos com HBsAg reagente devem realizar o teste de HBV-DNA (CV-HBV), e os casos\ncom indicação de tratamento para hepatite B\ndevem iniciá-lo previamente ou de forma\nconcomitante ao início da terapia para hepatite C.","B":"Os indivíduos com HBsAg reagente não devem realizar o teste de HBV-DNA (CV-HBV), e os\ncasos com indicação de tratamento para\nhepatite B devem iniciá-lo previamente ou de forma\nconcomitante ao início da terapia para hepatite C.","C":"Os indivíduos com HBsAg reagente devem realizar o teste de HBV-DNA (CV-HBV), e os casos\ncom indicação de tratamento para hepatite B\ndevem iniciá-lo previamente e nunca de forma\nconcomitante ao início da terapia para hepatite C.","D":"Os indivíduos com HBsAg reagente não devem realizar o teste de HBV-DNA (CV-HBV), e os\ncasos com indicação de tratamento para\nhepatite B devem iniciá-lo de forma concomitante ao início\nda terapia para hepatite C."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-265867","number":"265867","sourceNumber":"265867","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Em pacientes com Hepatite C, a condição de similaridade permite que a análise da\noferta dos esquemas terapêuticos no SUS seja\nbaseada em uma análise de custo-minimização, ou\nseja, está de acordo com o item CORRETO:","options":{"A":"Priorização das alternativas que implicam um maior impacto financeiro ao sistema, sem deixar\nde garantir o acesso a terapias seguras e\neficazes às pessoas com hepatite C.","B":"Priorização das alternativas que implicam um menor impacto financeiro ao sistema, sem deixar\nde garantir o acesso a terapias seguras e\neficazes às pessoas com hepatite C.","C":"Priorização das alternativas que implicam um menor impacto financeiro ao sistema, mesmo\ndeixando de garantir o acesso a terapias seguras e eficazes às pessoas com hepatite C.","D":"Priorização das alternativas que não implicam um menor impacto financeiro ao sistema, sem\ndeixar de garantir o acesso a terapias seguras e eficazes às pessoas com hepatite C."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-265890","number":"265890","sourceNumber":"265890","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A hepatite crônica pelo HCV é uma doença de caráter insidioso e se caracteriza por um\nprocesso inflamatório persistente. Somente podemos CONCORDAR que:","options":{"A":"Esse fato reitera a importância do conhecimento técnico por toda a equipe multiprofissional, bem\ncomo o aumento da oferta de testes\nsorológicos - especialmente para as populações vulneráveis\nao HCV.","B":"Na ausência de tratamento, há cronificação em 60% a 85% dos casos e, em média, 90%\nevoluem para cirrose ao longo do tempo.","C":"Uma vez estabelecido o diagnóstico de cirrose hepática, não ocorre o risco para o surgimento de\ncarcinoma hepatocelular.","D":"O risco de descompensação hepática não existe."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-265893","number":"265893","sourceNumber":"265893","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"O uso associado de imunoglobulina hiperimune contra hepatite B está indicado em\ncaso de pessoa-fonte com alto risco para\ninfecção pelo HBV, como listados abaixo, indique a opção\nINCORRETA:","options":{"A":"Usuários de drogas injetáveis e pacientes em programas de diálise.","B":"Contatos domiciliares e sexuais de pessoas HBsAg reagentes, pessoas que fazem sexo com\npessoas do mesmo sexo.","C":"Heterossexuais com único parceiro e relações sexuais protegidas.","D":"História prévia de IST (Infecções Sexualmente Transmissíveis); pacientes provenientes de áreas\ngeográficas de alta endemicidade para hepatite B, pacientes provenientes de prisões e de\ninstituições de atendimento a pacientes com deficiência mental."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-265899","number":"265899","sourceNumber":"265899","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A transmissão sexual do vírus HCV é possível, principalmente em práticas sexuais\ntraumáticas, presença de doença ulcerativa\ngenital e proctites, isso ocorrendo apesar de o risco de\ntransmissão do HCV estar mais relacionado às exposições percutâneas. Podemos assim\nCONCORDAR que:","options":{"A":"Grupos específicos, como pessoas vivendo com HIV-PVHIV, e portadores de outras\nimunodeficiências não têm risco acrescido de contágio pela via sexual.","B":"Grupos específicos, como as pessoas vivendo com HIV-PVHIV, mas não portadores de outras\nimunodeficiências, também têm risco acrescido de contágio pela via sexual.","C":"Grupos específicos, como as pessoas vivendo com HIV-PVHIV, e portadores de outras\nimunodeficiências também têm risco acrescido de contágio pela via sexual.","D":"Grupos específicos, como as pessoas vivendo com HIV-PVHIV, e portadores de outras\nimunodeficiências também tem risco igual de contágio pela via sexual."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-249462","number":"249462","sourceNumber":"249462","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Os pacientes co-infectados pelo HIV que desenvolvem hepatite aguda pelo HBV têm\ncinco a seis vezes mais chance de se\ntornarem portadores crônicos do HBV, quando comparados a\nindivíduos soronegativos para o HIV. Assim, podemos aceitar que:","options":{"A":"A história da infecção pelo vírus da hepatite B é melhorada pelo HIV.","B":"A história natural da infecção pelo vírus da hepatite B não é alterada pelo HIV.","C":"A história natural da infecção pelo vírus da hepatite B é independente do HIV.","D":"A história natural da infecção pelo vírus da hepatite B é alterada pelo HIV."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-249469","number":"249469","sourceNumber":"249469","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Todo tratamento da hepatite B deverá ser interrompido, independentemente do\nesquema terapêutico, nas seguintes situações listadas\nabaixo, exceto:","options":{"A":"Ocorrência de eventos adversos importantes.","B":"Ausência de adesão ao tratamento.","C":"Identificação de situação que contra indique a modalidade de tratamento.","D":"Identificação de situação que não demande substituição do tratamento."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-249470","number":"249470","sourceNumber":"249470","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Quando analisamos situações clínicas, de pacientes com doença aguda pelo HCV em\nfase inicial (até 30 dias) e pacientes imunodeprimidos e/ou dialíticos, pode não haver presença de\nanticorpos anti-HCV, em razão da incapacidade imunológica desses pacientes para produzir\nanticorpos. Podemos apenas aceitar que:","options":{"A":"Nessas situações, o diagnóstico da infecção pelo HCV não deverá ser realizado pela presença\ndo HCV-RNA, por método de biologia molecular.","B":"Nessas situações, o diagnóstico da infecção pelo HCV deverá ser realizado pela presença do\nHCV-RNA, por método de biologia molecular.","C":"Nessas situações, o diagnóstico da infecção pelo HCV deverá ser realizado pela ausência do\nHCV-RNA, por método de biologia molecular.","D":"Nessas situações, não é possível o diagnóstico da infecção pelo HCV por método de biologia\nmolecular."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-249474","number":"249474","sourceNumber":"249474","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Na realização de biópsia hepática em cirurgia, orienta-se o cirurgião a realizar coleta\nde\nmaterial em cunha profunda e evitar a região subcapsular. Podemos apenas aceitar que:","options":{"A":"A biópsia também pode ser realizada por via transjugular, mas a realização desse procedimento\nestá restrita aos centros de baixa complexidade,\nmediante a contraindicação dos demais métodos\napresentados.","B":"A biópsia também pode ser realizada por via transjugular, mas a realização desse procedimento\nestá restrita aos centros de alta complexidade,\nmediante a contraindicação dos demais métodos\napresentados.","C":"A biópsia nunca pode ser realizada por via transjugular.","D":"A biópsia também pode ser realizada por via transarterial, mas a realização desse procedimento\nestá restrita aos centros de alta complexidade,\nmediante a contraindicação dos demais métodos\napresentados."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-234363","number":"234363","sourceNumber":"234363","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A infecção pelo vírus da hepatite C (VHC) atinge milhões de pessoas em todo o mundo\ne é uma das principais causas de\nmorbimortalidade relacionadas ao fígado. Na contaminação pelo\nVHC:","options":{"A":"A transmissão sexual ocorre mais comumente entre casais heterossexuais do que entre homens\nque fazem sexo com homens.","B":"A transmissão hospitalar de paciente para paciente pode ocorrer por meio de colonoscópio,\ndiálise ou cirurgia contaminados.","C":"A transfusão de sangue permanece entre os meios mais comuns.","D":"A transmissão vertical é comum e pode resultar da amamentação."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-249539","number":"249539","sourceNumber":"249539","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Recomenda-se que, ao início do tratamento ou durante o mesmo, todos os\nmedicamentos em uso pelo paciente sejam\navaliados em relação a possíveis interações\nmedicamentosas. Em particular, os pacientes coinfectados pelo HIV devem ser monitorados em\nrelação a possíveis interações dos Antivirais de Ação Direta com a terapia antirretroviral.\n\nSIMEPREVIR, indique qual item não procede.","options":{"A":"Não deve ser utilizado com os antirretrovirais efavirenz, nevirapina, etravirina, tenofovir e a\nclasse de inibidores de protease.","B":"As dosagens de alguns antiarrítmicos, bloqueadores de canais de cálcio, estatinas, inibidores da\nfosfodiesterase tipo 5 e sedativos/ansiolíticos ? além da varfarina ? devem ser ajustadas.","C":"A medicação pode ser usada com carbamazepina, fenobarbital, fenitoína, eritromicina,\nclaritromicina, rifampicina, rifabutina, telitromicina,\nitraconazol, cetoconazol, posaconazol,\nfluconazol, voriconazol, dexametasona, cisaprida, erva de são joão (Hypericum perforatum) e\nsilimarina (Silybum marianum).","D":"Recomenda-se a prévia consulta de potenciais interações."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-249541","number":"249541","sourceNumber":"249541","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Todos os medicamentos de ação direta apresentam, em maior ou menor frequência,\nimportantes interações medicamentosas com diferentes fármacos. No caso do SOFOSBUVIR,\nsomente sendo incorreto que:","options":{"A":"não deve ser coadministrado com rifampicina, rifabutina, rifapentina, carbamazepina, fenitoína,\nfenobarbital, oxcarbamazepina, erva de são joão (Hypericum perforatum) .","B":"da mesma forma, não se recomenda o tipranavir/ritonavir em associação ao sofosbuvir.","C":"não se conhecem as interações do fármaco com anticoncepcionais hormonais.","D":"não deve ser coadministrado com alguns antiarrítmicos, exceto a amiodarona"},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-229588","number":"229588","sourceNumber":"229588","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A transmissão sexual do HCV também tem sido relatada de forma esporádica.\nPodemos assim CONCORDAR que:","options":{"A":"De modo geral, a transmissão sexual desse vírus é comum e ocorre em relações sem uso de\npreservativo.","B":"De modo geral, a transmissão sexual desse vírus é pouco comum e ocorre em relações com uso\nde preservativo.","C":"De modo geral, a transmissão sexual desse vírus é inexistente em relações sem uso de\npreservativo.","D":"De modo geral, a transmissão sexual desse vírus é pouco comum e ocorre em relações sem uso\nde preservativo."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-229590","number":"229590","sourceNumber":"229590","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"As orientações para prevenção das hepatites virais devem ser compartilhadas com os\ncontatos domiciliares e parceiros sexuais da pessoa. Somente NÃO podemos concordar com o\nitem:","options":{"A":"A única forma de reduzir o risco de transmissão é a prevenção do acidente. A prevenção requer\natitudes e práticas seguras","B":"Uso adequado do preservativo não altera o risco.","C":"Não compartilhamento de instrumentos perfurocortantes.","D":"Não compartilhamento objetos de higiene pessoal, como escovas de dente, alicates de unha,\nlâminas de barbear ou depilar."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-229592","number":"229592","sourceNumber":"229592","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A evolução para óbito, geralmente, decorre de complicações da hepatopatia crônica,\ncomo insuficiência hepatocelular, hipertensão\nportal (varizes gastresofágicas, hemorragia digestiva\nalta, ascite) e encefalopatia hepática, além de trombocitopenia e desenvolvimento de CHC.\nSomente NÃO podemos aceitar que:","options":{"A":"Após um primeiro episódio de descompensação hepática, o risco de óbito, nos 12 meses\nseguintes, é de 15% a 20%","B":"O genótipo 1 e prevalente no mundo, sendo responsável por 46% de todas as infecções pelo\nHCV.","C":"Por representarem um problema de saúde pública no Brasil, as hepatites virais são agravos de\nnotificação compulsória desde o ano de 1996.","D":"A taxa de progressão para cirrose é variável e pode ser mais acelerada em determinados grupos\nde pacientes, como alcoolistas, mas inalterados\nem coinfectados pelo HIV."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-229594","number":"229594","sourceNumber":"229594","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"São grupos populacionais que devem também ser prioritariamente testados, quanto à\npresença do HCV por sua maior vulnerabilidade no que concerne à chance de exposição. Sendo\nINCORRETA a alternativa:","options":{"A":"Pessoas que receberam transfusão de sangue ou hemoderivados antes de 1993 ou transplantes\nantes de 1980.","B":"Pessoas com antecedente de exposição percutânea/parenteral a sangue ou outros materiais\nbiológicos.","C":"Pessoas com antecedente ou em risco de exposição a sangue ou outros materiais biológicos\ncontaminados: profissionais de saúde, cuidadores de pacientes, bombeiros, policiais, etc.","D":"Crianças nascidas de mães que vivem com o HCV."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-229608","number":"229608","sourceNumber":"229608","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Alguns desses grupos populacionais, por sua maior vulnerabilidade no que concerne à\nchance de exposição ao HCV, devem ser\ntestados de forma periódica pelo menos uma vez ao ano\nou em intervalo menor, se clinicamente indicado, somente sendo INADEQUADA a alternativa:","options":{"A":"Pessoas Vivendo com o Vírus da Imunodeficiência Humana (HIV) ? PVHIV.","B":"Pessoas com múltiplas infecções sexualmente transmissíveis.","C":"Pessoas com múltiplos parceiros sexuais.","D":"Pessoas sexualmente inativas prestes a iniciar Profilaxia Pré-Exposição (PrEP) ao HIV."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-229609","number":"229609","sourceNumber":"229609","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A presença dos anticorpos anti-HCV é mais tardia e ocorre cerca de 30 a 60 dias após\na exposição ao vírus. Assinale a alternativa\nERRADA:","options":{"A":"Os níveis séricos do HCV-RNA atingindo os valores máximos de 105 a 107 UI/mL\nimediatamente após o pico dos níveis séricos\nde aminotransferases, podendo coincidir com o início\ndos sintomas.","B":"Os níveis séricos do HCV-RNA aumentam rapidamente durante as primeiras semanas.","C":"O RNA do HCV pode ser identificado no soro ou plasma antes da presença do anti-HCV.","D":"A presença do HCV-RNA pode ocorrer cerca de duas semanas após a exposição ao agente\ninfeccioso."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-216557","number":"216557","sourceNumber":"216557","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A veia porta forma-se atrás do colo do pâncreas, na confluência da veia mesentérica.","options":{"A":"Superior e da veia gástrica direita.","B":"Superior e da veia esplênica.","C":"Inferior e da veia esplênica.","D":"Inferior e da veia gástrica direita."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-217043","number":"217043","sourceNumber":"217043","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Com relação ao tratamento da infecção pelo vírus da hepatite B (HBV), de acordo com\nas diretrizes do Ministério da Saúde, assinale\na alternativa correta.","options":{"A":"A alfainterferona é indicada para tratamento alternativo de duração de 46 semanas.","B":"A alfainterferona é reservada a pacientes portadores do HBV com exame anti-HBe reagente.","C":"Os análogos de nucleotídeo tenofovir e entecavir são opções de monoterapia equivalentes em\neficácia.","D":"Deve-se evitar o uso de tenofovir em pacientes em pacientes com uso prévio de lamivudina e\ntelbivudina.","E":"O tenofovir apresenta baixa barreira genética de resistência contra as mutações do HBV."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-205621","number":"205621","sourceNumber":"205621","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"As hepatites virais são doenças causadas por diferentes vírus hepatotrópicos os mais\nrelevantes são os vírus A (HAV), B (HBV), C (HCV), D (HDV) e E (HEV). Esses vírus pertencem,\nrespectivamente, às seguintes famílias: Picornaviridae, Hepadnaviridae, Flaviviridae, Deltaviridae e\nHepeviridae. Sendo INCORRETO que:","options":{"A":"Após entrar em contato com o vírus, o indivíduo pode desenvolver hepatite aguda\noligo/assintomática ou sintomática. Esse quadro\nagudo pode ocorrer na infecção por qualquer um\ndos vírus e possui seus aspectos clínicos e virológicos limitados aos primeiros 6 meses.","B":"Anteriormente ao aparecimento da icterícia, os sintomas são inespecíficos: anorexia, náuseas,\nvômitos, diarréia ou, raramente, constipação, febre baixa, cefaleia, mal-estar, astenia e fadiga,\naversão ao paladar e/ou olfato, mialgia, fotofobia, desconforto no hipocôndrio direito, urticária,\nartralgia ou artrite e exantema papular ou maculopapular.","C":"Indivíduos com infecção crônica, que não apresentam manifestações clínicas, com replicação\nviral baixa ou ausente e que não apresentam\nevidências de alterações graves à histologia hepática,\nsão considerados portadores assintomáticos.","D":"Hepatite fulminante é termo utilizado para designar a insuficiência hepática crônica,\ncaracterizada pelo surgimento de icterícia,\ncoagulopatia e encefalopatia hepática em um intervalo\nde até 18 semanas."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-205626","number":"205626","sourceNumber":"205626","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Das alternativas abaixo, qual NÃO é uma alteração hepatobiliar que ocorre com o\navançar da idade?","options":{"A":"Redução do número de hepatócitos.","B":"Capacidade de síntese reduzida.","C":"Declínio no fluxo sanguíneo hepático.","D":"Aumento da sensibilidade e redução da depuração de certas drogas."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-214179","number":"214179","sourceNumber":"214179","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Profissional da saúde faz dosagem de HBSAg não reagente e anti-HBS de 10ui/ml.\nNesse caso pode-se dizer que","options":{"A":"não é necessário fazer reforço da vacina contra hepatite B; esse resultado já confere proteção\ncontra essa doença.","B":"é recomendado fazer uma dose da vacina de reforço.","C":"é recomendado fazer o esquema da vacinação completa.","D":"não se recomenda fazer vacinação, pois esse resultado já demostra haver hepatite crônica."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-205641","number":"205641","sourceNumber":"205641","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Com relação à anatomia segmentar hepática, assinale a alternativa INCORRETA:","options":{"A":"O lobo esquerdo do fígado, suprido pela veia porta esquerda, compõe os segmentos II ao IV.","B":"O segmento IV é dividido em segmentos IVA, acima, e segmento IVB abaixo da inserção da veia\nporta.","C":"A veia hepática média drena o segmento medial do lobo esquerdo e uma pequena quantidade\nde porções mediais dos segmentos V e VI.","D":"A veia porta direita irriga o lobo direito do fígado e o divide em setores anterior e posterior."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-178783","number":"178783","sourceNumber":"178783","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"As duas veias responsáveis pela formação da veia porta são:","options":{"A":"mesentérica inferior e mesentérica superior.","B":"esplênica e mesentérica superior.","C":"esplênica e gastroduodenal.","D":"esplênica e mesentérica inferior.","E":"mesentérica superior e gastroduodenal."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-187562","number":"187562","sourceNumber":"187562","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Uma paciente com 32 anos de idade, sem-história prévia de doença hepática,\napresenta-se ictérica há 1 semana. referindo\nmal estar e náuseas. Os exames laboratoriais\nevidenciam: TGO: 1500UI/I (valor de referência (nr) = 31 UI/L), TGP: 3400 UI/I (nr = 31 UI/L), FA:\n457 UI/L (nr = 105 UI/L), Gama-GT: 340 UI/L (nr = 28 UI/L), BT: 13.5 mg/dl (BD: 10 mg/dl). Hb: 15 e\n\nHt: 48%. Para elucidar o caso são necessários os seguintes exames sorológicos:","options":{"A":"HBsAg / Anti-HBc lgG / Anti- HAV lgG / Anti - HCV.","B":"HBsAg / Anti-HBc lgM / Anti- HAV lgM/ Anti - HCV.","C":"HBsAg /HBcAg / Anti- HAV lgM / Anti-HBs / Anti-HCV.","D":"HBsAg / Anti-HBc lgM/ Anti- HAV lgG / Anti - HCV."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-183298","number":"183298","sourceNumber":"183298","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Todas as gestantes e suas parcerias sexuais devem ser investigadas para Infecções\nSexualmente Transmissíveis IST e informadas sobre a possibilidade de infecções perinatais. A\ntriagem de IST durante a gravidez é uma intervenção eficaz, mas cuja efetividade depende de\nvários fatores (ex.: agravo/doença, acesso ao serviço de saúde, ampliação da cobertura de\ntestagem e tratamento, entre outros). Das informações relevantes sobre a triagem de IST na\ngestação, indique o item INADEQUADO:","options":{"A":"HIV na primeira consulta do pré-natal, idealmente no primeiro e no terceiro trimestre da\ngestação. Porém, no caso de gestantes que não\ntiveram acesso ao pré-natal, o diagnóstico pode\nocorrer no momento do parto, na própria maternidade, por meio do TR para HIV.","B":"Sífilis: na primeira consulta do pré-natal, idealmente no primeiro trimestre da gravidez, no\ninício\ndo terceiro trimestre (28ª semana), no momento\ndo parto (independentemente de exames\nanteriores), e em caso de abortamento.","C":"Hepatite B deve-se proceder à investigação da infecção pelo HBV na gestante com pesquisa do\nHbsAg, durante o primeiro trimestre da gestação ou quando do início do pré-natal.","D":"Hepatite C é recomendada a pesquisa de anti-HCV de rotina no pré-natal, devido ao alto índice\nde detecção do agravo em gestantes e à ausência\nde imunoprofilaxia ou intervenção\nmedicamentosa que possam prevenir a transmissão vertical da hepatite\n\nC."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-183335","number":"183335","sourceNumber":"183335","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A hepatite C é uma infecção de transmissão principalmente parenteral, e a sua história\nnatural do HCV é marcada pela evolução silenciosa. Quanto a isso, podemos considerar\nINADEQUADO que:","options":{"A":"Muitas vezes, a doença é diagnosticada décadas após a infecção, e os sinais e sintomas são\ncomuns às demais doenças parenquimatosas\ncrônicas do fígado, manifestando-se apenas em\nfases mais avançadas.","B":"O risco de infecção pelo vírus da hepatite C (HCV, do inglês Hepatitis C virus) está aumentando\nem determinadas populações, como usuários de drogas\nintravenosas ou usuários de cocaína\ninalada que compartilham os equipamentos de uso.","C":"O risco de infecção pelo vírus da hepatite C (HCV, do inglês Hepatitis C virus) está aumentando\nem determinadas populações, como em atendentes de\nconsultórios odontológicos, podólogos,\nmanicures, entre outros, que, não obedecendo às normas de biossegurança, expõem-se a sangue\npela via percutânea.","D":"A transmissão sexual do HCV é muito frequente e ainda muito discutida, ocorrendo em pessoas\ncom parcerias múltiplas e que têm relações\nsexuais sem preservativo."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-149185","number":"149185","sourceNumber":"149185","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Numa laparotomia exploradora, identifica-se lesão hepática, a qual é prontamente\nrafiada. A fim de monitorar sangramento\npós-operatório e evitar formação de abscesso subfrênico à\ndireita, o cirurgião coloca um dreno túbulo-laminar pelo flanco direito:","options":{"A":"No espaço de Morrison.","B":"Na loja de Traube.","C":"No ângulo de Hiss.","D":"Todas as alternativas estão corretas."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-127295","number":"127295","sourceNumber":"127295","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"O perfil sorológico de um indivíduo, que recebeu a vacina recombinante contra hepatite\nB, inclui resultados positivos para apenas um\ndos seguintes marcadores imunológicos. Indique-o.","options":{"A":"Antígeno de superfície da hepatite B (hbsag).","B":"Anticorpo do cerne (?core?) da hepatite B (anti-hbc).","C":"Anticorpo de superfície da hepatite B (anti-hbs).","D":"Anticorpo ?e? da hepatite B (anti-hbe)."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-136626","number":"136626","sourceNumber":"136626","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Um homem de 30 anos, assintomático, foi encaminhado pelo banco de sangue de um\nhospital para um ambulatório de clínica, porque teve seu sangue rejeitado para doação, por\napresentar na sorologia de hepatite B: HbsAg negativo e anti-HBc positivo. A história foi negativa\npara comportamento de risco para infecções sexualmente transmissíveis, transfusões e uso de\ndrogas ilícitas injetáveis; o exame físico foi normal. Testes sorológicos adicionais revelaram HBeAg\ne anti-HBcIgM negativos e anti-HBs positivo. Diante de tal caso, pode-se afirmar que esse paciente","options":{"A":"Provavelmente vai evoluir para cronificação de hepatite B.","B":"Apresenta hepatite B crônica, com replicação viral persistente.","C":"Foi previamente exposto ao vírus da hepatite B, com resolução da infecção.","D":"Persiste exposto ao vírus B da hepatite e com alto potencial de transmissibilidade."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-101159","number":"101159","sourceNumber":"101159","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"<p>A hepatite C:</p>","options":{"A":"Tem, na transmissão vertical, uma importante forma de disseminação.","B":"É uma das principais etiologias das hepatites agudas fulminantes.","C":"É a principal causa de transplante hepático atualmente.","D":"É a forma importante de contaminação em profissionais de saúde, que pode ser evitada pelo\nuso precoce de imunoglobulina hiperimune após o acidente."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-109303","number":"109303","sourceNumber":"109303","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"As hiperbilirrubinemias familiares hereditárias apresentam diferentes mecanismos\npatogênicos. Qual destas síndromes cursa com predomínio de bilirrubina conjugada?","options":{"A":"Dubin-Johnson.","B":"Gilbert.","C":"Crigler-Najjar tipo I.","D":"Crigler-Najjar tipo II."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-109319","number":"109319","sourceNumber":"109319","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Considerando o cenário epidemiológico da hepatite B, tem-se o seguinte:","options":{"A":"A hepatite B, mediante diagnóstico, requer acompanhamento dos doentes, visando à proteção\ndos contatos não infectados, não sendo, no\nentanto, uma doença de notificação e investigação\nobrigatórias.","B":"O HBV é de transmissão parenteral, sexual e materno fetal, e o portador crônico pode\ntransmiti-lo por vários anos.","C":"A vacinação é a medida mais segura para a prevenção da hepatite B, e, no Brasil, tem indicação\nrestrita a pessoas de grupos populacionais\nespecíficos, mais vulneráveis à doença.","D":"O estado de Goiás, assim como a região amazônica, é considerado área de alta endemicidade\npara hepatite B."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-109372","number":"109372","sourceNumber":"109372","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"J.V.S., de 22 anos, há sete dias iniciou quadro de febre não aferida, mal-estar,\nanorexia, náuseas e desconforto abdominal. Há\ndois dias, apresenta prurido, vômito e piora da dor\nabdominal. Refere ter percebido, nesse período, urina mais escura e olhos amarelados. No exame\nfísico, são constatadas febre (38°C), icterícia 2+ e hepatomegalia dolorosa. Nos exames colhidos,\nsão identificados TGO: 1.006; TGP: 884; bilirrubinas totais: 09; anti-HAV IgM: reagente; anti-HAV\nIgG: não reagente; HBsAg: não reagente; HBeAg: não reagente; anti-HBe: não reagente; anti-HBc:\nreagente; anti-HBs: reagente; anti-HCV: não reagente. Nesse caso, qual é o diagnóstico?","options":{"A":"Hepatite A aguda, e o paciente já foi exposto ao vírus da hepatite B.","B":"Hepatite A aguda, e o paciente já foi vacinado contra o vírus da hepatite B.","C":"Hepatite B aguda, e o paciente já foi exposto ao vírus da hepatite A.","D":"Hepatite B crônica, e o paciente já foi exposto ao vírus da hepatite A."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-83832","number":"83832","sourceNumber":"83832","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Qual destes exames laboratoriais mais especificamente indica lesão hepatocelular?","options":{"A":"TGO","B":"y-GT","C":"amilase","D":"TGP","E":"fosfatase alcalina"},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-78113","number":"78113","sourceNumber":"78113","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Em relação aos marcadores sorológicos da hepatite B, pode-se afirmar que o marcador","options":{"A":"Anti-HBs é indicativo de exposição prévia ao vírus B.","B":"Anti-HBc total define imunidade.","C":"HbsAg indica hepatite crônica pelo vírus B.","D":"HbeAg define replicação viral."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-85396","number":"85396","sourceNumber":"85396","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente do sexo feminino, 47 anos de idade, deu entrada no Pronto-Socorro com\nquadro de confusão mental de início\nprogressivo há dois dias. Associado ao quadro sonolência,\nletargia, mudança de humor e de personalidade, movimentos anormais e tremores nas mãos e,\nsegundo o acompanhante, diminuição do volume urinário. Ao exame físico, apresenta PA: 60 x 40\nmmHg, alguns hematomas nos MMSS e tronco. Sem hepato ou esplenomegalia. Icterícia discreta\n(+4/4+). Ritmo respiratório irregular. Feito ECG: bradicardia sinusal. Antecedentes: crises\nconvulsivas na adolescência em uso diário de carbamazepina e fenitoína. Faz uso esporádico de\nálcool. História de cefaleia com uso frequente de analgésicos (paracetamol) em excesso. Nega\ntabagismo, HAS ou DM. Sobre o caso acima, assinale a alternativa CORRETA.","options":{"A":"Deve-se iniciar anticoagulação com heparina de baixo peso molecular.","B":"É necessária a avaliação laboratorial: AST; ALT; TAP/INR; dosagens de fator V e VII da\ncoagulação.","C":"Avaliação laboratorial deve incluir D-dímero, BNP, glicemia e troponina.","D":"Punção lombar é mandatória nesse caso."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-63228","number":"63228","sourceNumber":"63228","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Com relação à hepatite viral, podemos afirmar que:","options":{"A":"O anti-HBc e o anti-HBs são anticorpos que protegem contra a hepatite B.","B":"O AgHBs geralmente permanece positivo só nos 15 primeiros dias da fase aguda da hepatite B\nnão fulminante.","C":"A presença do anti-HBc IgM é patognomônica de hepatite aguda pelo vírus B.","D":"O desaparecimento precoce do AgHBe na fase aguda do tipo B indica grande possibilidade de\ncura da infecção.","E":"Mães portadoras de AgHBs positivo e AgHBe positivo ou negativo têm 90% de chance de\ntransmitir o vírus B para o filho na hora do parto."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hepato-hep-1-61794","number":"61794","sourceNumber":"61794","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente de 30 anos, masculino, vai ao posto de saúde e solicita exames para hepatite\nB e C. Refere estar muito preocupado pois\nteve várias relações sexuais durante sua vida sem\npreservativo e escutou sobre hepatite na televisão. Refere estar assintomático. Retorna com os\nseguintes exames: HBsAg: não reagente Anti-HBs: reagente Anti-HBc total: reagente Anti-HBc IgM:\nnão reagente HBeAg: não reagente Anti-HBe: não reagente Anti- HCV: não reagente. O seu\ndiagnóstico é:","options":{"A":"Hepatite C crônica.","B":"Hepatite B crônica na fase replicante.","C":"Infecção passada pela hepatite B e imunidade para a mesma.","D":"Hepatite B aguda.","E":"Imunidade a hepatite B e C por resposta vacinal."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-48786","number":"48786","sourceNumber":"48786","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Gestante encaminhada ao ambulatório de pré-natal da Santa Casa de Goiânia,\napresentando resultado do teste da mamãe alterado\npara hepatite B, com HbsAg negativo, anti-Hbc\nIgG positivo e anti-Hbs Ag positivo. Tal resultado pode ser interpretado como:","options":{"A":"Imunização passiva para hepatite B.","B":"Infecção aguda para hepatite B.","C":"Infecção crônica com alta taxa de replicação viral.","D":"Imunidade adquirida por infecção passada.","E":"Gestante suscetível."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-49023","number":"49023","sourceNumber":"49023","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"As hepatites virais são um grave problema de saúde pública no mundo e no Brasil.\nSegundo estimativas, bilhões de pessoas já\ntiveram contato com o vírus da hepatite e milhões são\nportadores crônicos. A rede de assistência às hepatites virais no SUS está dividida em três níveis:\natenção básica, média, alta complexidade. De acordo com a orientação da NOAS-SUS 01/2002, o\nplanejamento regional da atenção deve ser feito de modo integrado, para que os serviços não\nfiquem restritos ao âmbito municipal, garantindo o acesso do paciente aos recursos necessários\npara resolução de seu problema. Mas para alguns tipos de hepatites existem algumas ações\nimunopreveníveis por vacina. São elas:","options":{"A":"B e C.","B":"A e B.","C":"A e C.","D":"A e D.","E":"B e E."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-47324","number":"47324","sourceNumber":"47324","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"O segmento I do fígado:","options":{"A":"faz parte do lobo direito","B":"faz parte do segmento lateral esquerdo","C":"é menos comprometido na síndrome de Budd-Chiari","D":"tem drenagem venosa prioritária para veia hepática média","E":"é também denominado de lobo quadrado"},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-47734","number":"47734","sourceNumber":"47734","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"<p>Um paciente de 26 anos, de sexo masculino, assintomático, ao se candidatar para\ndoação de sangue recebeu resultado de\nHBsAG reagente e anti-HBc IgG reagente. Vai à consulta\nno ambulatório de gastroenterologia, já com os seguintes exames: HBeAG reagente, anti-HBe\nnegativo, ALT = 21 mg/dl, Gama GT = 18 mg/dl, TAP = 100% e Bilirrubina total = 0,95. Realizou\nainda PCR quantitativo HBV-DNA, que mostrou resultado acima de 40.000.000 Ul/ml (valor máximo\ndetectável pelo método). Qual o próximo passo neste caso?</p>","options":{"A":"Realizar acompanhamento, pois provavelmente se trata de um paciente em fase de\nimunotolerância.","B":"Realizar biópsia hepática imediatamente para estadiamento da doença hepática.","C":"Indicar tratamento imediato devido à alta carga viral e ao HBeAG reagente.","D":"Administrar HBIG (Imunoglobulina hiperimune) na tentativa de eliminação do vírus, pois se trata\nde uma provável Hepatite B aguda."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-48195","number":"48195","sourceNumber":"48195","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"<p>Eduardo, 18 anos, foi admitido com hepatite viral aguda. Sobre a situação clínica, é\nINCORRETO afirmar:</p>","options":{"A":"Os primeiros sinais e sintomas são tipicamente inespecíficos.","B":"A febre, sempre presente, costuma ser baixa.","C":"A fase prodrômica pode evoluir para a fase ictérica.","D":"O desconforto abdominal pode refletir hepatomegalia dolorosa.","E":"Os vírus A, C, D e E são RNA e o vírus B é DNA."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-48159","number":"48159","sourceNumber":"48159","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Entre os marcadores listados abaixo, aquele que é considerado o mais adequado para\no diagnóstico de hepatite B é:","options":{"A":"HBcAg","B":"Anti-HBc IgM","C":"Anti-HCV","D":"HBsAg","E":"HBeAg"},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-48166","number":"48166","sourceNumber":"48166","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Entre os marcadores listados abaixo, aquele que é considerado fator de proteção para\nreinfecção pelo vírus da hepatite B é:","options":{"A":"Anti-HBs","B":"Anti-HBc","C":"Anti-HBe","D":"HBsAg","E":"HBeAg"},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-35829","number":"35829","sourceNumber":"35829","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Na hepatite fulminante, a principal causa de morte é devido a:","options":{"A":"Hipertensão intracraniana secundária ou edema cerebral.","B":"Hemorragia digestiva.","C":"Insuficiência renal aguda.","D":"Falta de acesso a drogas antivirais.","E":"Nenhuma das anteriores."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-35866","number":"35866","sourceNumber":"35866","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Gestante de 23 anos, portadora de hepatite B (Hbs Ag Positivo), apresenta quadro de\nvaricela 10 dias antes do parto, dando a luz a um RN pesando 3100 g, a termo, exame físico\nnormal. Em relação ao tratamento e aleitamento do RN, é correto afirmar que:","options":{"A":"Contraindica o aleitamento materno, realiza imunoglobulina para hepatite B, vacina para hepatite\nB e tratamento com aciclovir.","B":"Manter a mãe em isolamento, utilizar leite ordenhado da própria mãe, realizar imunoglobulina\npara hepatite B e varicela e vacina para hepatite\nB.","C":"Manter aleitamento materno sob livre demanda, realizar imunoglobulina para hepatite B e vacina\npara hepatite B.","D":"Manter aleitamento materno sob livre demanda, realizar imunoglobulina para hepatite B e\nvaricela, e vacina para hepatite B.","E":"Nenhuma é correta."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hepato-hep-1-27157","number":"27157","sourceNumber":"27157","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Em relação as hepatites virais é correto afirmar que:","options":{"A":"A hepatite A ocorre por transmissão oral-fecal e sempre tem evolução benigna.","B":"O perfil sorológico revelando anti-HbsAg positivo e anti HBc total negativo não é compatível com\no de indivíduos previamente vacinados.","C":"A evolução para cronicidade ocorre com maior frequência na hepatite B.","D":"O vírus B e C são geralmente eliminados meses após a infecção aguda.","E":"A hepatite E pode ocorrer de forma epidêmica, sendo mais grave no terceiro trimestre da\ngestação."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-8936","number":"8936","sourceNumber":"8936","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Em relação às Hepatites Virais assinale a alternativa incorreta:","options":{"A":"A Hepatite C pode ser transmitida através das relações sexuais, pela via parenteral e também da\nmãe para o feto durante a gestação","B":"A Hepatite B pode evoluir para formas crônicas, inclusive com o desenvolvimento de\nhepatocarcinoma","C":"No Brasil, a vacinação contra a Hepatite B está indicada para toda a população menor de 20\nanos e para pessoas de grupos populacionais\ncom maior risco para a doença","D":"A administração de Imunoglobulina Humana anti-Hepatite B (IGHAHB) é indicada para\nprofissionais de saúde que se acidentam com\nferimento cutâneo ou de membrana mucosa por\ninstrumento perfurocortante contaminado com sangue independente do histórico vacinal de hepatite\nB"},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-11069","number":"11069","sourceNumber":"11069","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A presença do marcador de Hepatite Anti-HCV+ tem como significado imunológico\ncorrespondente à:","options":{"A":"Doença Crônica","B":"Doença aguda","C":"Presença do vírus C na corrente sanguínea","D":"Contato do portador com vírus da Hepatite C","E":"Contato do portador com vírus da Hepatite B"},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-8946","number":"8946","sourceNumber":"8946","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Em relação às hepatites virais é correto afirmar que:","options":{"A":"A hepatite A ocorre por transmissão oral-fecal e sempre tem evolução benigna","B":"O perfil sorológico revelando anti-HbsAg positivo e anti-HBc total negativo não é compatível com\no de indivíduos previamente vacinados","C":"O vírus B e C são geralmente eliminados meses após a infecção aguda","D":"A hepatite E pode correr de forma epidêmica, sendo mais grave no terceiro trimestre da\ngestação"},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-10626","number":"10626","sourceNumber":"10626","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Qual dos seguintes marcadores virais indica o risco de infectividade na hepatite B?","options":{"A":"HBsAg.","B":"HBcAg.","C":"HBeAg.","D":"Anti-HBs.","E":"Anti-Hbc."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-16064","number":"16064","sourceNumber":"16064","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Em que situação o tratamento da Hepatite Crônica C com Interferon e Ribavirina está\nformalmente contraindicado?","options":{"A":"Valores elevados de ferritina.","B":"Cirrose Child B.","C":"Concomitância com Hepatite Crônica B.","D":"Diabetes melitus."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-176138","number":"176138","sourceNumber":"176138","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Te cnico de enfermagem recentemente submetido a avaliaça o de rotina traz os\nseguintes resultados de sorologias para ví rus B:\nHBsAg (-), Anti-HBs (+), Anti-HBc (+), Anti-HBc\nIgM (-), HBeAg (-), Anti-HBe (+). O mesmo esta angustiado e solicita sua avaliaça o para o caso\nacima. TRATA-SE DE:","options":{"A":"Hepatite B crônica","B":"Hepatite B aguda","C":"Hepatite B curada","D":"Período de incubação de hepatite B","E":"Imunização pós-vacinal"},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-62623","number":"62623","sourceNumber":"62623","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Com relação à hepatite B, podemos afirmar que:","options":{"A":"A hepatite B pode ser considerada uma das mais importantes doenças sexualmente\ntransmissíveis;","B":"Após o período de incubação, a grande maioria dos indivíduos infectados apresenta icterícia\nclínica;","C":"A presença sorológica do Ag-Hbs por mais de 6 meses por si só, caracteriza intensa replicação\nviral;","D":"Indivíduos portadores de hepatite B possuem pouca chance de desenvolver hepatocarcinoma;","E":"O surgimento do anticorpo anti-Hbs indica cronificação do processo inflamatório do fígado,\naumentando a chance de aparecimento de cirrose hepática e hepatocarcinoma."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hepato-hep-1-35779","number":"35779","sourceNumber":"35779","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Analise as afirmativas abaixo sobre insuficiência hepática aguda e a seguir marque a\nopção CORRETA:","options":{"A":"A definição mais amplamente aceita considera para diagnóstico de insuficiência hepática aguda\nevidência de coagulopatia com INR maior ou igual que 1,5 e encefalopatia graus III ou IV em\npaciente sem cirrose pré-existente e com duração da doença < 26 semanas.","B":"A reposição volêmica adequada e o manitol são medidas terapêuticas para insuficiência renal\naguda.","C":"O edema cerebral está relacionado ao grau de encefalopatia hepática, sendo raro nos graus III e\nIV.","D":"A reposição de plaquetas e plasma fresco deveria ser realizada em todos os pacientes que\napresentam plaquetas < 50.000.","E":"São sinais clínicos de hipertensão intracraniana; hipertensão (com PAS mantida > 160 mmHg ou\npicos de > 200 mmHg), bradicardia e padrão respiratório irregular."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-28186","number":"28186","sourceNumber":"28186","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Onde é sintetizada a albumina?","options":{"A":"Duodeno","B":"Fígado","C":"Intestino delgado","D":"íleo terminal","E":"Pâncreas"},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-302053","number":"302053","sourceNumber":"302053","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Analise as afirmativas abaixo sobre a segmentação hepática com base no sistema de\nclassificação preconizado por Couinard. 1- O lobo esquerdo compõe-se dos segmentos II ao IV. 2-\nOs segmentos II e III são supridos pela ramificação da veia porta esquerda, com o segmento II\nabaixo da passagem da veia porta e o segmento III acima. 3- O segmento VI é suprido pela\ndistribuição inferior da ramificação posterior da veia porta direita, enquanto o segmento VII\nrecebe o\nfluxo da distribuição superior desta ramificação. 4- O segmento V é suprido pela distribuição\nsuperior da ramificação anterior da veia porta direita, e o segmento VIII recebe o fluxo da\ndistribuição inferior desta ramificação. Das afirmativas acima, apenas:","options":{"A":"3 e 4 estão corretas.","B":"1 e 2 estão corretas.","C":"2 e 3 estão corretas.","D":"1 e 3 estão corretas.","E":"2 e 4 estão corretas."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-263713","number":"263713","sourceNumber":"263713","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Homem, 45 anos de idade, sem comorbidades, procura serviço médico com o seguinte\nresultado de sorologia para hepatite: anti-HBc total positivo, AgHBs negativo e anti-HBs positivo.\n\nQual interpretação deve ser feita?","options":{"A":"Que ele já está imune para hepatite B porque o anti-HBs está positivo, mas tem doença ativa\npara hepatite C porque o anti-HBc total é positivo, apesar do AgHBs está negativo.","B":"Que ele já está imune para hepatite B porque o anti-HBs está positivo, não tem doença ativa,\npois o AgHBs está negativo, mas ele também é imune para hepatite C, pois o anti-HBc total é\npositivo.","C":"Que ele já está parcialmente imune para hepatite B porque o anti-HBs está positivo e o AgHBs\nestá negativo, mas ele também é imune para\nhepatite C, pois o anti-HBc total é positivo.","D":"Que ele já não está imune para hepatite B apesar do anti-HBs positivo, uma vez que tem doença\nativa porque o AgHBs ainda está negativo e\nque está em fase ativa para hepatite C, pois anti-HBc\ntotal é positivo.","E":"Que ele já está imune para hepatite B porque o anti-HBs está positivo, mas não tem doença\nativa porque o AgHBs está negativo e que ele\ndeve ter se imunizado naturalmente, pois o anti-HBc\ntotal é positivo."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-278910","number":"278910","sourceNumber":"278910","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Analise as afirmativas abaixo sobre a segmentação hepática com base no sistema de\nclassificação preconizadas por Couinard. 1- O lobo esquerdo compõe-se dos segmentos II ao IV. 2-\nOs segmentos II e III são supridos pela ramificação da veia porta esquerda, com o segmento II\nabaixo da passagem da veia porta e o segmento III acima. 3- O segmento VI é suprido pela\ndistribuição inferior da ramificação posterior da veia porta direita, enquanto o segmento VII\nrecebe o\nfluxo da distribuição superior desta ramificação. 4- O segmento V é suprido pela distribuição\nsuperior da ramificação anterior da veia porta direita, e o segmento VIII recebe o fluxo da\ndistribuição inferior desta ramificação. Das afirmativas acima, apenas:","options":{"A":"1 e 2 estão corretas.","B":"3 e 4 estão corretas.","C":"1 e 3 estão corretas.","D":"2 e 3 estão corretas.","E":"2 e 4 estão corretas."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-175032","number":"175032","sourceNumber":"175032","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Ao verificar o resultado de exames laboratoriais de um paciente na atenção básica, o\nclínico depara-se com o seguinte perfil sorológico de hepatite B: HBsAg (+); anti-HBc IgG (+);\nanti-HBc IgM (-); HBeAg (-) e anti-HBs IgG (-). Logo, conclui tratar-se de:","options":{"A":"Hepatite aguda.","B":"Pós-vacina.","C":"Imunidade.","D":"Hepatite crônica inativa.","E":"Fase inicial de hepatite crônica."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-160401","number":"160401","sourceNumber":"160401","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Qual das seguintes opções se refere ao marcador sorológico de replicação do vírus da\nhepatite B?","options":{"A":"HBcAg.","B":"Anticorpo Anti-HBs.","C":"Anticorpo Anti-HBe.","D":"HBeAg.","E":"HBsAg."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-103936","number":"103936","sourceNumber":"103936","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"O rastreamento, para a detecção precoce do hepatocarcinoma em pacientes com\nhepatite crônica viral, é:","options":{"A":"Dosagem dos níveis de fosfatase alcalina.","B":"A dosagem do nível sérico da alfafetoproteína.","C":"A execução de tomografia computadorizada.","D":"A dosagem do nível sérico de alfafetoproteína associado à ultrassonografia.","E":"Dosagem do nível sérico do antígeno carcinoembrionário."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-103940","number":"103940","sourceNumber":"103940","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Na hepatite fulminante, a complicação que mais frequentemente leva ao óbito é:","options":{"A":"Hipertensão intracraniana.","B":"Coagulopatia.","C":"Hipoglicemia.","D":"Pneumonia.","E":"Falência renal."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-65601","number":"65601","sourceNumber":"65601","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"O perfil sorológico correspondente à infecção crônica inativa pelo vírus da hepatite B\né:","options":{"A":"HBsAg (+) HBeAg (+) Anti-HBc IgG (-) Anti-HBc IgM (+) Anti-HBs IgG (-);","B":"HBsAg (+) HBeAg (+) Anti-HBc IgG (+) Anti-HBc IgM (-) Anti-HBs IgG (-);","C":"HBsAg (+) HBeAg (-) Anti-HBc IgG (+) Anti-HBc IgM (-) Anti-HBs IgG (-);","D":"HBsAG (-) HBeAg (-) Anti-HBc IgG (+) Anti-Hbc IgM (-) Anti-HBs IgG (+);","E":"HBsAg (-) HBeAg (-) Anti-HBc IgG (-) Anti-HBc IgM (-) Anti-HBs IgG (+);"},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-52189","number":"52189","sourceNumber":"52189","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Assinale a alternativa incorreta, quanto aos padrões de infecção pelo vírus da hepatite\nB.","options":{"A":"HBsAg (+)/Anti - HBs (-)/Anti - HBc (IgM)/HBeAg (+)/Anti - Hbe (-) = Hepatite B aguda, alta\ninfectibilidade.","B":"HBsAg (+)/Anti - HBs (-)/Anti - HBc (IgG)/HBeAg (+)/Anti - Hbe (-) = Hepatite B crônica, baixa\ninfectibilidade.","C":"HBsAg (-)/Anti - HBs (+)/Anti - HBc (-)/HBeAg (-)/Anti - Hbe (-) = Imunização com HBsAg (após\nvacinação).","D":"HBsAg (-)/Anti - HBs (+)/Anti - HBc IgG (+)/HBeAg(-)/Anti - Hbe (+) = Resolução da Hepatite B","E":"NRA"},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hepato-hep-1-346623","number":"346623","sourceNumber":"346623","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Homem de 65 anos com obesidade central, dislipidemia e hiperglicemia de jejum\napresenta hipertransaminasemia persistente há mais de um ano. Traz consigo resultados de\nexames que mostram HBsAg positivo, HBeAg positivo, anti- HBe negativo e níveis elevados de\nHBV DNA. Acerca destas informações, assinale a alternativa CORRETA:","options":{"A":"Este paciente apresenta critérios de hepatite crônica pelo vírus B (VHB).","B":"Lamivudina é droga de primeira escolha por apresentar maior barreira genética.","C":"Na maioria destes pacientes o HBsAg negativa a longo prazo.","D":"Síndrome metabólica não é fator de risco adicional para hepatocarcinoma."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-348474","number":"348474","sourceNumber":"348474","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Homem, 16 anos, retorna em consulta na UBS com os seguintes resultados dos\nexames laboratoriais coletados devido à suspeita\nclínica de hepatite B: HBsAg positivo, Anti-HBs\nnegativo, Anti-HBc positivo, HBeAg positivo e Anti-HBe negativo. É CORRETO concluir que o\npaciente encontra-se na fase:","options":{"A":"Resolutiva da infecção, com baixa carga viral e ainda não adquiriu imunidade.","B":"Replicativa da infecção, com alta carga viral e já adquiriu imunidade.","C":"Resolutiva da infecção, com alta carga viral e já adquiriu imunidade.","D":"Replicativa da infecção, com alta carga viral e ainda não adquiriu imunidade."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-288138","number":"288138","sourceNumber":"288138","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Indivíduo vai doar sangue numa campanha de doação sanguínea do hospital Santa\nCasa. Porém, o exame anti-Hbs está reagente. Qual é o significado?","options":{"A":"Infecção por hepatite C.","B":"Infecção aguda por hepatite B.","C":"Infecção crônica por hepatite B.","D":"Imunidade contra a hepatite B."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-255341","number":"255341","sourceNumber":"255341","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Gestantes que tem hepatite B com alta replicação viral, e, portanto, altamente\ninfectantes, são as que apresentam positividade para o marcador:","options":{"A":"HBsAg.","B":"HBeAg.","C":"Anti-HBs.","D":"Anti-HBc."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-255354","number":"255354","sourceNumber":"255354","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"As principais interações observadas entre os medicamentos para o tratamento da\nhepatite C e a TARV estão detalhadas e\neventualmente, serão necessários ajustes posológicos ou\nsubstituições medicamentosas a fim de se evitarem essas interações indesejáveis. Não podemos\naceitar que:","options":{"A":"Respeitando-se o histórico de uso de TARV e genotipagens prévias, deve ser avaliada e\nconsiderada a substituição de medicamentos contra o HIV por esquemas contendo dolutegravir\n(DTG).","B":"Caso se faça alguma substituição no esquema da TARV, é obrigatório o retorno ao esquema\nanterior ao tratamento para HCV após a conclusão deste.","C":"Nos casos que por indicação médica, haja necessidade de retorno ao esquema de TARV\nanterior, esse retorno não deve ocorrer antes de\nduas semanas após a suspensão do tratamento\nda hepatite C.","D":"A extensão do uso do esquema modificado de TARV é necessária devido à meia-vida\nprolongada de alguns antivirais de ação direta DAA."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-255355","number":"255355","sourceNumber":"255355","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Plano para Eliminação da Hepatite C no Brasil como problema de saúde pública até\n2030, indica como adequado o item:","options":{"A":"Tal estratégia proporciona a redução do acesso ao tratamento medicamentoso a todos os\npacientes infectados pelo HCV, sendo fundamental para o sucesso do plano.","B":"Tal estratégia proporciona a ampliação do acesso ao tratamento medicamentoso a todos os\npacientes infectados pelo HCV, não sendo fundamental para o sucesso do plano.","C":"Tal estratégia proporciona a ampliação do acesso ao tratamento medicamentoso a todos os\npacientes infectados pelo HCV, sendo fundamental para o sucesso do plano.","D":"Tal estratégia não proporciona a ampliação do acesso ao tratamento medicamentoso a todos os\npacientes infectados pelo HCV, sendo fundamental para o sucesso do plano."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-185221","number":"185221","sourceNumber":"185221","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente de 23 anos apresenta diarreia aquosa e icterícia há 3 dias. Sem outros sinais\nou sintomas. Bilirrubina direta normal e\nindireta de 4 mg/dl. Transaminases normais. Assinale a\nalternativa com o diagnóstico que melhor explica a icterícia do paciente.","options":{"A":"Hepatite A aguda","B":"Hepatite autoimune","C":"Doença de Wilson","D":"Síndrome de Gilbert","E":"Hemocromatose"},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-181580","number":"181580","sourceNumber":"181580","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Sobre o tratamento da hepatite C, é correto afirmar:","options":{"A":"A cirrose hepática classe funcional Child-Pugh B ou C não contraindica o tratamento da hepatite\nC.","B":"O uso de peg-interferon alfa era a base do tratamento, mas o surgimento de agentes antivirais\ndiretos fez com que esse imunomodulador\ndeixasse de ter função no tratamento dessa infecção.","C":"Está indicado em pacientes com manifestações imunes extra-hepáticas, como glomerulonefrites\nou\n\ncrioglobulinemia mista, desde que haja fibrose hepática pelo menos moderada (F2).","D":"A biópsia hepática não é mandatória para decisão sobre tratamento da hepatite C, podendo ser\nsubstituída pela elastografia, pelo índice APRI ou pelo MELD."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-181099","number":"181099","sourceNumber":"181099","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Dá entrada no PS criança desacordade e crise convulsiva. Mãe refere que seu filho\nestava com quadro gripal e apresentou vómitos e cefaleia intensa em casa. Refere que somente\nutilizou aspirina para o tratamento da febre. Nos exames complementares observou-se esteatose\nhepática, edema cerebral, aumento de enzimas hepáticas e alargamento do TAP. Líquor límpido\nsem sinais de infecção no exame laboratorial. Indique a hipótese diagnostica:","options":{"A":"Síndrome de Reye;","B":"Intoxicação por salicilatos;","C":"Dengue grave;","D":"Síndrome da morte infantil aguda."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-136750","number":"136750","sourceNumber":"136750","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Qual o parâmetro mais importante na avaliação pré-operatória da reserva funcional\nhepática?","options":{"A":"Tempo de protrombina","B":"Tempo parcial de tromboplastina","C":"Albuminemia","D":"Transaminases"},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-136914","number":"136914","sourceNumber":"136914","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente oriundo de cidade do interior do Mato Grosso apresenta carta de\nencaminhamento ao ambulatório de referência\nno tratamento de doenças hepáticas constando que\no mesmo teria recebido recentemente o diagnóstico de Hepatite Viral B (HBV), após realização dos\nseguintes exames sorológicos na cidade de origem: anti-HBsAg reagente, HbsAg não reagente,\nanti-HBc total reagente (anti-HBc IgM não reagente). O mesmo desconhece sua história vacinal,\nporém relata icterícia na adolescência e ter várias tatuagens no dorso. Nesse caso, qual a\nconclusão diagnóstica?","options":{"A":"O paciente é portador de HBV crônica, deve-se realizar sua notificação imediata, solicitar a\ncarga\nviral e transaminases, inicialmente, tendo-se em vista a avaliação quanto à necessidade de início\nde tratamento.","B":"O paciente é portador de HBV aguda, tendo em vista seu anti-HBc total reagente, deve-se\nrealizar sua notificação imediata, inicia\ntratamento específico e manutenção do seguimento no\nambulatório.","C":"O paciente não é portador de HBV aguda ou mesmo crônica, tendo em vista seu HbsAg não\nreagente e anti-HbsAg reagente, porém apresenta cicatriz sorológica, demonstrada pelo anti-HBc\nIgG reagente, devendo, portanto, receber alta do ambulatório.","D":"O paciente não é portador de HBV aguda ou crônica, porém devido ao seu anti-HBsAg reagente\ndeve ser encaminhado para imunização contra\no vírus, uma vez que o mesmo encontra-se\nsuscetível."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-136733","number":"136733","sourceNumber":"136733","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Qual das afirmações abaixo está INCORRETA:","options":{"A":"A hiperbilirrubinemia pode ser devida a anormalidades na função, transporte, metabolismo ou\nexcreção da bilirrubina","B":"A icterícia com aumento de bilirrubina conjugada pode ser causada por hemólise","C":"Na avaliação icterícia obstrutiva, solicitamos primeiramente ultrassonografia e após a\ncolangiografia poderá ser necessária","D":"Aumentos persitentes e discretos dos níveis de aminotransferases são comuns na prática clínica\ne podem ser causados por esteatose hepática"},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-98042","number":"98042","sourceNumber":"98042","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"<p>Em relação à infecção pelo vírus D da hepatite, é CORRETO afirmar:</p>","options":{"A":"A coinfecção com o vírus da hepatite B aumenta o risco de hepatite fulminante, sem alterar o\nrisco de evolução para cirrose.","B":"Não está relacionada a um maior risco de desenvolvimento de hepatocarcinoma.","C":"Os marcadores sorológicos da doença, anti-HDV IgM ou IgG e a pesquisa HDV-RNA por PCR\ncostumam aparecer tardiamente, após 8 semanas da infecção.","D":"A febre de Lábrea é uma forma peculiar de apresentação da infecção, caracterizada por\nnecrose hepatocelular moderada, balonização e\naumento do volume dos hepatócitos, com gotas\nde gordura no citoplasma, circundando o núcleo (espongiócitos)."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-98030","number":"98030","sourceNumber":"98030","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Visando à avaliação dos riscos para transmissão vertical do vírus da hepatite B, o\nmédico do PSF solicitou para a gestante a realização dos exames sorológicos para essa infecção.\nO risco de transmissão vertical será maior se o resultado for positivo para:","options":{"A":"HBeAg.","B":"HBsAg.","C":"HBcAg.","D":"HBdAg."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-85003","number":"85003","sourceNumber":"85003","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente assintomático recebe o seguinte resultado de sorologia: HbsAg: não reagente;\nAnti-Hbc total: reagente; Anti-Hbc IgM: não reagente; Anti-Hbe: reagente; Anti-Hbs: reagente;\n\nAnti-HCV: não reagente. Qual é o diagnóstico?","options":{"A":"Hepatite C crônica.","B":"Infecção prévia de Hepatite B e imunidade para a mesma.","C":"Hepatite B aguda.","D":"Período da janela imunológica da Hepatite B."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-85040","number":"85040","sourceNumber":"85040","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Escolar de 8 anos de idade apresentando febre, vômitos, dor em hipocôndrio direito,\nicterícia e colúria. Quais marcadores séricos de hepatites virais devem ser solicitados para\ndefinição do agente etiológico?","options":{"A":"Anti-HAV IgM, Anti-HBc total e Anti-HBs.","B":"Anti-HAV IgM, HBsAg e Anti-HCV.","C":"Anti-HAV IgM, Anti-HBs e Anti-HCV.","D":"Anti-HAV IgM, HBsAg e Anti-HBc IgM."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-71072","number":"71072","sourceNumber":"71072","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Um paciente realiza tratamento para hepatite B há 02 anos. Se seu médico deseja\nsaber como está a replicação viral ele deverá solicitar:","options":{"A":"antígeno austrália;","B":"HBsAg;","C":"anti-HBe;","D":"anti-HBc;","E":"anti-HBs."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-360619","number":"360619","sourceNumber":"360619","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A infecção pelo HDV é dependente de uma infecção pelo HBV associada. Podemos\nindicar como correto que:","options":{"A":"A evolução da doença não está relacionada ao contato inicial com os vírus. Caso a infecção pelo\nHBV e pelo HDV seja simultânea, não é denominada coinfecção.","B":"A evolução da doença está relacionada ao contato inicial com os vírus. Caso a infecção pelo\nHBV e pelo HDV não seja simultânea, não é denominada coinfecção.","C":"A evolução da doença está relacionada ao contato inicial com os vírus. Caso a infecção pelo\nHBV e pelo HDV seja simultânea, é denominada coinfecção.","D":"A evolução da doença não está relacionada ao contato inicial com os vírus. Caso a infecção pelo\nHBV e pelo HDV seja simultânea, não pode ser considerada coinfecção."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-330627","number":"330627","sourceNumber":"330627","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A infecção por HAV em indivíduos com mais de 50 anos:","options":{"A":"Evolui de forma mais leve e assintomática, ocorrendo icterícia em mais de 70% dos pacientes.","B":"Evolui de forma mais grave e sintomática, ocorrendo icterícia em mais de 99% dos pacientes.","C":"Evolui de forma mais grave e sempre assintomática, ocorrendo icterícia em mais de 70% dos\npacientes.","D":"Evolui de forma mais grave e sintomática, ocorrendo icterícia em mais de 70% dos pacientes."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-330631","number":"330631","sourceNumber":"330631","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Mais de 90% dos adultos infectados conseguem reverter os sintomas e desenvolver\nanticorpos específicos contra os antígenos HBeAg e\nHBsAg circulantes, que garantem proteção de\nlongo prazo contra a doença. Está correto que:","options":{"A":"Apesar da recuperação clínica, o DNA do HBV ainda pode ser detectado em níveis basais e sua\nexpressão é controlada pela imunidade humoral e não pela celular.","B":"Apesar da recuperação clínica, o DNA do HBV ainda pode ser detectado em níveis basais e sua\nexpressão é controlada pela imunidade humoral e celular.","C":"Apesar da recuperação clínica, o DNA do HBV não pode ser detectado em níveis basais e sua\nexpressão é controlada pela imunidade humoral e celular.","D":"Apesar da recuperação clínica, o DNA do HBV ainda pode ser detectado em níveis basais e sua\nexpressão não é controlada pela imunidade humoral e celular."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-330634","number":"330634","sourceNumber":"330634","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Portador inativo é caracterizada por níveis baixos ou indetectáveis de replicação viral,\ncom normalização das transaminases e, habitualmente, soroconversão para anti-HBe. Sendo\ncorreto que:","options":{"A":"O escape viral pode ocorrer por integração do DNA viral ao genoma das células hospedeiras,\nmas não por depressão da atividade imunológica\ndo hospedeiro, seja por meio de mutações virais,\nseja por tratar-se de pacientes imunodeprimidos.","B":"O escape viral pode ocorrer por integração do DNA viral ao genoma das células hospedeiras ou\npor depressão da atividade imunológica do hospedeiro, seja por meio de mutações virais, seja por\ntratar-se de pacientes imunodeprimidos.","C":"O escape viral pode ocorrer por integração do DNA viral ao genoma das células hospedeiras ou\npor depressão da atividade imunológica do hospedeiro, seja por meio de mutações virais, seja por\ntratar-se de pacientes não imunodeprimidos.","D":"O escape viral nunca pode ocorrer por integração do DNA viral ao genoma das células\nhospedeiras, somente por depressão da atividade\nimunológica do hospedeiro, seja por meio de\nmutações virais, seja por tratar-se de pacientes imunodeprimidos."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-330689","number":"330689","sourceNumber":"330689","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Atualmente, a principal fonte de infecção da Hepatite C na infância é a transmissão\nvertical. Sendo correto que:","options":{"A":"A minoria das crianças são totalmente assintomáticas. A cirrose na infância é rara, ocorrendo em\n1% a 20% dos casos.","B":"A maioria das crianças são totalmente assintomáticas. A cirrose na infância é rara, ocorrendo em\n1% a 2% dos casos.","C":"A maioria das crianças são totalmente assintomáticas. A cirrose na infância é rara, ocorrendo em\n10% a 52% dos casos.","D":"A maioria das crianças são totalmente assintomáticas. A cirrose na infância é comum, ocorrendo\nem muitos dos casos."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-330696","number":"330696","sourceNumber":"330696","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A evolução clínica da doença hepática relacionada ao HCV progride mais rapidamente\nem pessoas coinfectadas com HIV. Está correto\nque:","options":{"A":"O tratamento do HIV e do HCV é, portanto, uma prioridade para as pessoas com coinfecção\nHIV/HCV.","B":"O tratamento do HIV e do HCV não é uma prioridade para as pessoas com coinfecção HIV/HCV.","C":"O tratamento do HIV e do HCV é, portanto, impedimento para as pessoas com coinfecção\nHIV/HCV.","D":"O tratamento do HIV e do HCV é, portanto, uma prioridade para as pessoas sem coinfecção\nHIV/HCV."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-284150","number":"284150","sourceNumber":"284150","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A presença dos anticorpos anti-HCV está adequadamente relacionada ao item\nCORRETO:","options":{"A":"É mais precoce e ocorre cerca de 3 a 6 dias após a exposição ao vírus.","B":"É mais tardia e ocorre cerca de 30 a 60 dias após a exposição ao vírus.","C":"É mais tardia e não ocorre cerca 90 dias após a exposição ao vírus.","D":"É mais tardia e ocorre cerca de 30 a 60 dias antes da exposição ao vírus."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-284155","number":"284155","sourceNumber":"284155","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"O tratamento da hepatite C está indicado na presença da infecção aguda ou crônica\npelo HCV, independentemente do estadiamento da fibrose hepática. Sendo correto o item:","options":{"A":"É fundamental saber se o paciente tem fibrose avançada ou cirrose, pois a confirmação desse\ndiagnóstico poderá afetar a condução clínica do paciente e o esquema de tratamento proposto.","B":"É fundamental saber se o paciente tem fibrose avançada ou cirrose, pois a confirmação desse\ndiagnóstico não poderá afetar a condução clínica do paciente e o esquema de tratamento proposto.","C":"É fundamental saber se o paciente tem fibrose avançada ou cirrose, pois a confirmação desse\ndiagnóstico poderá afetar a condução clínica do paciente e não o esquema de tratamento proposto.","D":"Independe saber se o paciente tem fibrose avançada ou cirrose, pois a confirmação desse\ndiagnóstico poderá afetar a condução clínica do paciente e o esquema de tratamento proposto."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-274880","number":"274880","sourceNumber":"274880","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente refere trabalhar como manicure e ter tido contato com sangue de clientes em\nalguns episódios quando não utilizou luvas ao realizar a sua função. Apresenta-se hoje ictérica e\nrefere também colúria e acolia fecal. Foi realizado diagnóstico de hepatite B aguda. Assinale a\nalternativa que apresenta os marcadores do vírus da hepatite B que estarão presentes na fase\ncrônica da doença, caso essa paciente evolua da fase aguda sem apresentar a eliminação viral\nespontânea.","options":{"A":"HBsAg e anti-HBs.","B":"HBsAg e anti-HBc IgM.","C":"HBsAg e anti-HBc IgG.","D":"HBeAg e anti-HBc IgM.","E":"Anti-HBc IgM e anti-HBs."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-216862","number":"216862","sourceNumber":"216862","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"O fígados direito e esquerdo são separados pela cisura portal principal, que\ncorresponde a uma linha que, originando-se no\nponto médio do leito vesicular, anteriormente,\ndirige-se posteriormente, ao longo da face anterossuperior do fígado, à face lateral esquerda da\nveia cava na sua porção supra-hepática também conhecida como:","options":{"A":"Linha de Calais.","B":"Linha de Cantlie.","C":"Linha de Devine.","D":"Linha de Couinaud."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-220270","number":"220270","sourceNumber":"220270","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Na dissecção da vesícula em uma colecistectomia é identificada a artéria cística, para\nreparo e ligadura para então proceder à ligadura do ducto cístico. A artéria cística é ramo arterial\ndireto da:","options":{"A":"Gastroduodenal superior.","B":"Hepática própria.","C":"Hepática direita.","D":"Hepática comum."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-177895","number":"177895","sourceNumber":"177895","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Há a seguir perfil sorológico de uma paciente com hepatite C: anti-HCV (ELISA)\npositivo; anti-HCV (imunoblot) positivo; HCV RNA\n(PCR) negativo e ALT (alanina aminotransferase)\nnormal. Trata-se de:","options":{"A":"Provável coinfecção hepatite C/hepatite B.","B":"Hepatite C resolvida.","C":"Hepatite C aguda.","D":"Hepatite C crônica ativa.","E":"Perfil falso-positivo para hepatite C."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-183443","number":"183443","sourceNumber":"183443","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente de sexo feminino, 20 anos de idade, chega ao Pronto Atendimento com\nqueixa de olhos amarelados há 10 dias com\npiora gradativa. Refere febre baixa não aferida\nassociada à urina escurecida sem outros sintomas. Mora em Caarapó-MS, mas refere viagens\nconstantes para o interior de São Paulo. Nega comorbidades e uso de medicações. Com relação a\nesse quadro clínico, assinale a alternativa correta.","options":{"A":"A hipótese de colangite é a mais provável, devendo ser iniciada antibioticoterapia de amplo\nespectro e realizados exames de imagem abdominal para avaliação de necessidade cirúrgica.","B":"A hipótese de febre amarela não pode ser descartada devendo a paciente permanecer em\nisolamento de contato até o resultado de exames confirmatórios.","C":"O diagnóstico de hepatite aguda viral é o mais provável e, além dos exames sorológicos para\nhepatites A, B e C, devem ser indicados repouso e interrupção ingesta alcóolica por pelo menos 6\nmeses.","D":"A hipótese de neoplasia de vias biliares é alta necessitando realização urgente de\ncolangioressonância.","E":"Em se tratando de uma hepatite autoimune, é imprescindível a coleta de FAN para confirmação\ndiagnóstica."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-177888","number":"177888","sourceNumber":"177888","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Qual o nome do plano que passa ao lado esquerdo da fossa vesicular para o lado\nesquerdo da veia cava inferior, que divide o fígado em lobos direito e esquerdo?","options":{"A":"Lobo caudado.","B":"Ducto hepático direito.","C":"Artéria hepática.","D":"Linha de Cantlie.","E":"Linha de Courvoisier-Terrier."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-155651","number":"155651","sourceNumber":"155651","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A respeito da anatomia hepática, os fígados direito e esquerdo são separados pela\ncisura portal principal, que corresponde a\numa linha que, originando-se no ponto médio do leito\nvesicular, anteriormente, dirige-se posteriormente, ao longo da face ânterosuperior do fígado, à\nface lateral esquerda da veia cava na sua porção supra-hepática. Essa linha é também conhecida\ncomo:","options":{"A":"Cisura portal inferior.","B":"Linha de Cantlie.","C":"Linha interlobular.","D":"Cisura de Coinaud.","E":"Linha segmentar."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-155693","number":"155693","sourceNumber":"155693","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Aluno do 5º ano de medicina, vinculado à liga do trauma de uma universidade da\ncidade, durante o procedimento de sutura,\nsofre acidente perfurativo ao encapar a agulha que\nutilizou para anestesiar o paciente. Trata-se de um paciente sabidamente com infecção por vírus\ndas hepatites B e C, mas que é HIV-negativo. Os exames laboratoriais básicos realizados no\nestudante incluem a seguinte sorologia: HBsAg negativo, anticorpo anti-HBs positivo e IgG anti-HBc\nnegativo. Assinale a alternativa CORRETA quanto à situação de hepatite do aluno citado.","options":{"A":"O aluno teve contato prévio com o vírus da Hepatite B.","B":"O aluno representa memória imune para o Vírus B por conta da sua situação vacinal prévia.","C":"O aluno foi vacinado, porém não apresenta anticorpos que comprovem imunização.","D":"O aluno possui Hepatite B aguda.","E":"O aluno possui Hepatite C."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-133852","number":"133852","sourceNumber":"133852","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Mulher de 50 anos de idade deu entrada no hospital com queixas de mal-estar e dores\nno quadrante superior do abdome de início há,\naproximadamente, 7 dias. Refere adinamia, mas\nfamiliares referem que ela apresentou notável mudança no comportamento nessa última semana,\nprincipalmente depois que iniciou aumento do consumo de bebidas. Durante exame físico, notamos\naumento do fígado com borda romba, icterícia e tremores. Laboratório demonstra aumento de AST,\nALT bem como bilirrubinas. Seu tempo de protrombina está com INR de 2. A paciente refere grande\nconsumo de analgésico durante a última semana por causa das dores abdominais. Acerca disso,\npode-se afirmar que esse quadro é compatível com","options":{"A":"Hepatite Crônica.","B":"Insuficiência Hepática induzida por Paracetamol.","C":"Colangite.","D":"Cirrose Hepática."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-133857","number":"133857","sourceNumber":"133857","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente com quadro de hepatite viral muito grave, de início há 5 dias, evoluindo com\nquadro franco de insuficiência hepática, deteriorando agora com piora neurológica. Qual das\nmedidas abaixo NÃO é adequada para o controle de dano neurológico?","options":{"A":"Cabeceira elevada em 45°.","B":"Posição neutra da cabeça.","C":"Manitol.","D":"Lactulona por sonda."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-141842","number":"141842","sourceNumber":"141842","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Na hepatite pelo vírus B a fase de imunotolerância é caracterizada, dentre outros, pelos\nseguintes achados clínicos, laboratoriais ou histológicos, EXCETO:","options":{"A":"Alta replicação viral, altos títulos de HBV-DNA","B":"Baixa replicação viral, baixos títulos de HBV-DNA","C":"Transaminases normais, lesão hepática ausente","D":"Presença de HBeAg, lesão hepática mínima."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-130088","number":"130088","sourceNumber":"130088","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Assinale a alternativa que demonstra marcadores sorológicos característicos de um\npaciente com hepatite B aguda.","options":{"A":"Anti-HBc IgG não reagente, HBsAg não reagente, anti-HBsAg reagente.","B":"Anti-HBsAg reagente, anti-HBeAg reagente, HBsAg não reagente.","C":"HBeAg reagente, anti-HBc IgM reagente, HBsAg reagente.","D":"Anti-HBc IgM não reagente, anti-HBsAg reagente, HBsAg não reagente."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-111789","number":"111789","sourceNumber":"111789","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"<p>Paciente G.L.B., do sexo feminino, 28 anos, assintomática, procura atendimento\nmédico devido a história de contato com\nnamorado portador do Vírus Hepatite B (HBV). Refere que\nnão sabe se recebeu a vacina da hepatite B quando era mais jovem, sendo que o médico solicita\nos exames desta paciente cujos resultados foram: anti-Hbc IgM não reagente; anti-Hbs não\nreagente; HbsAg não reagente; HbeAg não reagente; anti-Hbe reagente; anti-Hbc total reagente.\n\nDNA-HBV (PCR quantitativo) com resultado menor que o limite mínimo detectável do aparelho\nutilizado na contagem. Sobre esta paciente,\nassinale a alternativa CORRETA que condiz com sua\nsituação clinicolaboratorial atual:</p>","options":{"A":"Hepatite B crônica pelo vírus mutante pré-core.","B":"Período de janela imunológica da infecção pelo HBV.","C":"Hepatite B crônica pelo vírus replicante selvagem.","D":"Hepatite B aguda (fase inicial).","E":"Hepatite B pregressa (imunidade)."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-106794","number":"106794","sourceNumber":"106794","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"<p>As hepatites virais são enfermidades provocadas por diferentes agentes etiológicos,\nacometendo primariamente o fígado, e que apresentam características epidemiológicas e\nclinicolaboratoriais semelhantes. Sobre as mesmas, é INCORRETO afirmar que:</p>","options":{"A":"A distribuição das hepatites virais é universal, sendo que a magnitude dos diferentes tipos varia\nde região para região.","B":"A principal via de contágio do vírus da hepatite A é a fecal-oral, por contato inter-humano ou\natravés de água e alimentos contaminados.","C":"A transmissão do vírus da hepatite B (HBV) se faz por via parenteral e, sobretudo, pela via\nsexual, sendo considerada uma doença sexualmente transmissível.","D":"A principal via de contágio da hepatite E é a fecal-oral.","E":"A Imunoglobulina Humana Anti-Hepatite tipo B (IGHAHB), disponível nos CRIE, é indicada\nsomente para recém-nascidos de mãe sabidamente portadora do HBV."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-106802","number":"106802","sourceNumber":"106802","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Em relação à hepatite C, é correto afirmar que:","options":{"A":"O teste confirmatório para diagnóstico é anti-HCVIgM.","B":"A ribavirina isolada é utilizada com sucesso nos portadores de hepatite C pós-transfusional.","C":"A presença de crioglobulinemia associada à VHC relaciona-se com as alterações\ndermatológicas e renais da doença.","D":"Os portadores do genótipo 1 evoluem com formas mais leves da doença e portanto necessitam,\napenas, de 6 meses de tratamento\nfarmacológico.","E":"Os portadores de HCV com transaminases normais devem, obrigatoriamente, ser submetidos à\nbiópsia hepática."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-106836","number":"106836","sourceNumber":"106836","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"No exame admissional de um candidato para o setor de enfermagem, você se depara\ncom o seguinte resultado do ANTI HBs: 5\nmUi/mI. Sua carteira vacinal está em dia. Qual a sua\norientação?","options":{"A":"Admissão e recomendação para o uso dos EPI.","B":"Reforço vacinal.","C":"Orienta novo esquema da vacina.","D":"Repete o teste ANTI HBs dentro de trinta dias.","E":"Nenhuma das anteriores."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-81180","number":"81180","sourceNumber":"81180","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Sobre Hepatites virais na infância, assinale a alternativa incorreta:","options":{"A":"Não existe forma crônica de hepatite A, mas a mesma é uma das principais causas de hepatite\nfulminante.","B":"A hepatite B raramente evolui para cronicidade em recém-nascidos, já que os mesmos recebem\na primeira dose da vacinação ao nascer.","C":"O marcador AgHBs positivo indica infecção aguda ou crônica pelo VHB.","D":"O marcador AgHbe indica alta infecciosidade, enquanto estiver positivo.","E":"O Anti-HCV positivo indica contato prévio com VHC e não define se a infecção é aguda ou\npregressa curada, ou se houve cronificação da doença."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-62454","number":"62454","sourceNumber":"62454","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente sexo masculino, 33 anos, casada. A pedido de um parente doente foi doar\nsangue, tendo como resultados de exames para hepatite B : Anti-HBs positivo, HBsag negativo,\nAnti Hbc total positivo. Com base nesses resultados, você orientaria a paciente a","options":{"A":"doar sangue visto ter imunidade duradoura, devido à Anti- HBs.","B":"doar sangue visto não ter HBsag negativo e portanto não tem a doença.","C":"não doar sangue, porque não sabe interpretar os exames e prefere não correr riscos.","D":"não doar sangue, pois tem HBsag negativo, mas anti HBC total positivo e pode reativar a\ndoença.","E":"não doar sangue, pois tem anti HBs positivo."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-45449","number":"45449","sourceNumber":"45449","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Em relação à hepatite C, é correto afirmar:","options":{"A":"Mais de 80% evolui para a forma crônica.","B":"A taxa de transmissão vertical é elevada.","C":"O principal marcador de infecção é o anti-HBc positivo.","D":"Icterícia ocorre em 90% dos casos agudos.","E":"Novas infecções podem ser evitadas com a vacina tríplice viral (A, B e C)."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-34521","number":"34521","sourceNumber":"34521","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Quanto às hepatites virais, não podemos afirmar que:","options":{"A":"As cinco formas de hepatite viral são clinicamente similares e podem ser distinguidas apenas por\nensaios sorológicos.","B":"Todos os vírus, exceto o HBV, são vírus RNA.","C":"As hepatites A e E são formas de hepatite infecciosa com disseminação oral-fecal e as hepatites\nB, C e D são formas de hepatite sérica,\ndisseminadas via parenteral e/ou sexual.","D":"O curso da hepatite aguda é altamente variável e sua gravidade pode variar desde uma infecção\nassintomática até uma doença grave ou fulminante.","E":"A insuficiência hepática aguda ou hepatite fulminante ocorre, mais comumente, em pacientes\ncom hepatite C."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-34508","number":"34508","sourceNumber":"34508","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"<p>Em relação à insuficiência hepática em pacientes maiores de 36 meses, qual NÃO\né resultado de doença hepática crônica:","options":{"A":"Fibrose cística.","B":"Colangite esclerosante.","C":"Síndrome de Reye.","D":"Glicogenose tipo IV.","E":"Deficiência de alfa-1-antitripsina."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-31854","number":"31854","sourceNumber":"31854","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Assinale a alternativa correta:","options":{"A":"O controle químico dirigido para a fase adulta do mosquito é a medida de controle vetorial\nrecomendada na leishmaniose visceral.","B":"A transmissão das hepatites, por via sexual, é mais comum para a HCV que para o HBV.","C":"O indivíduo infectado pelo HIV só transmite a doença na sua fase aguda.","D":"No Brasil, a maioria dos casos de Febre Amarela ocorre nos meses de novembro e dezembro.","E":"Nenhuma das alternativas anteriores."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-34574","number":"34574","sourceNumber":"34574","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente faz exames periódicos admissionais para o novo emprego, seus resultados\npara Hepatite B são o seguinte: HBsAg-; Anti-HBs+;\nAnti-HBc+; HBeAg-; Anti-HBe+, ao observar\ntais resultados assinale a assertiva CORRETA:","options":{"A":"Este paciente pode ter sido vacinado para Hepatite B.","B":"Este paciente teve hepatite B, mas agora está curado.","C":"Este paciente é portador crônico assintomático.","D":"Este paciente deverá iniciar imediatamente o tratamento com interferon alfa.","E":"Este paciente deverá ser submetido à biópsia hepática para decisão terapêutica."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-22628","number":"22628","sourceNumber":"22628","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Mulher, solteira, 28 anos, apresenta, há 20 dias, história de febre baixa, hiporexia,\nnáuseas e alguns episódios de vômitos\npós-alimentar. Nega tosse, disúria ou diarreia. Houve perda\nde 2 kg de peso no período. Nega etilismo ou tabagismo. Ao exame ictérica +/+4, desidratada,\neupneica, normotensa. Abdômen globoso, flácido, fígado a 2 cm do rebordo costal direito,\nmanobras de Blumberg e Murphy negativas. IMC: 30. A hipótese diagnóstica é de hepatite aguda.\nDeverá ser solicitado:","options":{"A":"Ultrassom de abdômen total e encaminhar para ambulatório de clínica cirúrgica por provável\ncolangite.","B":"AST, ALT e sorologia para hepatite C aguda. Notificar se houver confirmação.","C":"Raio X de abdômen. Encaminhar para o serviço de urgência/emergência devido ao diagnóstico\nsindrômico de abdômen agudo.","D":"AST, ALT, anti-HCV, Anti-HBc IgG e anti-HAV IgG.","E":"AST, ALT, Anti-HAV IgM, anti-HCV e HBsAg."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-22674","number":"22674","sourceNumber":"22674","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente com 26 anos de idade, G4P2A1, usuária esporádica de crack, chegou ao\npré-natal de um hospital terciário na 36a semana de gravidez. Verificou-se que o HBsAg e o\n\nanti-HBcAg apresentavam-se positivos, confirmando ser portadora crônica do vírus da hepatite B.\nEm relação a esse caso, é correto afirmar:","options":{"A":"Se o marcador sorológico HBcAg for positivo, o risco de transmissão vertical é mais baixo.","B":"Está indicada a imunoprofilaxia materna com vacina e gamaglobulina em grupos musculares\ndiferentes.","C":"Como a paciente tem o anti-HBcAg positivo, o recém-nascido só deverá receber a vacina para\nprofilaxia da transmissão vertical","D":"A cesárea deverá ser indicada para reduzir a taxa de transmissão vertical","E":"Se o marcador sorológico anti-HBeAg também for positivo, o risco de transmissão vertical é mais\nbaixo."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-25749","number":"25749","sourceNumber":"25749","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Um paciente, de 20 anos de idade, apresenta os seguintes resultados de exames\nlaboratoriais: bilirrubinas totais: 2,5 UI/mL; bilirrubinas indiretas:2,0 UI/mL; bilirrubinas\ndiretas: 0,5\nUI/mL; transaminases normais; Fosfatase Alcalina e Gama GT normais. A untrassonografia de\nabdome revela fígado de aspecto preservado. Assinale a opção correspondente ao provável\ndiagnóstico desse caso.","options":{"A":"Síndrome de Gilbert","B":"Hepatite B aguda","C":"Hepatite alcoólica","D":"Colecistite calculosa","E":"Hepatite A aguda"},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-359380","number":"359380","sourceNumber":"359380","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente de 25 anos de idade comparece à Unidade Básica de Saúde informando que\nteve contato com água de enchente, sem uso de\nproteção há 15 dias. Iniciou há uma semana com\nfebre de 38°C, mialgia, náuseas, vômitos e dor no hipocôndrio direito. Há dois dias relata que teve\nmelhora parcial do quadro, mas ficou ictérico. Ao exame físico, apresenta-se corado, hidratado,\nictérico (++/4+), acianótico. Restante do exame físico estava normal, exceto no exame de abdome,\nonde apresentou dor a palpação no hipocôndrio direito e hepatomegalia a 4cm do RCD. No dia\nanterior havia realizado exames laboratoriais onde foi visto hemograma sem alterações, bilirrubinas\ntotais de 16mg/dL (à custa de bilirrubina direta = 14mg/dL), TGO = 500U/L e TGP = 3.000U/L.\nUreia, creatinina e eletrólitos sem alterações. Levando em consideração os aspectos clínicos,\nlaboratoriais e epidemiológicos, dos exames abaixo, qual é o indicado para a confirmação\ndiagnóstica deste caso:","options":{"A":"Biologia molecular (RT-PCR) para leptospirose","B":"Exame sorológico para febre amarela (dosagem de anticorpo IgG)","C":"Exame sorológico para hepatite A (Anti-HAV IgM)","D":"Teste rápido imunocromatográfico para o diagnóstico de leishmaniose visceral"},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-359402","number":"359402","sourceNumber":"359402","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Homem de 37 anos, assintomático, apresenta os seguintes resultados de exames: AST\n24U/L; ALT 32U/L; HBsAg reagente, anti-HBs não reagente; anti-HBc total reagente; HBeAg não\nreagente; anti-HBe reagente. Assinale a alternativa que apresenta a conduta MAIS ADEQUADA\nnesse caso:","options":{"A":"Encaminhar o paciente para início de tratamento de hepatite B crônica.","B":"Orientar o paciente que as alterações se devem a hepatite B prévia curada.","C":"Orientar o paciente que as alterações se devem a vacinação prévia para hepatite B.","D":"Solicitar PCR (reação em cadeia da polimerase) para o vírus da hepatite B."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-330531","number":"330531","sourceNumber":"330531","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"As hepatites são comuns nas crianças em todo o mundo, em especial em populações\nde baixa renda e em áreas de saneamento básico\ndeficiente. Os programas de vacinação contra\nhepatite ajudam na prevenção. Diante do exposto, assinale a alternativa CORRETA","options":{"A":"A hepatite aguda é preocupante na infância e tem etiologia infecciosa, com predomínio das\nhepatites A a G, com cerca de 5% de causas não conhecidas","B":"A hepatite viral D, também conhecida como hepatite por agente delta, é um vírus que requer o\nvírus B para sua replicação e causa coinfecção com outras hepatites virais","C":"A presença de HBsAg significa infecção aguda ou crônica pela vírus da hepatite B, sendo que a\nantigenemia aparece no início da doença e, geralmente, é transitória, mas se mantém na infecção\ncrônica","D":"Uma das grandes preocupações de saúde pública é a infecção aguda fulminante ou a crônica\npela hepatite A, em especial em populações pobres e sem acesso à vacinação"},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-233825","number":"233825","sourceNumber":"233825","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Homem de 22 anos procura atendimento médico com relato de que a parceira sexual\nfoi recentemente diagnosticada com herpes\ngenital. Ele está assintomático. Não apresenta doenças\nconhecidas e não faz uso regular de medicamentos. Nega cirurgias prévias, transfusões\nsanguíneas, uso de drogas ilícitas ou medicamentos injetáveis. Relata ter mantido relações sexuais\ncom múltiplas parceiras. Possui estado vacinal adequado para idade. O exame físico não revela\nanormalidades. Exames de laboratório: anti-HIV não reagente; anti-HCV reagente; VDRL não\nreagente; HBsAg não reagente. Assinale a conduta MAIS ADEQUADA nesse caso.","options":{"A":"Encaminhar o paciente para o início de tratamento antiviral.","B":"Realizar o teste rápido para o vírus da hepatite C na mesma consulta.","C":"Repetir a sorologia plasmática para o vírus da hepatite C.","D":"Solicitar o teste molecular para a pesquisa de HCV-RNA."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-203222","number":"203222","sourceNumber":"203222","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Homem de 43 anos procurou auxílio médico porque notou coloração amarelada da pele\ne das mucosas. Ao exame físico, observou-se\nicterícia, e a hepatimetria estava no limite superior da\nnormalidade. Considerando esses dados, assinale a alternativa INCORRETA com relação à\nabordagem complementar nesse caso.","options":{"A":"Elevação predominante da fosfatase alcalina em relação às aminotransferases sugere presença\nde obstrução biliar ou colestase intra-hepática.","B":"Elevação predominante das aminotransferases, com ambas as enzimas abaixo de 500 U/L e\nrelação Aspartato Aminotransferase (AST)/Alanina Aminotransferase (ALT) superior a 2, permite\nexcluir o diagnóstico de hepatite alcoólica.","C":"Hipoalbuminemia, não explicada por outra causa, associada ao prolongamento do tempo de\nprotrombina que não é corrigido pela administração de vitamina K, sugere lesão hepatocelular mais\ngrave com acometimento da função síntese.","D":"O encontro de enzimas hepáticas normais sugere que a icterícia não se deve a hepatopatia ou\ndoença das vias biliares."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-139668","number":"139668","sourceNumber":"139668","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Acidentes perfuro-cortantes com exposição à material biológico representam risco de\ncontaminação pelo vírus da hepatite C, principalmente pra profissionais de saúde. Com relação a\nesta contaminação é CORRETO afirmar:","options":{"A":"A hepatite C aguda apresenta sintomatologia em 90% dos casos","B":"A hepatite C é a principal responsável pelas hepatites pós transfusionais","C":"Recomenda-se o emprego da imunoglobulina para os indivíduos acidentados com material\nbiológico sabidamente contaminado com o vírus.","D":"No tratamento da infecção aguda recomenda-se o uso de antiretrovirais."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-101809","number":"101809","sourceNumber":"101809","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Em relação à falência hepática aguda, está ERRADO afirmar:","options":{"A":"Nos casos de hepatotoxicidade pelo acetaminofeno, deve ser administrada N-acetilcisteína, o\nmais precocemente possível.","B":"Penicilamina é o tratamento de escolha quando a causa é a doença de Wilson.","C":"Toxicidade por drogas, hepatites virais e doença hepática autoimune são as causas mais\ncomuns.","D":"Trata-se de condição clínica na qual ocorre rápida deterioração da função hepática que resulta\nem relação do estado mental e coagulopatia em\nindivíduos sem doenças hepáticas sabidamente\nconhecida."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-60359","number":"60359","sourceNumber":"60359","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Homem de 47 anos é atendido no consultório com anti-HCV e o estudo qualitativo do\nRNA-HCV positivos. Relata que há 4 meses notou escurecimento transitório da cor da urina, assim\ncomo as escleras estavam ligeiramente amarelas naqueles dias. Com base nesses dados, é\nCORRETO afirmar que:","options":{"A":"A evolução para cirrose hepática ocorre em 40 a 50% dos casos e acontece, em média, após 20\nanos do contágio.","B":"Cerca de 30% dos pacientes permanecem com transaminases dentro dos valores de referência\ne, raramente, evoluirão para cirrose.","C":"O quadro clínico apresentado pode estar relacionado à hepatite C aguda e a taxa de\nnegativação do vírus ocorre até o 6º mês em 50% dos casos.","D":"Uma vez com cirrose hepática, a taxa anual de incidência do carcinoma hepatocelular é de 8 a\n10%."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-52341","number":"52341","sourceNumber":"52341","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Um aluno da Faculdade de Medicina (22 anos, assintomático, etilista social e índice de\nmassa corporal = 23) procura orientação\nmédica, após ser alertado pelos colegas de que estava\nictérico. Não faz uso de medicamentos ou de drogas ilícitas. O exame físico é normal. A avaliação\nlaboratorial revela hiperbilirrubinemia indireta (agravada pelo jejum prolongado), níveis normais de\ndesidrogenase lática e de aminotransferases. A contagem de reticulócitos também é normal. A\nprincipal hipótese diagnóstica é:","options":{"A":"Esteato-hepatite não alcoólica.","B":"Síndrome de Gilbert.","C":"Colangite esclerosante.","D":"Síndrome de Dubin-Johnson."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-53328","number":"53328","sourceNumber":"53328","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Mulher de 45 anos é surpreendida num exame médico de rotina com valor elevado de\ncreatinina no soro (2,4 mg%). Era completamente assintomática e lembrava-se de um exame\nnormal (1,0 mg%) realizado há 4 anos, quando se submeteu a uma pequena cirurgia plástica. O\núnico relevante da sua história pregressa foi um acidente automobilístico, ocorrido aos 25 anos de\nidade. Naquela ocasião recebeu múltiplas transfusões de sangue. O exame físico revelou, de\nsignificativo, pressão arterial de 160/106 mmHg, hepatoesplenomegalia e petéquias nos membros\ninferiores. Exames laboratoriais: hemoglobina 13,2 g%; glicemia de jejum 85 mg%; FAN: negativo;\nC3 70 mg% (VR: 80 a 180 mg%); C4; 6 mg% (VR: 14 a 40 mg%); urinálise tipo 1: hematúria e\ncilindros hemáticos, relação proteína/creatinina em amostra aleatória de urina 3,1. Assinale, dentre\nas opções abaixo, os exames complementares que mais provavelmente definiriam o diagnóstico do\nquadro apresentado pela paciente:","options":{"A":"ANCAc-Proteinase 3, ANCAp-MPO e anticorpo anti-MBG.","B":"Anti-HCV e pesquisa de crioglobulinas.","C":"Imunofixação de proteínas séricas e urinárias.","D":"Título de antiestreptolisina O e anti-hialuronidase."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-31585","number":"31585","sourceNumber":"31585","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Acidentes com material biológico entre trabalhadores da saúde têm se mostrado\nimportante problema de saúde pública. Diante de\numa vítima de acidente perfurocortante com\nagulha oca, durante o procedimento de coleta de sangue, dentre as opções abaixo, assinale a\nconduta recomendada:","options":{"A":"Administrar, imediatamente, imunoglobulina anti-VHC, no caso de ser um profissional não\nvacinado contra Hepatite C.","B":"Afastar o acidentado do trabalho durante dez dias para realização de exames e repouso no\ndomicílio.","C":"Caso a fonte seja sabidamente portador do vírus da hepatite B e o trabalhador não seja\nvacinado contra essa infecção, iniciar esquema vacinal para vírus da hepatite B e aplicar\nimunoglobulina.","D":"Testar o sangue coletado para detecção de portador de HIV, vírus da Hepatite C e da Hepatite\nB, sendo, nesse caso, dispensada a exigência\nde autorização, pelo paciente fonte, para realizar tais\nexames."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-365982","number":"365982","sourceNumber":"365982","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Dados os seguintes marcadores, a alternativa que contém o que é sintetizado\nexclusivamente pelas células parenquimatosas do\nfígado e apresenta uma longa vida média de\naproximadamente 20 dias, o que pode fazer com que seus níveis iniciais estejam normais em\ndoenças hepáticas agudas, é:","options":{"A":"Albumina.","B":"Fosfatase alcalina.","C":"Gamaglutamiltranspeptidase (GGTP).","D":"Alanina Aminotransferase (ALT)."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-365980","number":"365980","sourceNumber":"365980","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente, 30 anos, é diagnosticado com hepatite B aguda após a realização de exames\nlaboratoriais e de imagem. O médico planeja o acompanhamento do paciente para monitorar a\npossibilidade de cronificação da doença. Com base nesta situação, é CORRETO afirmar:","options":{"A":"O acompanhamento deve ser contínuo por pelo menos 1 ano, já que a maioria dos casos se\ntorna crônica.","B":"O acompanhamento deve ser feito apenas por 3 meses, pois a maioria dos casos se resolve\nespontaneamente.","C":"Pacientes com hepatite B aguda não necessitam de acompanhamento prolongado, uma vez que\nmenos de 1% dos casos se torna crônico.","D":"O paciente deve ser acompanhado por pelo menos 6 meses, uma vez que 5 a 10% dos casos\npodem cronificar."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-361756","number":"361756","sourceNumber":"361756","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente de 8 anos, masculino, relata dor abdominal difusa, acompanhada de náuseas\ne vômitos, há 02 dias. Relata viagem recente\npara casa dos avós no interior do estado, onde ficou\npor 14 días. Acompanhante avô relata que o jovem ia brincar bastante na natureza, pelo sítio e que\nnão sabe referir se teve contato com animais peçonhentos. Criança relata que comia pequenas\nfrutas próximas a um riacho, onde eram despejados os dejetos dos moradores locais. Solicitados\nexames laboratoriais, com TGO 400 U/mL, TGP 420 U/mL, fosfatase alcalina 130 U/L,\ngamaglutamiltransferase 70 U/L, bilirrubina total e frações 1,5 mg/dL (direta 1,2 mg/dL e indireta\n0,3\nmg/dL), Hemoglobina 14,6g/dL, leucograma 16 mil/mm3, plaquetas 180mil/mm3, PCR 145mg/dL.\nExame físico demonstra uma discreta icterícia, com dor abdominal em cólica difusa, sem sinais de\nperitonite. Refere vacinação em dia para hepatite B sem ter tido infecção prévia, mas desconhece\npara hepatite A. Aventada hipótese de hepatites, qual a provável sorologia para o caso?","options":{"A":"HBsAg positivo, HBeAg positivo, Anti-HBe negativo, Anti-HBc total negativo, Anti-HBs negativo.\n\nAnti-HAV IgM e IgG negativos.","B":"HBsAg negativo, HBeAg negativo, Anti-HBe negativo, Anti-HBc total negativo, Anti-HBs positivo\ne Anti-HAV IgM positivo, Anti- HAV IgG negativo.","C":"HBsAg positivo, HBeAg positivo, Anti-HBe negativo, Anti-HBc total negativo, Anti-HBs negativo.\n\nAntiHAV IgM negativo, Anti- HAV IgG positivo.","D":"HBsAg negativo, HBeAg negativo, Anti-HBe negativo, Anti-HBc total positivo, Anti-HBs positivo.\n\nAntiHAV IgM negativo, Anti- HAV IgG positivo."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-340733","number":"340733","sourceNumber":"340733","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Sobre a segmentação hepática de Couinaud, assinale a correta.","options":{"A":"O segmento I encontra-se no lobo direito.","B":"O segmento II encontra-se no lobo esquerdo e é mais posterior.","C":"Os segmentos V e VII formam o lobo esquerdo.","D":"O segmento III encontra-se no lobo direito e é mais posterior."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-260249","number":"260249","sourceNumber":"260249","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Sobre as hepatites agudas, assinale a alternativa correta.","options":{"A":"As hepatites A e D possuem transmissão fecal-oral.","B":"A crioglobulinemia mista pode ser uma das manifestações extra-hepáticas da infecção pelo vírus\nda hepatite C.","C":"O vírus da hepatite B tem efeito citopático direto.","D":"O vírus da hepatite E é um vírus de DNA de transmissão parenteral."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-260615","number":"260615","sourceNumber":"260615","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A anatomia cirúrgica do fígado é extremamente importante para ressecções de\ntumores. A classificação de Couinaud contribuiu enormemente para a realização dos\nprocedimentos cirúrgicos no fígado. Couinaud dividiu o fígado de forma funcional. Sobre a\nsegmentação do fígado marque a opção ERRADA:","options":{"A":"Linha de Cantlie divide o fígado em lobo direito ( 60-70%) e lobo esquerdo (30-40% ) do fígado.","B":"Com esta divisão funcional as cirurgias se tornaram mais seguras e atualmente a mortalidade\npós-operatória é < que 5%.","C":"A classificação de Couinald seguimentou o fígado em 8 seguimentos que recebem sangue da\nveia porta e artéria hepática , possui e drenagem biliar independentes e a drenagem venosa de\ntodos os seguimentos é para veia cava inferior.","D":"Os lobos funcionais do fígado são formados da seguinte maneira: lobo esquerdo pelos\nseguimentos I ,II,III e IV e o lobo funcional direito pelos seguimentos V,VI,VII e VIII."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-266651","number":"266651","sourceNumber":"266651","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"As hepatites virais são um grave problema de saúde pública no Brasil e no mundo.\nTrata-se de uma infecção que atinge o\nfígado, causando alterações leves, moderadas ou graves.\nSobre essa temática, é INCORRETO afirmar que:","options":{"A":"A hepatite A é a causa mais frequente de hepatite aguda e sua transmissão é fecal-oral.","B":"O exame anti-HBs positivo traduz imunidade por cura ou resposta normal à vacinação.","C":"Os acidentes com perfurocortantes devem receber imunoglobulinas independente do estado\nvacinal para hepatite A e hepatite B.","D":"Os aumentos de aminotransferases são os principais marcadores de hepatite aguda e indicam\nlesão hepatocelular."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-239813","number":"239813","sourceNumber":"239813","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Um homem de 32 anos é atendido em um pronto-atendimento de uma cidade litorânea,\nenquanto passava férias na companhia de alguns amigos, em período de carnaval. A queixa\nprincipal é de que estava ficando amarelo e na anamnese surgiram dados de sintomas prodrômicos\ntais como náuseas, inapatetência, mal-estar inespecífico de início há 1 semana. Não estava\nconfuso nem apresentava outras alterações do exame neurológico. Nega episódios prévios\nsemelhantes. No exame físico inicial: paciente ictérico, sem estigmas de insuficiência hepática, sem\nascite. O fígado estava doloroso e palpável a 4 cm do rebordo costal direito. Exames laboratoriais\niniciais demonstraram: Bilirrubinas totais de 6.8 mg/dL (VR até 1.2) com bilirrubina direta de 6;\ngama-GT 30 (VR até 60); Fosfatase alcalina de 192 (VR até 110); aspartato aminotrasferase (AST)\n140 (VR até 42) e alanina aminotransferase (ALT) de 160 (VR até 44). Albumina 4.3 (VR > 3.5),\nRNI de 1. Sorologias realizadas: HbsAg reagente ? Anti-HBC IgM reagente ? anti-HbsAg não\nreagente ? Anti-HbeAg não reagente - Anti-HAV IgG reagente ? Anti-HCV não reagente ? Anti-HIV\n1 e 2 não reagente. Nesse caso, qual a conduta inicial mais adequada?","options":{"A":"Imunoglobulina hiperimune.","B":"Seguimento clínico.","C":"Tratamento antiviral de início imediato.","D":"Biopsia hepática."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-244516","number":"244516","sourceNumber":"244516","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Para o diagnóstico laboratorial da infecção Hepatite C, um resultado anti-HCV reagente\nprecisa ser complementado utilizando-se um teste para detecção direta do vírus. Está errado\napenas o item:","options":{"A":"Os testes de ácidos nucleicos (ou testes moleculares) podem ser utilizados para detectar o\nHCV-RNA circulante no paciente.","B":"A versão qualitativa do teste irá identificar a presença ou a ausência deste marcador no\npaciente.","C":"As metodologias quantitativas disponíveis hoje são similares às metodologias qualitativas no que\nse refere à sensibilidade e especificidade\ndo teste.","D":"Os testes moleculares quantitativos também são conhecidos como testes de carga viral, e são\nincapazes de quantificar o número de cópias de genomas virais circulantes em um paciente."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-238753","number":"238753","sourceNumber":"238753","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Um homem de 50 anos apresentou resultado de exame sorológico anti-HCV positivo. É\nportador de doença renal crônica e está em tratamento com realização de hemodiálise. Assinale a\nalternativa CORRETA sobre o caso deste paciente.","options":{"A":"A presença de hepatite C crônica é definida pela presença de anti-HCV positivo por mais de 6\nmeses.","B":"O nível de replicação do vírus C se correlaciona diretamente com a gravidade da doença\nhepática, já que o genoma viral se incorpora ao núcleo da célula infectada.","C":"É frequente a reativação do vírus C após início de imunossupressores ou quimioterápicos em\npacientes com resposta virológica sustentada após o tratamento antiviral.","D":"A infecção pelo vírus C é uma das principais causas de crioglobulinemia mista, a qual pode\ncursar com insuficiência renal."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-254995","number":"254995","sourceNumber":"254995","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Zilma, 25 anos, procura atendimento ambulatorial para mostrar resultados de exames.\nEla já realizou tatuagens anteriores e teve\ndúvidas em relação ao risco de transmissão de hepatite\nviral B, sendo realizados os seguintes exames: anti-HBe e anti-HBc (IgG) reagentes. Encontra-se\nassintomática, sem histórico prévio de doença hepática. Diante dessas sorologias, as seguintes\nhipóteses diagnósticas são possíveis antes da avaliação laboratorial complementar, exceto:","options":{"A":"A paciente pode ser portadora do vírus da hepatite B.","B":"Pode significar que a paciente teve contato e conseguiu fazer o clareamento espontâneo do\nvírus da hepatite B.","C":"Pode significar hepatite B crônica com baixa replicação viral.","D":"Se esta paciente apresentar o HBsAg não reagente e o HBV-DNA quantitativo por PCR\nindetectável significa que a paciente nunca teve contato com o vírus da hepatite B.","E":"Não posso considerá-la imunizada através de vacinação contra o vírus da hepatite B."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-219433","number":"219433","sourceNumber":"219433","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente 33 anos de idade em consulta admissional para trabalho. Apresentou\nsintomas de IVAS na semana anterior.\nExames: Bilirrubina 1.4 mg/dL ALT 60U/L, AST 28 U/L, GGT\n301 U/L. Qual a provável explicação para esses resultados?","options":{"A":"Sindrome Crigler- Najjar syndrome","B":"Síndrome de Gilbert","C":"Hepatite B","D":"Síndrome Rotor"},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-219437","number":"219437","sourceNumber":"219437","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente de 32 anos de idade está grávida. É ex-usuária de drogas injetáveis e está\npreocupada com seu status de hepatite porque previamente já fez um teste que veio positivo, mas\nela não se lembra se foi hepatite B ou C. Novos exames foram realizados: Anticorpo Anti HCV\npositivo; HCV RNA negativo; HbsAg negativo; HbcAg positivo; Anti-HBs positivo; Anti-HBe IgM\nnegativo; Anti-HBc IgG positivo. Qual o próximo passo?","options":{"A":"Imunização HBV","B":"Explicar a paciente que o exame mostra hepatite B ativa","C":"Iniciar tratamento com tenofovir","D":"Reafirmar que indica infecção passada por HCV"},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-210444","number":"210444","sourceNumber":"210444","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Assinale a alternativa do marcador de hepatite B que indica alto grau de infectividade.","options":{"A":"HBsAg.","B":"HBcAg.","C":"HBcAg IgM.","D":"HBeAg."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-210474","number":"210474","sourceNumber":"210474","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Analise o quadro a seguir: assinale a alternativa que representa o padrão sorológico de\nimunidade naturalmente adquirida para hepatite B, em paciente de 42 anos, sexo feminino:","options":{"A":"Anti-HBc total: -; Ag HBs: -; Anti-HBs: +.","B":"Ant-HBc total +; Ag HBs: -; Anti-HBs: +.","C":"Anti-HBc total: +; Ag HBs: +; Anti-HBs: -.","D":"Anti-HBc total: -; Ag HBs: +; Anti-HBs: -."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":["question_bank/media/medcurso/medcurso-hepato-hep-1/210474.png"],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-181050","number":"181050","sourceNumber":"181050","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Nas doenças listadas abaixo, marque a alternativa em que NÃO ocorre transmissão\nvertical.","options":{"A":"Hepatite A.","B":"Citomegalovirose.","C":"Encefalite herpética.","D":"Doença de chagas."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-178010","number":"178010","sourceNumber":"178010","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente de 22 anos de idade, sexo masculino, chega ao centro de saúde para\nconsulta, trazendo resultados de exames\nsolicitados por outro médico. Os exames mostravam:\nHBsAg: negativo; anti-HBc IgG: positivo; anti-HBc IgM negativo; HbeAg negativo; anti-Hbe negativo;\nanti-HBs positivo. Assinale o diagnóstico do paciente.","options":{"A":"Paciente com passado de hepatite B que evoluiu para cura.","B":"Paciente com hepatite B crônica.","C":"Paciente vacinado para hepatite B.","D":"Paciente com hepatite C crônica e imune a hepatite B."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-181256","number":"181256","sourceNumber":"181256","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A hepatite viral B é uma infecção de transmissão parenteral, predominantemente, pela\nvia sexual. A transmissão vertical também pode ocorrer, e ocasiona uma evolução desfavorável,\ncom maior chance de cronificação. Diferentemente da hepatite viral A, as infecções causadas pelo\nHBV são habitualmente anictéricas em mais de dois terços das pessoas infectadas. Apesar da\nprogressão da cobertura vacinal e acesso ampliado às orientações para prevenção das Infecções\nSexualmente Transmissíveis (IST), ainda há um crescente número de diagnósticos de hepatite B,\ncom aproximadamente 10.000 novos casos detectados e notificados anualmente. Sendo\nINADEQUADO afirmar que:","options":{"A":"aproximadamente 5 a 10% das pessoas infectadas tornam-se portadoras crônicas do HBV (do\ninglês Hepatitis B Virus).","B":"cerca de 20 a 25% dos casos crônicos de hepatite B que apresentam replicação do virus\nevoluem para doença hepática avançada.","C":"a infecção pelo HBV também é condição para o desenvolvimento da hepatite D, causada pelo\nvírus Delta.","D":"o HBV apresenta baixa infectividade e permanece viável durante longo período quando fora do\ncorpo (ex: em uma gota de sangue)."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-179064","number":"179064","sourceNumber":"179064","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Mulher, 40 anos, obesa (IMC = 37 kg/m²), dislipidêmica com triglicérides o dobro do\nvalor da normalidade, procurou o médico\ngeneralista devido a desconforto em hipocôndrio direito,\nnos últimos meses, e alterações de enzimas hepáticas em exames de rotina. Negou ingestão de\nbebidas alcoólicas e uso contínuo de medicamentos. O ultrassom revelou esteatose hepática grau\nIII/III, aspartato aminotransferase e alanina aminotransferase estavam aumentadas 2 vezes o valor\ndo normal, gama GT estava aumentada 2 vezes o valor do normal, e fosfatase alcalina e\nbilirrubinas estavam normais. Além das orientações para controle de peso (dieta hipolipídica e\nhipocalórica) e atividade física, qual a conduta mais adequada nesse momento?","options":{"A":"Realizar exames de sangue para avaliar hepatopatias virais, autoimune e metabólica. Reavaliar\nem 6 meses.","B":"Realizar biópsia hepática e, se fibrose, iniciar vitamina E. Reavaliar em 1 ano com nova\nbiópsia.","C":"Realizar biópsia hepática e, se fibrose, iniciar pioglitazona. Reavaliar em 1 ano com nova\nbiópsia.","D":"Realizar exames de sangue para avaliar hepatites virais, autoimune e metabólica. Iniciar\nmetformina e vitamina E. Reavaliar em 6 meses."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-160209","number":"160209","sourceNumber":"160209","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Em relação ao perfil sorológico de hepatite B, qual a associação errada:","options":{"A":"Portador inativo: HbsAg + / AntiHbe +.","B":"Hepatite B aguda: HbsAg + / Hbe Ag + / AntiHbc Igm + / AntiHbs -.","C":"Vacinado: AntiHbs + / HbsAg + / antiHbc -.","D":"Imune por infecção prévia: HbsAg - / antiHbc + / antiHbs +."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-163440","number":"163440","sourceNumber":"163440","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A hepatite B pode ser uma doença relacionada ao trabalho quando no curso de ações\nde assistência à saúde ocorre contato com\nmateriais biológicos infectados. Diante de contato\nacidental de trabalhadores não imunizados com material biológico conhecidamente ou\npotencialmente contaminado com o vírus da hepatite B recomenda-se:","options":{"A":"Quimioprofixia com vacinação e imunoglobulina.","B":"Quimioprofilaxia com ribavirina.","C":"Quimioprofilaxia com lamivudina, interferon alfa, famciclovir.","D":"Quimioprofilaxia com ribavirina e vacinação."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-158218","number":"158218","sourceNumber":"158218","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Sobre os acidentes de trabalho envolvendo material biológico, assinale a alternativa\nINCORRETA.","options":{"A":"Deve ser preenchida a Ficha de Investigação de Acidente de Trabalho com Exposição a Material\nBiológico do Sinan, além das fichas individuais, de acordo com os agravos de notificação\ncompulsória, tais como nos casos de aids, tétano e hepatites.","B":"São considerados materiais biológicos potencialmente não infectantes para Hepatite B e C ?\nescarro, suor, lágrima, urina, vômitos, fezes, secreção nasal, saliva, independentemente de\nestarem ou não com sangue.","C":"Caso a fonte seja conhecida, mas sem informação de seu status sorológico, é necessário\norientar o profissional acidentado sobre a\nimportância da realização dos exames HBsAg, Anti-HBc\nIgM, Anti-HCV e Anti-HIV.","D":"Exames de detecção viral não são recomendados como testes de triagem quando a fonte é\ndesconhecida."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-159465","number":"159465","sourceNumber":"159465","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"As hepatites virais são doenças causadas por diferentes vírus hepatotrópicos que\napresentam características epidemiológicas,\nclínicas e laboratoriais distintas. Possuem distribuição\nuniversal e são observadas diferenças regionais de acordo com o agente etiológico. São\nconsiderados como agentes etiológicos mais relevantes os vírus A (HAV), B (HBV), C (HCV), D\n(HDV) e E (HEV). Assinale a alternativa que apresenta a família a que o vírus C pertence.","options":{"A":"Picornaviridae.","B":"Hepadnaviridae.","C":"Flaviviridae.","D":"Deltaviridae."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-131763","number":"131763","sourceNumber":"131763","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Raul, 40 dias, é trazido ao ambulatório por estar amarelinho. Nasceu de parto normal, a\ntermo, peso de nascimento igual a 3.200g, em boas condições. Alta conjunta. Mãe refere icterícia\ndesde a primeira semana de vida, tendo feito uso de chá de Picão. Procurou o médico com quinze\ndias sendo orientado banho de sol e substituído leite humano por fórmula de partida. Apresenta-se\nictérico +++/4, hidratado, abdome globoso, fígado a quatro cm da reborda costal direita e baço a\ntrês cm da reborda costal esquerda, Peso atual = 4kg. Sem outras alterações. Durante a consulta\napresentou urina escurecida e fezes esbranquiçadas. Todas as alternativas abaixo representam\nopções propedêuticas, exceto:","options":{"A":"Ultrassonografia de abdome.","B":"Cintilografia hepatobiliar.","C":"Bilirrubinas total e frações.","D":"Eletroforese de hemoglobina.","E":"Colangiografia."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-137459","number":"137459","sourceNumber":"137459","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Assinale a alternativa que corresponde à interpretação correta do seguinte perfil\nsorológico do Vírus da Hepatite B: HBsAg\n(+), HBeAg (+), IgM antiHBc (-), IgG anti-HBc (+),\nanti HBs (-), anti HBe (-) e HBV DNA (+):","options":{"A":"Infecção aguda, fase aguda.","B":"Infecção crônica, fase replicativa.","C":"Infecção crônica, fase não replicativa.","D":"Sem infecção, status pós-vacinação."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-103777","number":"103777","sourceNumber":"103777","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A vacinação em adultos é medida profilática e eficaz contra doenças passíveis de\nprevenção. Sobre vacinação marque a alternativa CORRETA:","options":{"A":"Não há indicação de vacinação de hepatite B em pacientes diabéticos sem a infecção previa.","B":"A vacinação de HPV se restringe a meninas com idade de 11 e 12 anos.","C":"Vacinação contra herpes-zoster não tem aplicabilidade clínica.","D":"A proteína recombinante da hepatite E está sendo desenvolvida para a sua prevenção em\npopulações de alto risco."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-103760","number":"103760","sourceNumber":"103760","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Em relação à Gamaglutamil Transferase (GGT), é INCORRETO afirmar que:","options":{"A":"O fígado é o órgão mais rico em atividade GGT, sendo que esta atividade é maior ao nível dos\ncanais biliares e nos polos dos hepatócitos.","B":"Existe uma alteração do valor sérico da GGT na chamada síndrome dismetabólica.","C":"O aumento da GGT acompanhado do aumento da fosfatase alcalina, das bilirrubinas e das\ntransaminases, pode conduzir a uma hipótese diagnóstica de coledocolitíase ou de colangite\nesclerosante.","D":"A GGT tipo 2 ? GGT II ? pode ser um marcador, junto à alfafetoproteína, que auxilia no\ndiagnóstico do Carcinoma Hepatocelular (CHC)."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-105998","number":"105998","sourceNumber":"105998","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Dr H.R.J. acidenta?se com material perfuro - cortante de fonte HBSAG Positiva e\nmesmo após duas séries de vacina recombinante para Hepatite B o mesmo não apresentou\nsoroconversão (antiHBS acima de 10 UI\\ml), ele deverá:","options":{"A":"Receber imunoglobulina e vacina imediatamente.","B":"Receber imunoglobulina EV nas próximas 12 horas.","C":"Acompanhar regularmente seus marcadores para hepatite B, com 6 semanas, 3 meses e 6\nmeses.","D":"Receber imunoglobulina IM em até 7 dias e repetir 500 UI após 30 dias, acompanhando seus\nmarcadores em ambulatório especializado."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-120735","number":"120735","sourceNumber":"120735","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Uma criança de cinco anos de idade chega ao Posto de Saúde trazida pela mãe,\nproveniente da zona rural de Pelotas, com\nqueixa de olhos amarelados e urina escura? há\ntrês dias. Ao exame, encontra-se em bom estado geral, ictérica e com hepatomegalia sem outras\nalterações. Tem dois colegas de escola que estão com quadro semelhante e você:","options":{"A":"pensa em Dengue e hospitaliza para investigação.","B":"pensa em obstrução biliar por áscaris e pede uma colangiopacreatografia.","C":"pensa em Hepatite A e pede transaminases, bilirrubinas totais e frações e anti HVA IgM.","D":"pensa em Hepatite B e pede bilirrubinas totais e frações e HBsAg.","E":"pensa em Hepatite C e pede bilirrubinas totais e frações, Anti HBC e biópsia hepática."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-79270","number":"79270","sourceNumber":"79270","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Em relação à área hepatobiliopancreática é INCORRETO afirmar que:","options":{"A":"A veia supra-hepática direita se une em tronco único com a veia supra-hepática média e juntas\ndrenam todo o lobo hepático direito, enquanto a veia supra-hepática esquerda drena o lobo\nesquerdo para a veia cava.","B":"O fígado pode ter seu suprimento arterial feito por uma artéria hepática média, uma artéria\nhepática direita, ramo da mesentérica superior, e\numa artéria hepática esquerda, ramo da artéria\ngástrica esquerda.","C":"Na síndrome de Budd-Chiari não é incomum a hiperfuncionalidade do segmento hepático I pelo\nfato do mesmo ter conexões venosas próprias com a veia cava abdominal.","D":"Existe uma maior incidência de malignidades de vias biliares nos portadores de patologias da\njunção pacreatobiliares."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-87921","number":"87921","sourceNumber":"87921","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"<p>Um médico cirurgião relata que tomou o esquema completo da vacina para hepatite\nB há 11 anos. Após 3 meses da vacinação\nrealizou o anti-HBs e o resultado foi positivo ( >2.000\nmUl/ml). Há 1 mês, conta que realizou novamente o exame e foi negativo ( < 10 mUl/ml). Qual a\nconduta neste caso?</p>","options":{"A":"Realizar o reforço com 1 dose da vacina para hepatite B.","B":"Orientar o profissional que a queda da titulação de anti-HBs não indica que ele não está imune,\nportanto, não necessita repetir o esquema vacinal.","C":"Orientar o profissional que a queda da titulação de anti-HBs indica que ele não está imune,\nportanto, necessita repetir o esquema vacinal.","D":"Repetir a sorologia e investigar estado de portador."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-81064","number":"81064","sourceNumber":"81064","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Analise as seguintes afirmativas com relação às hepatopatias crônicas da infância e\nassinale com V as verdadeiras e com F as falsas. ( ) As crianças infectadas pelo vírus B via\nhorizontal não apresentam, em geral, quadro clínico inicial sugestivo de infecção aguda. ( ) As\ncrianças infectadas pelo vírus B via vertical e aquelas com infecção crônica de longa duração\nrespondem muito mal ao tratamento farmacológico. ( ) A observação laboratorial de HBeAG\npositivo e anti-HBe negativo indica presença de vírus B mutante pré-core. ( ) Os pacientes que\nsofreram a infecção vertical tendem a ser sintomáticos desde os primeiros anos de vida, devido à\nhipersensibilidade anti-HBc materna. Assinale a alternativa que apresenta a sequência CORRETA:","options":{"A":"V, F, V, V.","B":"V, F, F, V.","C":"F, V, V, F.","D":"V, V, F, F."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-58948","number":"58948","sourceNumber":"58948","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"<p>Paciente de 26 anos, sexo masculino, queixa-se de dor intensa em hipocôndrio\ndireito e epigástrio iniciada há duas\nsemanas, sem relação com alimentação. Nos últimos sete dias,\napresentou febre, mialgia, poliartralgia, náusea, vômitos e constipação. Não tolera a ingestão de\nlíquidos e alimentos. Ao exame clínico, encontra-se desidratado, ictérico, febril e taquicárdico. Os\nexames laboratoriais iniciais foram: Hb: 12,8 g/dl; global de leucócitos: 5.600, com diferencial\nnormal; plaquetas: 243.000; TGO: 1.230 U/L; TGP: 1.610 U/L; bilirrubina total: 5,4 mg/dl;\nbilirrubina\ndireta: 2,8 mg/dl; RNI: 1,4; amilase: 90 U/L; ureia: 60 mg/dl; creatinina: 1,4 mg/dl; HBsAG:\nreagente;\nanti-HBs: não reagente; anti-HBc IgM: reagente; anti-HBc IgG: reagente; HBeAG: reagente;\n\nanti-HBe: não reagente; anti-HCV: não reagente; anti-HAV IgM: não reagente; anti-HAV IgG:\nreagente. Em relação a esse caso, marque a afirmativa INCORRETA: </p>","options":{"A":"Trata-se provavelmente de um caso de hepatite B aguda, porém a biópsia hepática é necessária\npara excluir diagnósticos diferenciais.","B":"A sorologia para o vírus da hepatite A indica exposição prévia ao HAV, intransmissibilidade e\nimunidade permanente.","C":"Esse paciente deve ser internado para tratamento de suporte, porém não há indicação de\nantivirais.","D":"A cronificação da doença é uma complicação pouco frequente e só poderá ser definida após um\nperíodo de seis meses."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-69339","number":"69339","sourceNumber":"69339","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Homem de 35 anos de idade, assintomático, é encaminhado para investigação por\napresentar elevação de ALT sérica e anti-HBc reagente. Refere ingestão alcóolica moderada,\nnegando uso de medicamentos ou drogas endovenosas. O paciente está anictérico e não\napresenta sinais periféricos de hepatopatia. O fígado e o baço não são palpados. ALT: 70 U/L.\nTGO: 120 U/L; GGT: 328 U/L; FA: 86 U/L, Anti-HBs reagente, anti-HCV e Anti-HIV não reagente;\nantimitocôndria negativo; USG de abdome superior sem alterações, sem litíase biliar e nem\ndilatação da árvore biliar. O diagnóstico provável é:","options":{"A":"esteato-hepatite alcóolica.","B":"hepatite crônica B.","C":"cirrose biliar primária.","D":"colangite esclerosante primária."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-48652","number":"48652","sourceNumber":"48652","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"<p>Paciente do sexo masculino, 38 anos de idade, apresentou-se com náuseas\nprogressivas, vômitos, desconforto no quadrante\nsuperior direito com duração de dois dias. No dia\nanterior notou urina escura, icterícia e confusão leve. Não tem antecedentes para infecção viral ou\nmesmo para uso abusivo de álcool. Usa analgésicos de forma excessiva devido à enxaqueca. Ao\nexame, paciente ictérico, inconsciente, com asterix leve. Fígado palpado e doloroso, hepatimetria\nde 14 cm. Exames laboratoriais, transaminases ALT e AST (5500 e 9500 U/L), bilirrubina total (5,6\nml/dl). Tempo de protrombina 16.5 seg. RNI 2,4. Assinale a alternativa INCORRETA.</p>","options":{"A":"As elevações das enzimas hepáticas podem ser a única alteração encontrada nas hepatites por\nálcool ou droga e na esteato-hepatite não alcoólica (NASH), sendo que nas duas primeiras o\ndiagnóstico é clínico e na última por exclusão.","B":"No diagnóstico das hepatites por vírus B e C, a desproporção das enzimas hepatocelulares e\ncanaliculares auxilia no diagnóstico diferencial com as outras hepatites não infecciosas.","C":"As hepatopatias crônicas podem ter as enzimas hepáticas quase que normais, sendo que às\nvezes é necessária a biópsia hepática para\nconfirmação do diagnóstico.","D":"As doenças colestáticas crônicas podem ser avaliadas pela elevação das enzimas canaliculares,\nhistória clínica e teste de função hepática\nnormal.","E":"A falência hepática fulminante diagnosticada pelos achados clínicos, elevação significativa das\nenzimas hepatocelulares e o uso do medicamento, é o provável diagnóstico do paciente."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-33470","number":"33470","sourceNumber":"33470","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A icterícia recorrente da gravidez está mais frequentemente associada a:","options":{"A":"Colelitíase","B":"Colestase intra-hepática","C":"Hepatite crônica","D":"Esteatose aguda da gravidez"},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-23188","number":"23188","sourceNumber":"23188","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Em relação à sorologia das hepatites virais marque a alternativa INCORRETA.","options":{"A":"Depois que uma pessoa é infectada pelo HBV, o primeiro marcador virológico identificável no\nsoro é o HBsAg.","B":"O vírus da hepatite A é transmitido quase exclusivamente pela via fecal-oral.","C":"O indicador mais sensível da infecção pelo HCV é a presença do HCV-RNA.","D":"Na hepatite C o anti-HCV precede a identificação sorológica do HCV-RNA."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-26834","number":"26834","sourceNumber":"26834","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A hepatite B é causada pelo vírus da Hepatite B (VHB), um DNA vírus da família\nhepadnaviride. Qual dos marcadores sorológicos\nabaixo relacionados, quando presentes, é os mais\nsugestivos de uma infecção crônica:","options":{"A":"Anti HBs(+) anti HBc IgM.","B":"HbsAg (+) anti HBc IgG.","C":"Anti HBc IgM.","D":"Anti Hbe.","E":"Anti HBc IgG."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-26851","number":"26851","sourceNumber":"26851","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"RN prematuro, com 1,8 kg, filho de mãe HbsAg+ deverá, EXCETO:","options":{"A":"Receber 4 doses da vacina contra hepatite B (ao nascimento, com 2 kg, 1 mês após a 2ª e 6\nmeses após a 2ª)","B":"Receber Imunoglobulina Hiperimune contra hepatite B nas primeiras 12 horas de vida","C":"Receber leite materno da própria mãe.","D":"Receber BCG normalmente","E":"Ficar sem o leite materno da própria mãe até que seja devidamente imunizado."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-9762","number":"9762","sourceNumber":"9762","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Marque a alternativa INCORRETA:","options":{"A":"remodelamento ventricular se refere às mudanças na massa, volume, forma e composição do\nventrículo esquerdo que acontece após injúria cardíaca e/ou condições hemodinâmicas anormais.","B":"um fator predisponente para bacteriúria em homens é obstrução uretral secundária a hipertrofia\nprostática.","C":"necrose de hepatócitos é a condição que libera as aminotransferases para o sangue e há boa\ncorrelação do nível sérico com o grau de lesão hepática.","D":"bactérias anaeróbias têm papel importante em pneumonias somente quando episódio de\naspiração ocorre dias a semanas anteriores ao início da doença."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-9659","number":"9659","sourceNumber":"9659","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Homem de 48 anos procura atendimento com relato de desconforto em hipocôndrio\ndireito, escurecimento da urina e progressiva\ncoloração da pele e dos olhos. Vem notando também\ninsônia, sonolência diurna e tremores. Ao exame nota-se icterícia e fígado palpável a 4 cm do\nrebordo costal direito. Admite-se ser um bebedor crônico de alcoólicos e que na ultima semana vem\nfazendo uso de volumes muito superiores aos costumeiros. Refere diagnóstico anterior de\ncolelitíase e uso atual de ?remédio de ervas chinesas?. A avaliação laboratorial revelou bilirrubina\ntotal de 8,7mg% com bilirrubina direta de 6,8mg%, TGO de 320U/L e TGP de 140U/L, gama GT de\n391U/L e RNI de 1,4. Com estes exames iniciais, que diagnóstico pode ser descartado com maior\ngrau de certeza?","options":{"A":"Hepatite viral aguda.","B":"Coledocolitíase.","C":"Hepatite viral crônica.","D":"Hepatite alcoólica."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-19074","number":"19074","sourceNumber":"19074","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Sobre doenças hepáticas crônicas, é CORRETO afirmar que:","options":{"A":"a incidência do carcinoma hepatocelular é muito elevada na Doença de Wilson.","B":"a presença de autoanticorpos é indispensável para o diagnóstico das hepatites autoimunes.","C":"pacientes com hepatite crônica ativa, HBsAg positivo, mas HBeAg negativo não devem receber\ntratamento antiviral.","D":"pacientes com vírus C genótipo 2 respondem melhor ao tratamento com interferon e ribavirina."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hepato-hep-1-318538","number":"318538","sourceNumber":"318538","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Uma jovem com 19 anos de idade chega para consulta na unidade de pronto\natendimento por icterícia e desconforto no\nquadrante superior direito do abdome. A paciente refere\nque vem se sentindo cansada há aproximadamente 10 dias, acrescentando que, nos primeiros 2\ndias desse quadro, apresentou febre (38ºC na região axilar) e artralgia, coriza, tosse seca, perda\nde\napetite, náuseas e dois episódios de vômitos. Conta ainda que, quando a icterícia apareceu, os\nsintomas melhoraram bastante e que agora sente apenas um pouco de desconforto no quadrante\nsuperior direito do abdome e leve diminuição do apetite. Ao exame físico, a paciente apresenta\nregular estado geral, ictérica e com fígado palpável 2 cm abaixo do rebordo costal; o baço não é\npalpável. Considerando o quadro clínico e os dados apresentados, a principal hipótese diagnóstica\ndessa paciente é:","options":{"A":"Leptospirose.","B":"Mononucleose.","C":"Colecistite aguda.","D":"Hepatite aguda viral."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-318613","number":"318613","sourceNumber":"318613","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Um homem com 32 anos de idade, usuário de Drogas Ilícitas Injetáveis (DII),\ncomparece à consulta ambulatorial em\nclínica médica com queixa de fadiga importante e dor\nabdominal no hipocôndrio direito que teve início há 1 semana. Refere que, 2 dias antes do início\ndesses sintomas, apresentou febre, artralgias e um exantema leve, que desapareceram, ficando em\nseguida com os olhos amarelados e a urina escura. Relata que esses últimos sinais apareceram\nsimultaneamente à melhora da febre, que persistiu por alguns dias, e que, nos últimos dias, passou\na ter apenas fadiga e dor abdominal. Nega náuseas, vômitos, diarreia ou sangramentos, e afirma\nconseguir ingerir líquidos e alimentos por via oral de forma normal. Nega comorbidades prévias\nsignificativas, e sua história familiar não é relevante. Além do uso de DII, o paciente é tabagista\n(10\nmaços/ano) e etilista social de fermentados. Ao exame físico, encontra-se em regular estado geral,\ncom fácies de doença aguda, levemente ictérico nas escleras; corado, hidratado, acianótico, afebril,\nsem equimoses ou petéquias. Aparelhos cardiovascular e respiratório sem anormalidades. Abdome\ndoloroso à palpação do hipocondrio direito, sendo o fígado palpável a 3 cm do rebordo costal\ndireito, na linha hemiclavicular, de borda romba e consistência habitual; espaço de Traube livre.\n\nNão há edemas em membros inferiores. Os resultados dos exames complementares solicitados\nnessa consulta são apresentados na tabela a\nseguir. Considerando as informações apresentadas,\na principal hipótese diagnóstica e o tratamento indicado são, respectivamente:","options":{"A":"Hepatite B aguda; iniciar tratamento sintomático, evitando-se fármacos hepatotóxicos e de\nmetabolismo hepático.","B":"Hepatite alcoólica aguda; prescrever corticoide, evitar novos insultos hepáticos e encaminhar o\npaciente para o Centro de Atenção Psicossocial (Álcool e Drogas).","C":"Hepatite C aguda; prescrever antivirais combinados (como ledipasvir/sofosbuvir), conforme\nresultado do teste de genotipagem.","D":"Hepatite B crônica agudizada; prescrever tenofovir ou entecavir, evitando-se fármacos\nhepatotóxicos e de metabolismo hepático."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":["question_bank/media/medcurso/medcurso-hepato-hep-1/318613.png"],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-355212","number":"355212","sourceNumber":"355212","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Em paciente de 40 anos, observa-se elevação de transaminases em exames de rotina.\nHá cerca de 30 dias, realizou tatuagem,\nponderando-se, assim, a possibilidade de hepatite C. Com\nbase nesse texto, o exame capaz de fazer o diagnóstico de hepatite C, aguda de forma mais\nprecoce nesse paciente é o","options":{"A":"Anti-HCV.","B":"PCR para DNA do vírus C da hepatite.","C":"HBsAg.","D":"Anti-HAV IgM.","E":"PCR para RNA do vírus C da hepatite."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-302543","number":"302543","sourceNumber":"302543","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente do sexo masculino de 32 anos, procedente do interior do estado do Pará,\nprofessor de educação física, recebe o\nresultado do teste rápido do HBsAg reagente, após\nparticipar de uma campanha de triagem sorológica em seu município. É encaminhado ao serviço de\natendimento ambulatorial, onde, de forma adequada, é solicitada a complementação de\ninvestigação denominada","options":{"A":"HBV-DNA por PCR quantitativo.","B":"HBeAg, anti-HBe e anti-HDV.","C":"anti-HBcIgM e IgG.","D":"biópsia hepática.","E":"elastografia hepática."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-277731","number":"277731","sourceNumber":"277731","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Homem de 40 anos, hígido, recebeu os resultados abaixo após doação de sangue. A\ninterpretação correta dos resultados e a conduta a ser adotada são","options":{"A":"suscetibilidade ao vírus da hepatite C; indicar vacinação.","B":"hepatite B aguda; iniciar interferon alfa peguilhado.","C":"hepatite B curada; não há indicação de tratamento.","D":"hepatite B crônica; indicar biopsia hepática.","E":"cicatriz vacinal de hepatite B; não há indicação de tratamento."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":["question_bank/media/medcurso/medcurso-hepato-hep-1/277731.png"],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-254735","number":"254735","sourceNumber":"254735","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente masculino, de 32 anos, casado, professor de educação física, morador do\ninterior do Estado do Pará, realiza triagem para as hepatites virais B e C, em uma campanha na\nescola onde trabalha. Recebe o resultado com teste rápido HBsAg reagente e anti-HCV não\nreagente. Referenciado para um ambulatório de hepatologia, onde a melhor conduta a ser tomada\npara continuar a investigação é","options":{"A":"solicitar a biópsia hepática para indicar tratamento ou não.","B":"solicitar o HBV-DNA quantitativo para avaliar replicação viral.","C":"solicitar os marcadores sorológicos HBsAg, anti-HBc total e anti-HBs.","D":"solicitar os marcadores sorológicos HBeAg, anti-HBe e anti-HD.","E":"não solicitar novos exames, pois o paciente possui cicatriz sorológica."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-240475","number":"240475","sourceNumber":"240475","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente feminina de 32 anos chega ao ambulatório de especialidade, procedente do\ninterior do Estado, casada, trazendo o seguinte resultado de sorologia realizado por ter participado\nde uma campanha de diagnóstico das hepatites virais em seu município: - Teste rápido para HBsAg\nreagente; teste rápido para o anti-HCV não reagente. O médico da estratégia de saúde da família\nde seu município ampliou a investigação após esses resultados, solicitando os seguintes exames:\nHBeAg não reagente, anti-HBe reagente, testes bioquímicos hepáticos dentro dos parâmetros de\nnormalidade e ultrassonografia abdominal superior dentro dos padrões normais. A conduta que se\ndeveria tomar a seguir seria solicitar o(a)","options":{"A":"biópsia hepática para indicar tratamento ou não.","B":"HBV-DNA quantitativo para avaliar replicação viral.","C":"elastografia hepática para indicar tratamento ou não.","D":"quantificação do HBsAg para avaliar estado de portador.","E":"endoscopia digestiva alta para avaliar hipertensão portal."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-227642","number":"227642","sourceNumber":"227642","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Sobre as hepatites virais, marque a alternativa CORRETA.","options":{"A":"Na hepatite aguda pelo vírus A, relações homossexuais e a multiplicidade de parceiros sexuais é\nimportante fator de transmissão, sendo o contato com o sêmen e a secreção vaginal uma\nimportante via de infecção.","B":"A idade, no momento do contágio pelo vírus da hepatite A, não guarda relação com evolução\nclínica da doença.","C":"Indivíduos HBsAg positivos por mais de 6 meses são definidos como portadores crônicos do\nvírus da hepatite B.","D":"Existem fortes evidências de que na hepatite B o padrão de resposta imune TH1 se correlaciona\ncom um estado de cronificação da doença, em\nvirtude desse padrão de resposta imune ser incapaz\nde responder adequadamente à presença do vírus B no fígado.","E":"Pacientes infectados pelo vírus da hepatite B evoluem para estado de cronificação ou cura,\nnunca evoluindo com quadro de hepatite fulminante."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-215636","number":"215636","sourceNumber":"215636","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"São objetivos do tratamento de hepatite C:","options":{"A":"Resposta virológica sustentada e erradicação do vírus do organismo.","B":"Manutenção do vírus em órgãos linfoides, mas com carga viral não detectada.","C":"Aumento da qualidade, mesmo com impossibilidade de aumento da expectativa de vida.","D":"Prevenção do carcinoma hepatocelular mesmo sem erradicação do vírus.","E":"Estabilizar a progressão de manifestações extra-hepáticas, mesmo com a erradicação do vírus."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-175251","number":"175251","sourceNumber":"175251","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Em relação à hepatite B, é correto afirmar:","options":{"A":"Não ocorre a transmissão vertical.","B":"A transmissão vertical só ocorre nos três primeiros meses de gestação.","C":"O vírus da hepatite B pode causar malformação fetal.","D":"É extremamente contagiosa; o número de partículas virais é estimado em 10 trilhões / ml de soro\nou de secreções.","E":"A principal via de transmissão do vírus é a fecal-oral."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-175255","number":"175255","sourceNumber":"175255","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente masculino, 10 anos, realizou pesquisa de marcadores sorológicos para\nhepatite B com o seguinte resultado: Anti\nHBs positivo, HBsAg negativo, Anti HBc positivo e HBeAg\nnegativo. Com base nesse quadro, é correto afirmar que o paciente","options":{"A":"se infectou com o vírus e evoluiu para a cura.","B":"apresenta a forma crônica da doença.","C":"apresenta hepatite B aguda.","D":"não teve contato com o vírus; apenas foi vacinado.","E":"apresenta a forma latente da doença."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-159850","number":"159850","sourceNumber":"159850","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"No paciente com indicação de investigação de Hepatite B, o primeiro marcador a\naparecer no curso desta infecção viral é:","options":{"A":"Anti-Hbs.","B":"Anti-Hbe.","C":"HbsAg.","D":"HbeAg.","E":"Anti-Hbc IgM."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-159975","number":"159975","sourceNumber":"159975","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A divisão anatômica do fígado tem como base:","options":{"A":"o suprimento arterial hepático.","B":"a drenagem venosa hepática.","C":"a fissura umbilical.","D":"a drenagem biliar.","E":"a distribuição da veia porta."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-159997","number":"159997","sourceNumber":"159997","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente gestante que entrou em contato com hepatite B realiza investigação para a\ndoença. Os resultados mostram anti-HBs reagente, HBsAg não reagente, anti-HBc IgG reagente,\nHBeAg não reagente e anti-HBe reagente. Nesse sentido, é correto afirmar que:","options":{"A":"os resultados são compatíveis com a resposta vacinal.","B":"a paciente está com doença aguda.","C":"a paciente é suscetível.","D":"a paciente está imune.","E":"a paciente desenvolveu hepatite B crônica."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-139511","number":"139511","sourceNumber":"139511","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Um enfermeiro de 30 anos de idade procura o ambulatório de clínica médica\ncom queixa de dores generalizadas, anorexia,\nfadiga e febre baixa. Ele estava previamente\nbem, fumava um ou dois cigarros por semana e negava uso de álcool ou drogas ilícitas. O\nexame físico revelou icterícia discreta, hepatomegalia e esplenomegalia leve, o restante do\nexame era normal. Os resultados de exames laboratoriais são os seguintes: Aspartato\naminotransferase (AST); 800U/l; Alanina aminotransferase ( ALT); 1.300u/L; Fosfatase alcalina;\n220U/l ( normal, 30 a 120); Bilirrubina total; 4,8mg/dl; Bilirrubina direta; 3,2mg/dl; Proteína\ntotal:\n7g/dl; globulina: 3,2g/dl; Tempo de protrombina: 12seg ( INR, 1,0); IgM anti- HAV positivo; HBsAg\nnegativo; IgG anti-HBcAg positivo; Anti- HBsAg positivo; Anti- HCV negativo. O diagnóstico mais\nprovável é:","options":{"A":"Hepatite A- Infecção prévia por hepatite B.","B":"Hepatite A ? aguda- Hepatite B aguda.","C":"Hepatite B aguda.","D":"Hepatite A- Vacinação prévia para hepatite B.","E":"Hepatite B crônica."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-134594","number":"134594","sourceNumber":"134594","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"São causas de icterícia, EXCETO:","options":{"A":"Síndrome de Gilbert.","B":"Síndrome de Budd-Chiari.","C":"Câncer de pâncreas.","D":"Doença de Von Willebrand","E":"Síndrome de Crigler-Najjar"},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-135470","number":"135470","sourceNumber":"135470","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Em relação ao tratamento atual contra o vírus da hepatite C (HCV) é INCORRETO\nafirmar que","options":{"A":"Com as novas drogas para tratamento da infecção crônica pelo HCV, todos os\npacientes, sem\n\nexceção, podem usar todas as drogas antivirais de ação direta.","B":"Sofosbuvir, Daclatasvir, Simeprevir são drogas que podem ser usadas no tratamento da hepatite\nC.","C":"Os RAV (Variantes associadas à resistência), em relação ao tratamento com as drogas antivirais\nde\n\nação direta, podem limitar o tratamento da infecção pelo vírus da hepatite C.","D":"O interferon peguilado não representa mais uma opção terapêutica.","E":"A Ribavirina ainda pode ser usada em adição aos novos esquemas nos pacientes com\nfibrose\n\navançada."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-88089","number":"88089","sourceNumber":"88089","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"<p>Em relação aos casos de Insuficiência Hepática (IH), analise as afirmativas abaixo. I\n\n- As causas mais comuns de IH aguda são o acetaminofeno e as hepatites virais. Em 20% dos\ncasos nenhuma causa é identificada; II - IH\nfulminante é definida como a instalação aguda de\nalterações do estado mental e coagulopatia nas 10 a 20 semanas de manifestações iniciais de\nhepatopatia em indivíduos previamente sadios; III - A hipertensão portal é a principal manifestação\nda cirrose e é estabelecida pela determinação da diferença de pressão entre a veia hepática e a\nveia porta (gradiente de pressão > 10 mmHg); IV - A determinação do nível sanguíneo de amônia\nnão é um teste nem sensível nem específico para a encefalopatia hepática; V - Os principais\n\nmicro-organismos envolvidos na peritonite espontânea bacteriana são Escherichia coli, Klebsiella e\nPseudomonas aeruginosa. Estão CORRETAS: </p>","options":{"A":"I, II, III, IV e V.","B":"II, III e V, somente.","C":"I, III e IV, somente.","D":"III, IV e V, somente.","E":"II, III, IV e V, somente."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-64186","number":"64186","sourceNumber":"64186","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Um jovem, 21 anos, vem à consulta com história de relações sexuais sem uso de\npreservativo, trazendo os seguintes exames: HBsAg: negativo; Anti-Hbc-Igm: negativo; IgG: +;\nAnti-HBs: +; Anti-HCV: +; PCR-HCV qualitativo: +. O que dizer para este paciente, além de\norientá-lo para o sexo seguro?","options":{"A":"Você está com hepatite B aguda e hepatite C crônica.","B":"Você nunca teve hepatite B e está com hepatite C aguda.","C":"Você apresenta imunidade vacinal ao vírus da hepatite B e está com hepatite C aguda.","D":"Você está com hepatite crônica B e C.","E":"Você teve contato com o vírus B, apresenta imunidade adquirida e está com hepatite C."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-68511","number":"68511","sourceNumber":"68511","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"<p>Paciente de 27 anos, na 36ª semana gestacional, chega ao ambulatório de\nhepatologia com resultado de sorologia\npositiva para Hepatite B realizada durante o pré-natal. Não\nhavia alteração no exame físico, exceto os achados fisiológicos do período gravídico. A análise dos\nexames laboratoriais revela: ALT: 27 UI/ml; AST: 31 UI/ml; HBsAG reagente; Anti-HBc total\nreagente; Anti-HBs não reagente; Anti-HCV não reagente e anti-HIV não reagente. Nesse caso, a\nconduta apropriada é:</p>","options":{"A":"Solicitar imediatamente do HBV-DNA quantitativo para iniciar terapêutica com interferon alfa-2A,\npor um período de quatro a seis meses, a\ndepender da soroconversão do HBeAG.","B":"Avaliar o HBeAG e anti-HBe para definir fase replicativa ou não, em vias de definir parto normal\nou cesariano e indicar tratamento específico.","C":"Orientar a paciente e a equipe obstétrica e pediátrica para procederem à vacinação contra a\nhepatite B e administração da HBiG ao recém-nato até 12 horas após o parto.","D":"Investigar seu parceiro sexual quanto à presença do vírus da Hepatite B, pois se trata de uma\ndoença sexualmente transmissível, com risco de\ncronificação de 90% quando adquirida na idade\nadulta.","E":"Efetuar a avaliação sorológica do recém-nascido, pois até o quarto mês de idade possui os\nanticorpos maternos. Caso ele persista com HBsAG positivo, deve-se proceder ao início do\ntratamento."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-55263","number":"55263","sourceNumber":"55263","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"<p>Paciente do sexo masculino, 37 anos, é atendido no ambulatório com quadro de\ncinco dias de mal-estar geral e desconforto\nno hipocôndrio direito, associado à náuseas. Três dias\ndepois, apareceu icterícia e colúria. Feito diagnóstico presuntivo de hepatite viral aguda, foram\nsolicitados exames laboratoriais, cujos resultados se encontram abaixo: Hematologia e bioquímica:\nHemácias: 3,7 milhões/mm³, Leucócitos: 2.800/mm³ (segmentados 55%, linfócitos 40%); Plaquetas:\n187.000/mm³; bilirrubinas totais / bilirrubina direta: 8,4 / 6,2 mg/dl; AST: 1.280 UI/L; ALT: 890\nUI/L;\nTAP: 62%. Sorologia: anti-HAV IgM negativo; anti-HAV IgG positivo; HBsAG positivo; anti-HBc IgM\npositivo, anti-HBs negativo; anti-HCV negativo. Com base no quadro clínico acima, é CORRETO\nafirmar: I. Trata-se de um quadro de Hepatite B aguda e contato prévio com o Vírus da Hepatite A,\ndevendo ser tratado com sintomáticos e introduzir lamivudina nos quadros com evolução para\nfulminação. II. Trata-se de um quadro de Hepatite B e A agudas, devendo receber tratamento\nsintomático e avaliar, no sexto mês do início do quadro, a possibilidade de cronificação ou não da\nHepatite B. III. Nos casos de Hepatite B aguda, a avaliação do HBeAG é fundamental para avaliar a\ngravidade da doença e o potencial risco de fulminação. IV. Caso no paciente persista o HBsAG\napós 24 semanas do quadro, pode-se afirmar que houve cronificação e ele deve ser encaminhado\npara o centro de referência. V. Neste caso, a possibilidade de cura com soroconversão do HBsAG\npara anti-HBs está em torno de 90 a 95%. Estão CORRETAS as afirmativas:</p>","options":{"A":"I e III, somente.","B":"IV e V, somente.","C":"I e IV, somente.","D":"II e III, somente.","E":"III e V, somente."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-50201","number":"50201","sourceNumber":"50201","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"JMS, 13 anos, masculino, ao fazer exames de rotina, apresentou o seguinte resultado\nda sorologia para Hepatite: HBsAg negativo,\nAnti-HBs positivo, HBe negativo, Anti-HBe negativo,\nAnti-HBc negativo, Anti-VHA IgG positivo. Então, é correto afirmar:","options":{"A":"JMS é portador do vírus da hepatite B (VHB).","B":"JMS é portador do vírus da hepatite A (VHA).","C":"JMS é portador do VHB e do VHA.","D":"JMS está imunizado para hepatite A e hepatite B.","E":"JMS nunca realizou imunização para nenhum dos dois vírus."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-371053","number":"371053","sourceNumber":"371053","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente masculino, 50 anos, com histórico de mal-estar geral, perda de peso\ninexplicável e dor abdominal difusa há\nalguns meses. Ele relata fadiga extrema, náuseas\nintermitentes e falta de apetite. Não há histórico significativo de doenças hepáticas conhecidas ou\nexposições a fatores de risco como álcool ou toxinas. Relata sorologia para hepatite B positiva. Ao\nexame físico, hepatomegalia discreta à palpação abdominal, mas sem outros achados relevantes.\nTraz alguns poucos exames laboratoriais evidenciando: ALT (alanina aminotransferase): 600 U/L\n(normal até 30 U/L). AST (aspartato aminotransferase): 500 U/L (normal até 35 U/L). Bilirrubina\ntotal: 1.2 mg/dL (normal até 1.2 mg/dL). Bilirrubina direta: 0.6 mg/dL (normal até 0.4 mg/dL).\n\nCoagulograma: dentro dos limites de normalidade. Conforme Informações em relação ao caso\nclínico, assinale a alternativa correta:","options":{"A":"A detecção de apenas anticorpos anti-HBc e anti- HBS pode indicar uma infecção passada ou\numa infecção crônica ativa.","B":"Em indivíduos com sorologia positiva para anti-HBc e negativa para anti-HBs, ou seja, presença\nisolada do anti-HBc, pode refletir infecção resolvida com Anti-HBs não detectado ou Anti-HBc\n\nfalso-positivo ou infecção crônica com HBsAg não detectado.","C":"Pacientes com hepatite B crônica e carga viral detectável, não correm risco de progressão para\ndoença hepática crônica avançada, incluindo cirrose e carcinoma hepatocelular.","D":"A reativação do vírus da hepatite B durante a imunosupressão pode resultar em um aumento\nrápido na replicação viral levando a\ncomplicações graves, como hepatite aguda grave, insuficiência\nhepática aguda (falência hepática) e até mesmo óbito em casos extremos. É recomendado o\ntratamento preventivo com medicamentos antivirais para reduzir o risco de reativação viral, em\ntodos os pacientes, independentemente do tipo da imunossupressão e perfil sorológico.","E":"Elevações moderadas de ALT (alanina aminotransferase) e AST (aspartato aminotransferase)\nindicam, de fato, uma lesão hepática grave. Pode\nser resultado de várias condições, como\nhepatites virais, lesões hepáticas tóxicas, doenças metabólicas, doença hepática gordurosa\nassociada a disfunção metabólica ou até mesmo outras condições extra-hepáticas. Portanto, elas\n\navaliem diretamente a função hepática."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-341156","number":"341156","sourceNumber":"341156","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Sobre os marcadores sorológicos e virológicos da Hepatite B, observe as alternativas\nabaixo e assinale a incorreta.","options":{"A":"Nos casos típicos, o HBsAg deixa de ser identificável 1 a 2 meses após o início da icterícia e,\nraras vezes, persiste por mais de 6 meses","B":"O anti-HBc é prontamente demonstrável no soro, começando 1 a 2 semanas após o\naparecimento de HBsAg e precedendo os níveis\nidentificáveis do antiHBs por semanas a meses.","C":"Depois que uma pessoa é infectada pelo HBV, o primeiro marcador virológico identificável no\nsoro em 1 a 12 semanas, em geral entre 8 e 12 semanas, é o HBsAg.","D":"Após o desaparecimento do HBsAg, o anticorpo para o HBsAg (anti-HBs) torna-se identificável\nno soro e continua detectável indefinidamente\ndepois disso.","E":"O HBsAg circulante precede as elevações da atividade das aminotransferases séricas e os\nsintomas clínicos em 2 a 6 semanas, que se tornam indetectáveis após a fase ictérica ou\nsintomática da hepatite B aguda na quase totalidade dos casos."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-155836","number":"155836","sourceNumber":"155836","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A segmentação hepática descrita por Couinaud em 1957 é até os dias de hoje a mais\nutilizada pelos cirugiões em decorrência da sua funcionalidade. Ela pode ser descrita assim:","options":{"A":"Segmento I - lobo caudado, segmento II - lobo hepático direito e segmento III - lobo hepático\nesquerdo.","B":"Segmento I - lobo hepático direito, segmento II - lobo hepático esquerdo.","C":"Segmento I - lobo caudado, segmentos II, III, IV - lobo hepático esquerdo e segmentos V, VI, VII\ne VIII - lobo hepático direito.","D":"Segmento I - lobo caudado, segmentos II, III e IV - lobo hepático direito e segmentos V, VI, VII\ne\nVIII - lobo hepático esquerdo.","E":"Segmento I e II - lobo hepático esquerdo e segmentos III e IV - lobo hepático direito."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-161855","number":"161855","sourceNumber":"161855","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"A segmentação hepática descrita por Couinaud em 1957 é até os dias de hoje a mais\nutilizada pelos cirurgiões em decorrência da sua funcionalidade. Ela pode ser descrita assim:","options":{"A":"Segmento I - lobo caudado, segmento II - lobo hépatico direito e segmento III - lobo hepático\nesquerdo.","B":"Segmento I - lobo hepático direito, segmento II - lobo hepático esquerdo.","C":"Segmento I - lobo caudado, segmentos II, III e IV - lobo hepático esquerdo e segmentos V, VI,\nVII e VIII - lobo hepático direito.","D":"Segmento I - lobo caudado, segmentos II, III e IV - lobo hepático direito e segmentos V, VI, VII\ne\nVIII - lobo hepático esquerdo.","E":"Segmento I e II - lobo hepático esquerdo e segmentos III e IV - lobo hepático direito."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-139836","number":"139836","sourceNumber":"139836","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Um paciente, com 25 anos de idade, usuário de drogas injetáveis, procurou o médico\ncom história de icterícia, colúria e adinamia\nhá seis dias. Ao exame físico, constataram-se icterícia e\nhepatomegalia, e os exames laboratoriais revelaram a existência de 800 U/L de AST(TGO), 1.000\nU/L de ALT(TGP) e a presença dos seguintes marcadores virais: HbsAg+, IgM anti-HBc-, IgM\n\nanti-VHA+ e anti-HBc+. Nesse caso, o diagnóstico etiológico é de hepatite aguda:","options":{"A":"pelo VHA e pelo HVB.","B":"inicial pelo VHB.","C":"pelo VHA, em paciente imune para VHB.","D":"pelo VHA, em portador crônico do VHB.","E":"pelo VHB, em portador crônico do VHA."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-84748","number":"84748","sourceNumber":"84748","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"<p>Sobre a Insuficiência Hepática Aguda (IHA), assinale a afirmativa ERRADA: </p>","options":{"A":"O diagnóstico de IHA baseia-se na história e exame físico, além de alterações laboratoriais com\nalargamento do Tempo e Atividade de Protrombina (TAP), hiperbilirrubinemia e INR > OU = a 1,5.","B":"A dosagem do fator VIII pode auxiliar na distinção entre IHA e sepse, pois seus valores são\nnormais na primeira e reduzidos na segunda, respectivamente.","C":"A hepatotoxicidade por fármacos é uma importante causa de IHA, sendo o acetaminofeno o\nprincipal medicamento causador.","D":"A pontuação de MELD (Model of End Stage Liver Disease) vai indicar os pacientes que deverão\nser selecionados para transplante hepático e deve\nser aplicada em todos os pacientes com IHA.","E":"Estes pacientes, por serem imunocomprometidos, com frequência desenvolvem infecções por\nestafilococos, estreptococos, Gram-negativos e fungos como a Candida albicans."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-49932","number":"49932","sourceNumber":"49932","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Com relação às hepatites virais, é INCORRETO afirmar que:","options":{"A":"A transmissão sexual do vírus da Hepatite C é comum, sendo o risco em torno de 10% por ano\nde exposição, para esposas e parceiros sexuais.","B":"A presença do antígeno HBe (HBeAG) reflete alto nível de replicação do vírus da Hepatite B.","C":"O período de incubação da Hepatite B varia de 30 a 150 dias; em média 75 dias.","D":"A dosagem do anti-HBs não é indicada rotineiramente para verificação de soroconversão, a não\nser para aqueles que se expõem\ncontinuadamente à Hepatite B.","E":"Os acidentes de punção em profissionais de saúde representam pequena proporção dos casos\nde contaminação pelas Hepatites B e C."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-36671","number":"36671","sourceNumber":"36671","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Com relação à hepatite B, marque a alternativa INCORRETA.","options":{"A":"O estado de imunidade para a hepatite B é dado pela presença de anti-HBs e anti-HBc total\npositivos (após infecção); anti-HBs\n\nisolado (após vacina).","B":"Na infecção crônica pela hepatite B, temos HbsAg e anti-HBc total positivos (HBeAg ou anti-HBe\npositivo).","C":"São metas do tratamento da hepatite B: suprimir a replicação viral, induzir a remissão da doença\nhepática e eliminação do vírus.","D":"Quadros gripais, astenia, anorexia, cefaleia, pancitopenia, fenômenos autoimunes e alterações\npsiquiátricas estão entre os efeitos\n\ncolaterais do interferon.","E":"Uma vantagem do interferon é a de poder ser feito na vigência de cirrose hepática\ndescompensada, que é uma das contraindicações\n\ndo uso da lamivudina."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-27612","number":"27612","sourceNumber":"27612","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Dentre os pacientes com infecção crônica pelo vírus da hepatite C (VHC), qual\nprovavelmente terá a taxa mais baixa de progressão para fibrose hepática?","options":{"A":"Um homem que adquiriu a infecção pelo VHC com 40 anos e bebe cinco doses de bebida\nalcoólica por dia.","B":"Um homem com infecção por HIV e VHC adquirida há 20 anos.","C":"Uma mulher que adquiriu infecção pelo VHC há mais de 20 anos e não ingere bebida alcoólica.","D":"Uma mulher imunossuprimida pós-transplante hepático com 45 anos de idade.","E":"Uma mulher que adquiriu a infecção pelo VHC aos 43 anos de idade e bebe três doses de\nbebida alcoólica por dia."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-27618","number":"27618","sourceNumber":"27618","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"NÃO se refere à hepatite viral A:","options":{"A":"Forma subclínica na infância.","B":"A imunoprofilaxia passiva é pouco efetiva na prevenção de surtos epidêmicos.","C":"A imunoprofilaxia ativa é segura e efetiva, cuja vacina pode ser aplicada em qualquer idade.","D":"Cronicidadade do quadro.","E":"Até 15% dos pacientes afetados apresentam quadro prolongado ou manifestações recorrentes\npor um período, habitualmente, não superior a\nseis meses."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-10584","number":"10584","sourceNumber":"10584","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Fisioterapeuta de 35 anos de idade, branco, casado. Realizou exames laboratoriais\npara admissão em concurso público. Assintomático.\nExames complementares hemograma,\nglicemia, ureia, gama glutamiltranspeptidade, fosfatase alcalina e aminotransferases normais.\nExame físico nada digno de nota. Encaminhado ao gastroenterologista por apresentar como perfil\nviral HBsAg (+); Anti-HBc IgM (-); Anti-HBc IgG (+); Anti-HBs (-); HBeAg (+); Anti-HBe (-). O perfil\nviral deste paciente sugere:","options":{"A":"Teve hepatite B e está curado","B":"Esta em fase aguda da hepatite B","C":"Tem hepatite crônica B em atividade","D":"Tem hepatite crônica B mutante pré-core","E":"E portador inativo do vírus B"},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-322113","number":"322113","sourceNumber":"322113","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Analise os marcadores virais de Hepatite B, dos quatro pacientes abaixo: Luis; AgHbs\n(+) Anti-Hbc total (+); Jair; AgHbs (+)\nAnti-Hbc total (-); Soraya; AgHbs (-) Anti-Hbc total (+);\nSimone; AgHbs (-) Anti-Hbc total (-); Assinale a alternativa com o estado infeccioso de cada um,\nsegundo esses marcadores.","options":{"A":"Luis; não infectado; Jair; curado; Soraya; infecção aguda; Simone; infecção crônica","B":"Luis; infecção aguda; Jair; infecção crônica; Soraya; não infectada; Simone; curada","C":"Luis; infecção crônica; Jair; infecção recente; Soraya; infecção aguda; Simone; não infectada","D":"Luis; infecção recente; Jair; infecção crônica; Soraya; não infectada; Simone; curada","E":"Luis; infecção crônica; Jair; infecção aguda; Soraya; infecção recente; Simone; não infectada"},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-103187","number":"103187","sourceNumber":"103187","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Homem, 60 anos, em acompanhamento de hepatite por vírus C, vem à consulta de\nrotina com queixa de emagrecimento, febre\nbaixa e dor abdominal em epigástrio com cerca de 2\nmeses de evolução. Assinale a alternativa que contenha os métodos diagnósticos iniciais para este\npaciente.","options":{"A":"Ecografia abdominal e alfa feto proteína.","B":"Antígeno carcino embrionário e alfa feto proteína.","C":"Tomografia computadorizada de abdome e transaminases.","D":"Ecografia abdominal e colangiografia endoscópica retrógrada.","E":"Ressonância magnética de abdome e antígeno carcino embrionário."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-78460","number":"78460","sourceNumber":"78460","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Com referência à abordagem diagnóstica nos pacientes com hepatite aguda, associe a\nsegunda coluna em relação à primeira: I -\nHBsAG+; anti-HBc IgM+; II - HBsAG+; anti-HBc IgM-; III -\nHBsAG-; anti-HAV IgM+; IV - anti-HCV+; V - HBsAG-; anti-HBc IgM+; ( ) Hepatite C; ( ) Hepatite B\naguda; HBsAG abaixo do limiar de identificação; ( ) Hepatite B aguda; ( ) Hepatite B crônica; ( )\nHepatite A aguda. Assinale a alternativa que corresponde à sequência CORRETA da associação.","options":{"A":"I, III, II, IV, V.","B":"II, IV, V, III, I.","C":"II, V, IV, III, I.","D":"IV, V, I, II, III.","E":"IV, V, II, III, I."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-27896","number":"27896","sourceNumber":"27896","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Com respeito à hepatite B, assinale a INCORRETA.","options":{"A":"O período de incubação da hepatite B pode ser longo, durando vários meses, mas ainda neste\nperíodo, o antígeno de superfície da hepatite B já passa a ser detectável no soro do paciente.","B":"O antígeno de superfície da hepatite B torna-se indetectável na fase de recuperação da hepatite\nB.","C":"O anticorpo IgM Anti-HBc desaparece do soro após 6 a 12 meses do início da doença.","D":"O anticorpo Anti-HBs desaparece do plasma após 12 a 24 meses do início da infecção.","E":"A maior parte dos infectados pelo vírus da hepatite B não desenvolve hepatite B Crônica."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-17625","number":"17625","sourceNumber":"17625","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente de 4 anos de idade com história de icterícia por uma semana há quatro\nmeses, com melhora espontânea, tendo sorologia\npositiva para hepatite A. Há 15 dias apresentou\nTGO de 5000, irritabilidade e colúria. Hoje apresenta-se torporosa, bilirrubina total de 35\n(predomínio de direta), TGO de 200, albumina de 2. A melhor conduta para este caso é:","options":{"A":"oxigenoterapia não invasiva e medidas para colestase.","B":"conduta expectante pela melhora das transaminases.","C":"acompanhar periodicamente com novos exames para definir conduta terapêutica.","D":"transfundir albumina, diurético e fenobarbital.","E":"intubação precoce e encaminhar para transplante hepático."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-17676","number":"17676","sourceNumber":"17676","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Com relação à hepatite viral, qual das afirmações abaixo está correta?","options":{"A":"A hepatite crônica B ocorre mais frequentemente do que a hepatite C após a infecção aguda.","B":"A maioria das infecções com ambos os vírus são reconhecidas clinicamente.","C":"Todos os cirurgiões devem ser vacinados para hepatite B.","D":"Cirurgiões infectados com hepatite C devem receber imunoglobulina hiperimune.","E":"Cirrose é mais comum com a hepatite B do que com a C."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-360924","number":"360924","sourceNumber":"360924","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Em relação à Síndrome de Gilbert, assinale a alternativa incorreta:","options":{"A":"É uma afecção benigna de excelente prognóstico.","B":"O diagnóstico definitivo envolve avaliação do DNA para pesquisar a mutação responsável pela\ndoença.","C":"O paciente portador pode ser doador de sangue.","D":"Não necessita de nenhum tratamento específico.","E":"Pode evoluir para cirrose hepática na dependência dos níveis de bilirrubina indireta."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-360946","number":"360946","sourceNumber":"360946","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Jovem de 22 anos ao doar sangue foi informado que possui HBsAg positivo. Na\navaliação posterior com especialista foi\ndemonstrado AgHBe negativo e carva viral em torno de 56\ncopias/mL. O que significa esse resultado?","options":{"A":"Estado de portador.","B":"Hepatite B crônica AgHbe negativo mutante pre core.","C":"Infecção aguda pelo vírus B.","D":"Hepatite B crônica, estado cirrótico.","E":"Não imunizado."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-366100","number":"366100","sourceNumber":"366100","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Quanto à hepatite B é incorreto afirmar que: \"Duncan BB, Schmidt Ml Giugliani ERJ et\nal. Medicina ambulatorial ? Condutas de atenção primária baseada em evidências. 3° edição.\n\nCapitulo 159. 2004. MINISTERIO DA SAUDE. Secretaria de Vigilância em Saúde. Departamento de\nVigilância, Prevenção e Controle das Infecções Sexualmente Transmissíveis, do HV/Aids e das\nHepatites Virais. PROTOCOLO CLINICO E DIRETRIZES TERAPEUTICAS PARA HEPATITE B\nECONFECGOES. Brasília 2027.\"","options":{"A":"A sua cronificação, em termos de frequência, é diretamente proporcional à idade, pois quanto\nmais idoso o paciente, maior a probabilidade de evoluir para a forma crônica","B":"O vírus B da hepatite (HBV) é responsável pela primeira entre as causas de viremia persistente\nem seres humanos","C":"Quanto mais intensa a resposta imunológica do hospedeiro, mais intensa será a lesão\nhepatocelular.","D":"Em pacientes coinfectados, o HIV aumenta a replicação do HBV, levando à forma mais grave de\ndoença hepática.","E":"A biópsia hepática ideal deve ser cilíndrica, não fragmentada, contendo de 10 a 20\nespaços-porta."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-360367","number":"360367","sourceNumber":"360367","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Diante de um paciente com quadro de hepatite fulminante, qual dos marcadores abaixo\nserá utilizado para marcar função hepática e auxiliar na tomada de decisão pela indicação de um\ntransplante (segundo critérios de Kings College).","options":{"A":"Transaminase Glutâmico-Oxalacética (TGO)","B":"Transaminase Glutâmica-Pirúvica (TGP)","C":"Tempo de Protrombina (TAP)","D":"Albumina plasmática"},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-354940","number":"354940","sourceNumber":"354940","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Sobre a hepatite B, o aparecimento de HBsAg pode ocorrer me períodos que vão de\nduas semanas até nove meses. Essa variação\nestá relacionada com: I- número de vírus no inóculo;\nII- modo de transmissão; III- fatores relativos ao hospedeiro. Está (ão) correto(s):","options":{"A":"Todos (I, II, III)","B":"Somente I e II","C":"Somente I e III","D":"Somente II e III"},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-341636","number":"341636","sourceNumber":"341636","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Em relação às hepatites virais, marque a opção INCORRETA:","options":{"A":"Nos infectados por HCV, a cronificação atinge até 85% dos casos e as primeiras duas décadas\napós a transmissão caracterizam-se por\nevolução insidiosa, com ausência de sinais ou sintomas.","B":"A presença de HbsAg não reagente, Anti-Hbc, IgM reagente e anti-HbsAg reagente indica\nvacinação recente contra o HBV (menos de 6 meses).","C":"A transmissão sexual e vertical da hepatite C são raras, quando comparada à da hepatite B,\nentretanto coinfectados pelo HIV apresentam maior risco de transmissão.","D":"Pacientes com fibrose avançada, mesmo após a cura da infecção pelo HCV, podem evoluir com\ncarcinoma hepatocelular."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hepato-hep-1-337914","number":"337914","sourceNumber":"337914","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente com anti-HAV IgG positive desenvolve novo período de icterícia 2 anos após o\nprimeiro episódio. Asssinale a alternativa que pode ser a causa do Quadro atual: (MAXINE A.\nPAPADAKIS, STEPHEN J. MCPHEE, CURRENT MEDICAL DIAGNOSIS AND TREATMENT,\nCHAPTER 16 - 2022)","options":{"A":"Recaída tardia","B":"Evolução para cronicidade","C":"Infecção por outro virus hepatotrófico","D":"Evolução para hepatocarcinoma","E":"Hepatite subaguda"},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-343334","number":"343334","sourceNumber":"343334","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Qual padrão sorológico a seguir indica imunidade naturalmente adquirida de hepatite\nB?","options":{"A":"Anti HBc total + / HBsAg - / Anti HBs +","B":"Anti HBc total - / HBsAg - / Anti HBs +","C":"Anti HBc total + / HBsAg + / Anti HBs -","D":"Anti HBc total - / HBsAg + / Anti HBs -"},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-298740","number":"298740","sourceNumber":"298740","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Em paciente com doença reumatológica autoimune, com indicação de uso de\nimunossupressor, constatou- se, nos exames:\nHBsAg positivo/anti-HBc total positivo terá de\nsubmeter-se a terapia imunossupressora à base de imunobiológico anti-CD20 (Rituximab). Qual é a\nconduta mais adequada?","options":{"A":"Iniciar profilaxia imediatamente ou no momento do início da terapia imunossupressora,\nindependentemente do nível da carga viral.","B":"Diante de transaminases normais, a conduta é observação clínica, apenas.","C":"Iniciar a profilaxia para hepatite B quando surgirem os primeiros sintomas de hepatite.","D":"Monitorar a carga viral (VHB-DNA) mensalmente e iniciar a profilaxia para hepatite com tenofovir\nou entecavir, se houver elevação de 2 log ou >10\nUI/mL."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-313810","number":"313810","sourceNumber":"313810","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente de dezesseis anos, do sexo masculino, apresenta sorologia para hepatite B\ncom os seguintes resultados: HBsAg = negativo; anti-HBs = reagente; anti-HBc IgG = reagente;\nanti-HBc IgM = negativo. Isso significa que esse paciente apresenta:","options":{"A":"Doença, com infecção aguda pelo vírus da hepatite B.","B":"Imunidade, por infecção pelo vírus da hepatite B.","C":"Fase de convalescença, devido à infecção recente pelo vírus da hepatite B.","D":"Imunidade, por resposta vacinal."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-298832","number":"298832","sourceNumber":"298832","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Com relação à hepatite B, assinale a opção CORRETA.","options":{"A":"Uma das formas de transmissão da doença consiste na ingestão de alimentos ou água\ncontaminados.","B":"Trata-se de doença que pode ser assintomática ou sintomática, não existindo, no entanto,\nformas fulminantes.","C":"É uma doença viral, causada por um vírus RNA.","D":"Exames para o diagnóstico incluem métodos sorológicos e de biologia molecular."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-261108","number":"261108","sourceNumber":"261108","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Homem, 25 anos retorna para consulta trazendo o resultado de exames solicitados:\nAssinale qual seria a interpretação correta\npara esses resultados:","options":{"A":"O paciente está susceptível à infecção pelo HBV.","B":"O paciente está imune após infecção pelo HBV.","C":"O paciente está imune após vacinação contra o HBV.","D":"O paciente apresenta infecção recente pelo HBV."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":["question_bank/media/medcurso/medcurso-hepato-hep-1/261108.png"],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-262810","number":"262810","sourceNumber":"262810","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Um paciente procura consultório médico para orientações a respeito da sua sorologia\npara Hepatite B. Ele apresenta Anti-HBs\npositivo, HBSag negativo, Anti HBc Total Positivo, Anti\nHBe negativo. Qual a interpretação correta para esse paciente?","options":{"A":"Trata-se de portador crônico de Hepatite B.","B":"Trata-se de indivíduo vacinado para Hepatite B.","C":"Trata-se de Indivíduo imune por meio de infecção curada para Hepatite B.","D":"Trata-se de Individuo Imune para Hepatite B e Hepatite C por infecção antiga."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hepato-hep-1-228111","number":"228111","sourceNumber":"228111","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Um homem de 56 anos, obeso, está em acompanhamento devido a discreta elevação\ndas transaminases. Apresenta os seguintes exames para\no vírus da hepatite C: anticorpo anti-VHC\npositivo; RNA VHC não detectado. Qual é a interpretação desses dois exames?","options":{"A":"Hepatite C fase aguda.","B":"Infecção passada pelo vírus da hepatite C com cura espontânea.","C":"Infecção crônica pelo vírus da hepatite C em paciente imunocompetente.","D":"Infecção crônica pelo vírus da hepatite C em paciente imunodeprimido.","E":"Hepatite C fase indeterminada."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-241992","number":"241992","sourceNumber":"241992","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Em relação à insuficiência hepática aguda, assinale a alternativa correta:","options":{"A":"Classifica-se somente em forma fulminante;","B":"A causa mais comum é abuso de acetaminofeno;","C":"Diabetes mellitus e obesidade não aumentam o risco de insuficiência hepática aguda;","D":"Pacientes com encefalopatia hepática severa apresentam bom prognóstico;","E":"Todos os casos são tratados com transplante hepático"},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-239114","number":"239114","sourceNumber":"239114","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Mulher, 22 anos, assintomática procura consulta médica para orientação quanto à\nvacinação de hepatite. Traz exames realizados recentemente com anti-HBs negativo, HBsAg\nnegativo, anti-HCV negativo, anti-HVA IgM negativo e anti-HVA positivo. Nesse caso,","options":{"A":"Não há necessidade de vacinar-se. Está protegida para as hepatites virais.","B":"Está protegida de hepatite A e B, mas suscetível à hepatite C. Deve ser orientada a procurar\nUBS para vacinação contra hepatite C.","C":"É suscetível às três formas de hepatite. Deve ser orientada a procurar UBS para vacinação\ncontra hepatite B.","D":"Está protegida de hepatite A, mas suscetível às hepatites B e C. Deve ser orientada a procurar\nUBS para vacinação contra hepatite B."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-238458","number":"238458","sourceNumber":"238458","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Um paciente vem para consulta médica solicitando orientação quanto a sua sorologia\npara hepatites. Nos seus exames apresenta os\nseguintes resultados: Anti HCV negativo, HBsAg\nnegativo, Anti HBs postivo, Anti HBc IgG positivo, Anti HAV IgG positivo. Qual seria a interpretação\nCORRETA da sorologia desse paciente?","options":{"A":"O paciente é portador de hepatite C e de Hepatite B, e imune a Hepatite A.","B":"O paciente e portador de Hepatite C e imune a Hepatite B e Hepatite A.","C":"O paciente é portador de hepatite A e B, e está susceptível a hepatite C","D":"O paciente foi vacinado para hepatite B, está imune a hepatite A e susceptível a hepatite C.","E":"O paciente está imune a hepatite A e B, e está susceptível a Hepatite C."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-230434","number":"230434","sourceNumber":"230434","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Em relação às endocrinopatias associadas à infecção crônica pelo vírus da hepatite C\n(VHC), considere as afirmativas a seguir. I. A infecção crônica pelo VHC acarreta aumento da\nresistência à insulina e do risco de diabetes mellitus tipo 2. II. A presença de diabetes mellitus\ntipo\n2, nos pacientes portadores de hepatite pelo vírus C, aumenta o risco de evolução para cirrose\nhepática. III. A infecção crônica pelo VHC está associada ao aumento do risco de hipotireoidismo\npor fibrose tireoidiana de etiologia não imunológica. IV. Não há evidências de aumento do risco de\ncarcinoma papilífero na doença tireoidiana relacionada à infecção crônica pelo VHC. Assinale a\nalternativa correta.","options":{"A":"Somente as afirmativas I e II são corretas.","B":"Somente as afirmativas I e IV são corretas.","C":"Somente as afirmativas III e IV são corretas.","D":"Somente as afirmativas I, II e III são corretas.","E":"Somente as afirmativas II, III e IV são corretas."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-209974","number":"209974","sourceNumber":"209974","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Síndrome hereditária autossômica recessiva, caracterizada por hiperbilirrubinemia\nnão-conjugada intensa (>20 mg%) desde os primeiros\nanos de vida. A maioria desses pacientes\nmore nos primeiros 15 meses em consequência de encefalopatia bilirrubínica. Raros são os\npacientes que apresentam as primeiras manifestações neurológicas na adolescência. A patogenia\nconsiste na ausência total da glicuronidação da bilirrubina em virtude de uma completa falta da\n\natividade da B-UGT. Nesses pacientes há também uma menor atividade para a glicuronidação dos\nfenóis. (LIMA JP, LIMA JCR, LIMA L, HORNOS AP, MARQUES DL. Icterícia em Coelho 3ª edição\nAparelho Digestivo - Clínica e Cirurgia 2005).","options":{"A":"Crigler-Najjar tipo I","B":"Crigler-Najjar tipo II","C":"Crigler-Najjar tipo III","D":"Crigler-Najjar Tipo IV","E":"Nenhuma das alternativas acima está correta"},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-205729","number":"205729","sourceNumber":"205729","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente assintomático recebe o resultado dos seguintes exames colhidos numa\nconsulta eletiva: HBs Ag: não reagente; Anti HBc\ntotal: reagente; Anti HBc IgM: não reagente; Anti\nHBe: reagente; Anti HBs: reagente; Anti HCV: não reagente. O diagnóstico é:","options":{"A":"Infecção passada pela hepatite B e imunidade para a mesma.","B":"Hepatite C crônica.","C":"Final de fase aguda da hepatite B ou hepatite B crônica.","D":"Período de janela imunológica da hepatite B.","E":"Hepatite B aguda."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-205671","number":"205671","sourceNumber":"205671","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Qual das hepatites apresenta frequentemente na sua fase prodrômica manifestações\nsemelhantes a doença do soro, composta por: dor articular, febre e alterações cutâneas tipo\nurticariformes e maculopapulares?","options":{"A":"Hepatite A.","B":"Hepatite B.","C":"Hepatite C.","D":"Hepatite D.","E":"Hepatite E."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-217984","number":"217984","sourceNumber":"217984","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"André, 34 anos, apresentou resultado de HBsAg reagente nos seus exames\nsorológicos anuais. Não tinha queixas. Seu\nmédico de família solicitou marcadores sorológicos de\nhepatite B e encontrou o seguinte resultado: anti-HBcIgM positivo com título baixo, anti-HBcIgG\npositivo, HBeAg negativo, anti-HBe positivo, anti-HBs negativo. Assinale a alternativa que\napresenta a interpretação do status da infecção de hepatite B em André.","options":{"A":"Imunidade ao vírus da hepatite B.","B":"Hepatite aguda com replicação viral.","C":"Hepatite crônica em fase de convalescença.","D":"Hepatite crônica com presença de infecciosidade."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-205704","number":"205704","sourceNumber":"205704","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Anatomicamente o fígado é dividido pelo ligamento falciforme em lobos direito e\nesquerdo, enquanto que funcionalmente ele é dividido em fígado direito e esquerdo\ntransversalmente pelos ramos portais e longitudinalmente pelas veias hepáticas. Dado estes\nconhecimentos responda as seguintes questões:","options":{"A":"O fígado direito corresponde aos segmentos I, II, V e VI.","B":"O fígado direito corresponde aos segmentos I, IV,V,VI e VII.","C":"O Fígado esquerdo corresponde aos segmentos II, III e VII","D":"O fígado direito corresponde aos segmentos V,VI,VII e VIII.","E":"O Fígado direito corresponde os segmentos IV, V, VI e VII."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-199447","number":"199447","sourceNumber":"199447","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente de 6 anos, sexo feminino, é atendida no pronto atendimento com história de\nfebre e aparecimento de icterícia de pele\ne escleras há 3 dias. Mãe refere colúria, nega acolia e\nrefere que há 2 dias a filha está com o ritmo de sono alterado, ?que vem trocando o dia pela noite?.\nNega sonolência. Ao exame físico, bom estado geral, corada, hidratada, orientada, com icterícia de\npele e escleras 2+/4+. Campos pleuropulmonares e pré-cordio sem alterações. Abdome plano,\nflácido, ruídos hidroaéreos normais, indolor à palpação superficial e profunda. Fígado palpável a 3\ncm do rebordo costal direito, na linha hemiclavicular e a 4 cm do apêndice xifoide, de consistência\nnormal. Baço não palpável, Traube livre. Com base no caso acima, considere as seguintes\nafirmativas: 1. O diagnóstico da paciente é hepatite aguda, uma síndrome clínica que se encontra\nassociada a várias etiologias, estando recomendado o acompanhamento ambulatorial, com exames\nde rotina e retorno em 48 horas. 2. O tempo de protrombina deve ser solicitado com urgência, para\no reconhecimento precoce de insuficiência hepática aguda. 3. A paciente deve ser internada em\nhospital especializado em transplante hepático. 4. Interrogatório minucioso sobre medicamentos\nprescritos à paciente afastam causa tóxico-medicamentosa para o caso. Assinale a alternativa\ncorreta.","options":{"A":"Somente a afirmativa 2 é verdadeira.","B":"Somente as afirmativas 1 e 4 são verdadeiras.","C":"Somente as afirmativas 2 e 3 são verdadeiras.","D":"Somente as afirmativas 1, 3 e 4 são verdadeiras.","E":"As afirmativas 1, 2, 3 e 4 são verdadeiras."},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-210046","number":"210046","sourceNumber":"210046","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Homem, 33 anos, procurou um banco de sangue para doação para um familiar\nacidentado. Sua doação foi negada devido à\nalterações nos exames de hepatite B. Foi\nencaminhado a uma unidade de saúde e o clínico geral solicitou as seguintes sorologias com os\nseguintes resultados: HbsAg (+), Anti-HBs ( - ), Anti-HBc IgM ( - ), Anti-HBc IgG (+), HbeAg (+),\nAnti-Hbe ( - ). Qua a interpretação adequada para estes resultados pelo considerando a infecção\npelo HBV: (LEE GOLDMAN, MD AND ANDREW I. SCHAFER, MD . Goldman Cecil Medicina\nSEÇÃO XXXIII, DOENÇAS INFECCIOSAS 24.Ed? 2014.).","options":{"A":"aguda de baixa infectividade","B":"aguda de alta infectividade","C":"crônica de alta infectividade","D":"crônica de baixa infectividade","E":"aguda tardia de baixa infectividade"},"answer":"C","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-178993","number":"178993","sourceNumber":"178993","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Qual a alternativa CORRETA relacionado infecção viral com a etiologia tumoral?\n\n1 - Linfoma; 2 - Câncer de colo de útero; 3 - Sarcoma de Kaposi; 4 - Câncer Hepático; 5 - Câncer\nde pele. A - Herpes vírus humano B; B - Vírus\nda hepatite C; C - Epstein-Barr Vírus; D -\nPapilomavírus; E - Vírus da imunodeficiência adquirida. (MALE,BROSTOFF, ROTH,ROITT-\nImmunology 8thed Elsevier2013 section 4 chapter22)","options":{"A":"1 ? E, 2 ? B, 3 ? E, 4 ? A, 5 ? D","B":"1 ? E, 2 ? C, 3 ? A, 4 ? B, 5 ? D","C":"1 ? C, 2 ? D, 3 ? A, 4 ? B, 5 ? E","D":"1 ? C, 2 ? D, 3 ? E, 4 ? B, 5 ? E","E":"1 ? E, 2 ? C, 3 ? B, 4 ? A, 5 ? E"},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-hepato-hep-1-183359","number":"183359","sourceNumber":"183359","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Alguns testes laboratoriais têm especial importância para avaliar pacientes com\ndoenças hepáticas. Em relação aos testes de função\nhepática assinale a alternativa correta:","options":{"A":"O tempo de protrombina é a medida isolada mais útil e eficaz para avaliar a função de síntese\nhepática devido a meia-vida curta dos fatores de coagulação produzidos no fígado.","B":"A albumina sérica é um bom indicador de severidade da doença hepática aguda pois é\nexclusivamente sintetizada pelos hepatócitos.","C":"A elevação dos níveis de fosfotase alcalina em três vezes ou mais significa obrigatoriamente\numa doença hepática colestática.","D":"TGO e TGP elevadas são indicadores sensíveis de dano hepático agudo, sendo TGO mais\nsensível que a TGP para lesões hepáticas."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-184323","number":"184323","sourceNumber":"184323","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Quanto aos marcadores sorológicos da Hepatite B é correto afirmar:","options":{"A":"HBsAg positivo, HBeAG positivo, Anti-Hbc IgM positivo, Anti-HBc IgG positivo, Anti- HBe\nnegativo, Anti-HBs negativo encontra-se na fase de hepatite crônica.","B":"HBsAg negativo, HBeAG negativo, Anti-Hbc IgM negativo, Anti-HBc IgG negativo, Anti-HBe\nnegativo, Anti-HBs positivo encontra-se na fase de imunidade por infecção passada.","C":"HBsAg positivo, HBeAG positivo, Anti-Hbc IgM negativo, Anti-HBc IgG positivo, Anti-HBe\npositivo, Anti-HBs positivo encontra-se na fase aguda da infecção.","D":"HBsAg positivo, HBeAG negativo, Anti-Hbc IgM negativo, Anti-HBc IgG positivo, Anti-HBe\nnegativo, Anti-HBs negativo encontra-se na fase de hepatite crônica.","E":"HBsAg positivo, HBeAG negativo, Anti-Hbc IgM negativo, Anti-HBc IgG negativo, Anti-HBe\nnegativo, Anti-HBs negativo encontra-se na fase de convalescência."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-178996","number":"178996","sourceNumber":"178996","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Homem, 32 anos, assintomático, teve sua doação de sangue recusada no hemocentro\ndevido aos seguintes resultados de exames:\nHBsAg negativo, Anti-HBcAg IgG positivo, Anti-HBsAg\npositivo. Assinale a alternativa que melhor analisa o perfil sorológico do paciente e a conduta\ntomada pelo hemocentro (Medicina Interna - Harrison - 19.ed. Parte 14, Seção 2.)","options":{"A":"Hepatite B prévia e resolvida. A doação foi recusada por razão de natureza epidemiológica","B":"Portador crônico do vírus B. A doação foi recusada para prevenir a transmissão desta doença\npara o preceptor","C":"Hepatite B aguda em resolução. A doação foi recusada para prevenir a transmissão desta\ndoença para o\n\npreceptor.","D":"Não é possível definir as condições atuais da doença com apenas os exames solicitados. O\npaciente deve ser encaminhado ao ambulatório e outras sorologias (anti-HBe e HBeAg) devem ser\nsolicitadas para melhor elucidação do quadro.","E":"Vacinação prévia contra hepatite B. A doação não deveria ter sido recusada."},"answer":"A","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-160092","number":"160092","sourceNumber":"160092","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Josefa, 34 anos, está grávida há dois meses e, muito preocupada, durante a consulta\ncom o médico da família, em sua UBS,\nquestionou sobre os exames de hepatite. Sua preocupação\nera porque no ano passado tinha apresentado um quadro de icterícia com diarréia, embora não\ntenha relatado contato com sangue. Sabendo da preocupação em relação à hepatite B, assinale\nabaixo a questão mais CORRETA.","options":{"A":"O anti-HBs (anticorpo superficial do vírus da hepatite B) em altos níveis identifica imunidade. É\num marcador que serve como resposta vacinal.","B":"O HBsAg (antígeno de superfície do vírus da hepatite B) é o primeiro marcador a aparecer,\nmuitas vezes antes da sintomatologia de\nhepatite, estando presente no portador crônico.","C":"O HBsAg presente em mulheres grávidas representa um risco de transmissão vertical.","D":"O anti-HBcIgM (antígeno core do vírus hepatite B) é um marcador de infecção aguda ou\nsubaguda.","E":"Todas as respostas estão corretas."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-151225","number":"151225","sourceNumber":"151225","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente de 56 anos tem consulta na unidade básica de saúde levando em mãos o\nexame anti-HCV reagente. Encontra-se assintomático e realizando suas atividades laborais\nnormalmente. Qual hipótese diagnóstica NÃO será possível em relação ao caso descrito?","options":{"A":"O paciente possuir hepatite C crônica.","B":"O paciente possuir hepatite C aguda.","C":"O paciente possuir hepatite C curada espontaneamente.","D":"O paciente possuir hepatite C curada com terapia medicamentosa.","E":"O paciente estaria imune contra a hepatite C."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-153141","number":"153141","sourceNumber":"153141","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Analise os marcadores virais a seguir: I. AgHBs (+), anti-HBc total (+); II. AgHBs (+),\nanti-HBc total (-); III. AgHBs (-), anti-HBc total (+); IV. AgHBs (-), anti-HBc total (-). Após\nanálise, é\nCORRETO afirmar que:","options":{"A":"Não infectado; cura; infecção aguda; infecção crônica.","B":"Infecção aguda; infecção crônica; não infectado; cura.","C":"Infecção crônica; infecção recente; infecção aguda; não infectado.","D":"Infecção recente; infecção crônica; não infectado; cura.","E":"Infecção crônica; infecção aguda; infecção recente; não infectado."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-141130","number":"141130","sourceNumber":"141130","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente de 25 anos vem para a consulta no Posto de Saúde trazendo os seguintes\nexames: anti-HBe e anti-HB-c-IgG reagentes, assintomática, sem histórico prévio de doença\nhepática. Diante destas sorologias relacionadas ao vírus da hepatite B as seguinte hipóteses\ndiagnósticas são possíveis, antes da avaliação laboratorial complementar, EXCETO:","options":{"A":"a paciente pode ser portadora de vírus da hepatite B.","B":"pode significar que a paciente teve contato e conseguiu fazer o clareamento espontâneo do\nvírus da hepatite B.","C":"pode significar hepatite B crônica com baixa replicação viral.","D":"se esta paciente apresenta o HbsAg não reagente e o HBV-DNA quantitativo por PCR\nindetectável significa que a paciente nunca teve contato com o vírus da hepatite B.","E":"não posso considerá-la imunizada através de vacinação contra o vírus da hepatite B."},"answer":"D","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-128955","number":"128955","sourceNumber":"128955","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente masculino, 47 anos de idade, apresenta confusão mental de início recente\nassociada à icterícia. Refere que ingeriu\ncogumelos há aproximadamente 30 horas, apresentando\nem seguida vômitos e diarreia. Negou uso prévio de medicaçõs. Ao exame físico encontrava-se\nictérico, desorientado, com presença de asterixis. Nos exames laboratoriais apresentava bilirrubina\ntotal = 20 mg/dl, TGP = 1890 UI, TGO = 1498 UI; TAP=37% (INR = 4,7), Creatinina = 2,3,\n\ngasometria arterial com pH=7,46, anti-HAV IgM(-) e IgG (+), HBsAg (-), anti-HBs (+), anti-HBc (+),\nPCR-RNA vírus da hepatite C (-). Qual a principal hipótese diagnóstica e quais os dois fatores de\ngravidade deste caso clínico?","options":{"A":"Insuficiência hepática fulminante induzida por intoxicação por cogumelo, pH arterial = 7,46 e\ndistúrbio da coagulação.","B":"Insuficiência hepática fulminante induzida por intoxicação por cogumelos, distúrbio de\ncoagulação e encefalopatia hepática.","C":"Insuficiência hepática fulminante causada pelo vírus B, encefalopatia hepática e icterícia.","D":"Insuficiência hepática fulminante causada pelo vírus A, transaminases maiores que 10x o limite\nsuperior da normalidade e distúrbio de coagulação.","E":"Insuficiência hepática fulminante causada pelo vírus B, encefalopatia hepática e alargamento do\nTAP."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-130402","number":"130402","sourceNumber":"130402","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Um homem de 35 anos lhe procurou para realizar exames laboratoriais pré-nupciais.\nApós sete dias, ele voltou à consulta com os\nresultados para você analisá-los. O paciente estava\nassintomático e o exame físico era normal. Dentre\n\nseus exames, destacava-se a positivação do Anti-HBs (reagente) e do Anti-HBc total (reagente).\nFrente a esse quadro, é CORRETO afirmar:","options":{"A":"Você explica para o paciente que está com hepatite B crônica, mas que precisa de mais exames\n(IgG e IgM) para confirmar a cronificação\ne deverá ser encaminhado ao especialista para\ntratamento ou seguimento.","B":"Você explica que o paciente não tem hepatite B, e que o resultado do exame é o padrão de uma\npessoa que recebeu a vacina para hepatite\nB.","C":"O paciente apresenta uma resposta vacinal para hepatite B e hepatite C crônica, que deverá ser\nconfirmada por PCR (carga viral) para HCV.","D":"Você explica para o paciente que está com hepatite B e C crônica, mas que precisa de mais\nexames (IgG e IgM) para confirmar a cronificação e deverá ser encaminhado ao especialista para\ntratamento ou seguimento.","E":"Você explica para o paciente que ele teve hepatite B no passado e que já se apresenta curado,\nnão tendo indicação de vacina e nem\ntratamento."},"answer":"E","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-131017","number":"131017","sourceNumber":"131017","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Preencha as lacunas e assinale a alternativa correta. As crioglobulinas mistas podem\nser encontradas durante o processo de infecção\npelo . O papel causal deste vírus na\npatogênese de crioglobulinas é provado pela grande quantidade de e proteínas virais\ncompletas no crioprecipitado. São mais frequentes as alterações cutâneas seguidas por\nneuropatias e .","options":{"A":"Vírus HIV, anticorpos virais, pneumopatias","B":"Vírus da Hepatite C, RNA viral, glomerulonefrites","C":"Vírus HTLV I, DNA pró-viral, leucemias","D":"Vírus Epstein Barr, DNA viral, linfoma","E":"Vírus da Dengue, RNA viral tipo 2, doença renal"},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-hepato-hep-1-101091","number":"101091","sourceNumber":"101091","collectionBlock":"medcurso:medcurso-hepato-hep-1","collectionLabel":"Medcurso · HEP 1","documentBlock":"","area":"Hepatologia","specialty":"Hepatologia","topic":"HEP 1","subtopic":"","stem":"Paciente com 28 anos queixa-se de náuseas, vômitos, fraqueza e mialgia que iniciaram\nhá 10 dias, com febre até 39ºC aferida. Há 2\ndias, passou a apresentar icterícia, colúria e acolia e\nqueixa de dor no hipocôndrio direito, contínua, com sensação de peso. Nega uso de álcool de\nforma abusiva, informação confirmada pela esposa presente à consulta. Nega uso de medicações,\nchás ou ervas, com exceção do uso recente de paracetamol 1 g/24h para dor e febre. Ao exame\nfísico, apresenta icterícia intensa, dor à palpação de hipocôndrio direito e hepatimetria de 16 cm.\n\nOs exames complementares demonstram: ALT = 2.352 UI/ml; AST = 1.839 UI/ml; BT = 24 mg/dl;\nBD = 19,7 mg/dl; RNI = 1,2. Sorologias\ndemonstram HBsAG positivo; anti-HBc IgM positivo; HBeAG\npositivo; anti-HBe negativo; anti-HBs negativo; anti-HAV total positivo; anti-HCV negativo; FAN\nnegativo; anticorpo antimúsculo liso 1:80. Qual o diagnóstico desta situação clínica?","options":{"A":"Hepatite aguda A.","B":"Hepatite aguda B.","C":"Hepatite aguda C.","D":"Hepatite autoimune.","E":"Hepatite medicamentosa."},"answer":"B","source":"Hepato/HEP 1/HEP 1.txt","sourceLabel":"Medcurso · HEP 1","images":[],"optionImages":{},"commentImages":[],"tags":["Hepatologia","HEP 1","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
